@Composable
fun Modifier.greenGlowBorder(
    enabled: Boolean = true,
    shape: Shape = RoundedCornerShape(12.dp),
    glowColor: Color = MaterialTheme.colorScheme.primary
): Modifier {
    if (!enabled) return this
    return this.border(width = 1.dp, color = glowColor.copy(alpha = 0.5f), shape = shape)
}

@Composable
fun Modifier.redGlowBorder(
    enabled: Boolean = true,
    shape: Shape = RoundedCornerShape(12.dp),
    glowColor: Color = MaterialTheme.colorScheme.primary
): Modifier = greenGlowBorder(enabled = enabled, shape = shape, glowColor = glowColor)

