@OptIn(ExperimentalAnimationApi::class)
@Composable
fun AnimatedCrossRefSection(
    selectedBook: String,
    selectedChapter: Int,
    readerTheme: String,
    readerThemeBgColor: Color,
    readerThemeVerseNumColor: Color,
    readerThemeSubtextColor: Color,
    viewModel: BibleViewModel,
    context: Context
) {
    val coroutineScope = rememberCoroutineScope()
    val crossReferences = remember(selectedBook, selectedChapter) {
        getChapterCrossReferences(selectedBook, selectedChapter)
    }

    var selectedCategory by remember { mutableStateOf("ALL") }
    var viewMode by remember { mutableIntStateOf(0) } // 0: Carousel Slider, 1: Vertical Cards
    var previewCrossRef by remember { mutableStateOf<ChapterCrossRef?>(null) }
    var expandedRef by remember { mutableStateOf<String?>(null) }

    val categories = remember(crossReferences) {
        listOf("ALL") + crossReferences.map { it.category.uppercase() }.distinct()
    }

    val filteredRefs = remember(crossReferences, selectedCategory) {
        if (selectedCategory == "ALL") crossReferences
        else crossReferences.filter { it.category.equals(selectedCategory, ignoreCase = true) }
    }

    val carouselState = rememberLazyListState()

    // Pulsing Link Icon Animation
    val infiniteTransition = rememberInfiniteTransition(label = "cross_ref_pulse")
    val pulseAlpha by infiniteTransition.animateFloat(
        initialValue = 0.55f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(1200, easing = LinearEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "pulseAlpha"
    )

    val iconScale by infiniteTransition.animateFloat(
        initialValue = 0.95f,
        targetValue = 1.08f,
        animationSpec = infiniteRepeatable(
            animation = tween(1400, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "iconScale"
    )

    Spacer(modifier = Modifier.height(20.dp))
    HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f))
    Spacer(modifier = Modifier.height(16.dp))

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .testTag("chapter_cross_references_section")
    ) {
        // Section Title Bar with Animated Icon & View Mode Switcher
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.weight(1f)
            ) {
                Surface(
                    shape = CircleShape,
                    color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = pulseAlpha),
                    modifier = Modifier.size(36.dp).scale(iconScale)
                ) {
                    Box(contentAlignment = Alignment.Center) {
                        Icon(
                            imageVector = Icons.Default.LinearScale,
                            contentDescription = "Cross References Link",
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                }
                Spacer(modifier = Modifier.width(10.dp))
                Column {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            text = "Connected Passages 🔗",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                        Spacer(modifier = Modifier.width(6.dp))
                        Surface(
                            shape = RoundedCornerShape(10.dp),
                            color = MaterialTheme.colorScheme.primary.copy(alpha = 0.12f)
                        ) {
                            Text(
                                text = "${filteredRefs.size}",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                            )
                        }
                    }
                    Text(
                        text = "Slide & explore related scriptures across Testaments.",
                        style = MaterialTheme.typography.bodySmall,
                        fontSize = 11.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                    )
                }
            }

            // View Mode Selector (Carousel Slider vs Vertical Cards)
            Surface(
                shape = RoundedCornerShape(20.dp),
                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.7f),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.2f))
            ) {
                Row(
                    modifier = Modifier.padding(3.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    // Carousel option
                    val isCarousel = viewMode == 0
                    Surface(
                        shape = RoundedCornerShape(16.dp),
                        color = if (isCarousel) MaterialTheme.colorScheme.primary else Color.Transparent,
                        modifier = Modifier
                            .clip(RoundedCornerShape(16.dp))
                            .clickable { viewMode = 0 }
                    ) {
                        Row(
                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(
                                imageVector = Icons.Default.ViewCarousel,
                                contentDescription = "Carousel View",
                                tint = if (isCarousel) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant,
                                modifier = Modifier.size(14.dp)
                            )
                            if (isCarousel) {
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Slide", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onPrimary)
                            }
                        }
                    }
                    // List option
                    val isList = viewMode == 1
                    Surface(
                        shape = RoundedCornerShape(16.dp),
                        color = if (isList) MaterialTheme.colorScheme.primary else Color.Transparent,
                        modifier = Modifier
                            .clip(RoundedCornerShape(16.dp))
                            .clickable { viewMode = 1 }
                    ) {
                        Row(
                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(
                                imageVector = Icons.Default.ViewStream,
                                contentDescription = "Stack View",
                                tint = if (isList) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant,
                                modifier = Modifier.size(14.dp)
                            )
                            if (isList) {
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Cards", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onPrimary)
                            }
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(12.dp))

        // Category Filter Chips Row
        if (categories.size > 2) {
            LazyRow(
                horizontalArrangement = Arrangement.spacedBy(6.dp),
                modifier = Modifier.fillMaxWidth().padding(bottom = 10.dp)
            ) {
                items(categories) { cat ->
                    val isSelected = selectedCategory == cat
                    val bgColor by animateColorAsState(
                        targetValue = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                        animationSpec = tween(200),
                        label = "bgColor"
                    )
                    val contentColor by animateColorAsState(
                        targetValue = if (isSelected) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant,
                        animationSpec = tween(200),
                        label = "contentColor"
                    )

                    Surface(
                        shape = RoundedCornerShape(16.dp),
                        color = bgColor,
                        border = BorderStroke(1.dp, if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline.copy(alpha = 0.15f)),
                        modifier = Modifier
                            .clip(RoundedCornerShape(16.dp))
                            .clickable { selectedCategory = cat }
                    ) {
                        Text(
                            text = cat,
                            fontSize = 10.sp,
                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                            color = contentColor,
                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp)
                        )
                    }
                }
            }
        }

        // Animated Content Area (Carousel Slider vs Card List)
        AnimatedContent(
            targetState = viewMode,
            transitionSpec = {
                if (targetState > initialState) {
                    (slideInHorizontally { width -> width } + fadeIn()).togetherWith(slideOutHorizontally { width -> -width } + fadeOut())
                } else {
                    (slideInHorizontally { width -> -width } + fadeIn()).togetherWith(slideOutHorizontally { width -> width } + fadeOut())
                }
            },
            label = "cross_ref_view_mode"
        ) { mode ->
            if (filteredRefs.isEmpty()) {
                Card(
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)),
                    shape = RoundedCornerShape(14.dp),
                    modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp)
                ) {
                    Box(modifier = Modifier.fillMaxWidth().padding(20.dp), contentAlignment = Alignment.Center) {
                        Text("No cross-references found for this category.", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                    }
                }
            } else if (mode == 0) {
                // Carousel Slider Layout
                Column(modifier = Modifier.fillMaxWidth()) {
                    LazyRow(
                        state = carouselState,
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        itemsIndexed(filteredRefs) { index, crossRef ->
                            val isExpanded = expandedRef == crossRef.reference
                            Card(
                                colors = CardDefaults.cardColors(
                                    containerColor = if (readerTheme != "Light") readerThemeBgColor.copy(alpha = 0.9f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.55f)
                                ),
                                shape = RoundedCornerShape(16.dp),
                                border = BorderStroke(
                                    width = 1.dp,
                                    color = MaterialTheme.colorScheme.primary.copy(alpha = 0.3f)
                                ),
                                modifier = Modifier
                                    .width(290.dp)
                                    .testTag("cross_ref_card_${crossRef.reference.replace(" ", "_").replace(":", "_")}")
                            ) {
                                Column(
                                    modifier = Modifier
                                        .padding(14.dp)
                                        .animateContentSize()
                                ) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Surface(
                                            shape = RoundedCornerShape(6.dp),
                                            color = MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)
                                        ) {
                                            Text(
                                                text = crossRef.category.uppercase(),
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = MaterialTheme.colorScheme.primary,
                                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                            )
                                        }

                                        // Slide index badge
                                        Surface(
                                            shape = CircleShape,
                                            color = MaterialTheme.colorScheme.surface.copy(alpha = 0.6f)
                                        ) {
                                            Text(
                                                text = "${index + 1}/${filteredRefs.size}",
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.SemiBold,
                                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                            )
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(6.dp))

                                    Text(
                                        text = crossRef.reference,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 15.sp,
                                        color = if (readerTheme != "Light") readerThemeVerseNumColor else MaterialTheme.colorScheme.primary
                                    )

                                    Text(
                                        text = "• ${crossRef.theme}",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = MaterialTheme.colorScheme.secondary,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )

                                    Spacer(modifier = Modifier.height(6.dp))

                                    Surface(
                                        shape = RoundedCornerShape(10.dp),
                                        color = MaterialTheme.colorScheme.background.copy(alpha = 0.5f),
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clickable {
                                                expandedRef = if (isExpanded) null else crossRef.reference
                                            }
                                    ) {
                                        Text(
                                            text = "“${crossRef.snippet}”",
                                            fontSize = 11.5.sp,
                                            fontStyle = FontStyle.Italic,
                                            fontFamily = FontFamily.Serif,
                                            lineHeight = 16.sp,
                                            maxLines = if (isExpanded) 10 else 3,
                                            overflow = TextOverflow.Ellipsis,
                                            color = if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.85f),
                                            modifier = Modifier.padding(8.dp)
                                        )
                                    }

                                    Spacer(modifier = Modifier.height(10.dp))

                                    // Action Buttons Row
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        // Quick Preview Slide Button
                                        OutlinedButton(
                                            onClick = { previewCrossRef = crossRef },
                                            shape = RoundedCornerShape(12.dp),
                                            contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp),
                                            modifier = Modifier.weight(1f).height(32.dp)
                                        ) {
                                            Icon(Icons.Default.RemoveRedEye, contentDescription = null, modifier = Modifier.size(12.dp))
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text("Preview", fontSize = 10.5.sp, fontWeight = FontWeight.SemiBold)
                                        }

                                        // Instant Jump Button
                                        Button(
                                            onClick = {
                                                viewModel.selectBook(crossRef.targetBook)
                                                viewModel.selectChapter(crossRef.targetChapter)
                                                viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                                                viewModel.logReadingHistory(crossRef.targetBook, crossRef.targetChapter)
                                            },
                                            shape = RoundedCornerShape(12.dp),
                                            contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp),
                                            modifier = Modifier.weight(1f).height(32.dp)
                                        ) {
                                            Text("Jump", fontSize = 10.5.sp, fontWeight = FontWeight.Bold)
                                            Spacer(modifier = Modifier.width(2.dp))
                                            Icon(Icons.AutoMirrored.Filled.ArrowForward, contentDescription = null, modifier = Modifier.size(12.dp))
                                        }
                                    }
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))

                    // Animated Slide Indicator & Navigation Arrows Bar
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        IconButton(
                            onClick = {
                                val currentFirst = carouselState.firstVisibleItemIndex
                                if (currentFirst > 0) {
                                    coroutineScope.launch {
                                        carouselState.animateScrollToItem(currentFirst - 1)
                                    }
                                }
                            },
                            modifier = Modifier.size(28.dp)
                        ) {
                            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Previous Slide", tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(16.dp))
                        }

                        // Slide Indicator Dots
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            filteredRefs.indices.forEach { idx ->
                                val isCurrent = carouselState.firstVisibleItemIndex == idx
                                val dotWidth by animateDpAsState(
                                    targetValue = if (isCurrent) 20.dp else 6.dp,
                                    animationSpec = tween(250),
                                    label = "dotWidth"
                                )
                                val dotColor by animateColorAsState(
                                    targetValue = if (isCurrent) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline.copy(alpha = 0.3f),
                                    animationSpec = tween(250),
                                    label = "dotColor"
                                )

                                Surface(
                                    shape = CircleShape,
                                    color = dotColor,
                                    modifier = Modifier
                                        .height(6.dp)
                                        .width(dotWidth)
                                        .clickable {
                                            coroutineScope.launch {
                                                carouselState.animateScrollToItem(idx)
                                            }
                                        }
                                ) {}
                            }
                        }

                        IconButton(
                            onClick = {
                                val currentFirst = carouselState.firstVisibleItemIndex
                                if (currentFirst < filteredRefs.size - 1) {
                                    coroutineScope.launch {
                                        carouselState.animateScrollToItem(currentFirst + 1)
                                    }
                                }
                            },
                            modifier = Modifier.size(28.dp)
                        ) {
                            Icon(Icons.AutoMirrored.Filled.ArrowForward, contentDescription = "Next Slide", tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(16.dp))
                        }
                    }
                }
            } else {
                // Vertical Stacked Cards View
                Column(
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    filteredRefs.forEachIndexed { index, crossRef ->
                        AnimatedVisibility(
                            visible = true,
                            enter = slideInVertically(initialOffsetY = { 40 * (index + 1) }) + fadeIn(animationSpec = tween(300 + index * 50))
                        ) {
                            Card(
                                onClick = {
                                    viewModel.selectBook(crossRef.targetBook)
                                    viewModel.selectChapter(crossRef.targetChapter)
                                    viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                                    viewModel.logReadingHistory(crossRef.targetBook, crossRef.targetChapter)
                                },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("cross_ref_card_${crossRef.reference.replace(" ", "_").replace(":", "_")}"),
                                colors = CardDefaults.cardColors(
                                    containerColor = if (readerTheme != "Light") readerThemeBgColor.copy(alpha = 0.8f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.45f)
                                ),
                                shape = RoundedCornerShape(14.dp),
                                border = BorderStroke(
                                    width = 1.dp,
                                    color = MaterialTheme.colorScheme.outline.copy(alpha = 0.2f)
                                )
                            ) {
                                Column(
                                    modifier = Modifier
                                        .padding(14.dp)
                                        .animateContentSize()
                                ) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Surface(
                                                shape = RoundedCornerShape(6.dp),
                                                color = MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)
                                            ) {
                                                Text(
                                                    text = crossRef.category.uppercase(),
                                                    fontSize = 9.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = MaterialTheme.colorScheme.primary,
                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                )
                                            }
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text(
                                                text = crossRef.reference,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 14.sp,
                                                color = if (readerTheme != "Light") readerThemeVerseNumColor else MaterialTheme.colorScheme.primary
                                            )
                                        }

                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            IconButton(
                                                onClick = { previewCrossRef = crossRef },
                                                modifier = Modifier.size(28.dp)
                                            ) {
                                                Icon(Icons.Default.RemoveRedEye, contentDescription = "Preview", tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(15.dp))
                                            }
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Surface(
                                                shape = RoundedCornerShape(12.dp),
                                                color = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.6f)
                                            ) {
                                                Row(
                                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp),
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text(
                                                        text = "Jump",
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = MaterialTheme.colorScheme.onSecondaryContainer
                                                    )
                                                    Spacer(modifier = Modifier.width(2.dp))
                                                    Icon(
                                                        imageVector = Icons.AutoMirrored.Filled.ArrowForward,
                                                        contentDescription = "Navigate",
                                                        tint = MaterialTheme.colorScheme.onSecondaryContainer,
                                                        modifier = Modifier.size(12.dp)
                                                    )
                                                }
                                            }
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(4.dp))

                                    Text(
                                        text = "• ${crossRef.theme}",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = MaterialTheme.colorScheme.secondary
                                    )

                                    Spacer(modifier = Modifier.height(4.dp))

                                    Text(
                                        text = "“${crossRef.snippet}”",
                                        fontSize = 12.sp,
                                        fontStyle = FontStyle.Italic,
                                        fontFamily = FontFamily.Serif,
                                        lineHeight = 17.sp,
                                        color = if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.85f)
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Animated Preview Bottom Sheet Dialog when previewCrossRef != null
    if (previewCrossRef != null) {
        val target = previewCrossRef!!
        Dialog(onDismissRequest = { previewCrossRef = null }) {
            AnimatedVisibility(
                visible = true,
                enter = slideInVertically(initialOffsetY = { it }) + fadeIn()
            ) {
                Card(
                    shape = RoundedCornerShape(24.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                    border = BorderStroke(1.5.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.4f)),
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(12.dp)
                ) {
                    Column(
                        modifier = Modifier.padding(20.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Surface(
                            shape = CircleShape,
                            color = MaterialTheme.colorScheme.primaryContainer,
                            modifier = Modifier.size(48.dp)
                        ) {
                            Box(contentAlignment = Alignment.Center) {
                                Icon(Icons.Default.MenuBook, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(24.dp))
                            }
                        }
                        Spacer(modifier = Modifier.height(10.dp))
                        Surface(
                            shape = RoundedCornerShape(8.dp),
                            color = MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)
                        ) {
                            Text(
                                text = target.category.uppercase(),
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
                            )
                        }
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = target.reference,
                            fontSize = 20.sp,
                            fontWeight = FontWeight.Bold,
                            fontFamily = FontFamily.Serif,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Text(
                            text = target.theme,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.SemiBold,
                            color = MaterialTheme.colorScheme.secondary
                        )

                        Spacer(modifier = Modifier.height(14.dp))

                        Surface(
                            shape = RoundedCornerShape(14.dp),
                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text(
                                text = "“${target.snippet}”",
                                fontSize = 14.sp,
                                fontStyle = FontStyle.Italic,
                                fontFamily = FontFamily.Serif,
                                lineHeight = 21.sp,
                                textAlign = TextAlign.Center,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                modifier = Modifier.padding(16.dp)
                            )
                        }

                        Spacer(modifier = Modifier.height(18.dp))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            OutlinedButton(
                                onClick = {
                                    val clipboardManager = context.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
                                    val clip = ClipData.newPlainText("Cross Reference", "${target.reference}: ${target.snippet}")
                                    clipboardManager.setPrimaryClip(clip)
                                    Toast.makeText(context, "Copied to clipboard", Toast.LENGTH_SHORT).show()
                                },
                                shape = RoundedCornerShape(14.dp),
                                modifier = Modifier.weight(1f)
                            ) {
                                Icon(Icons.Default.ContentCopy, contentDescription = null, modifier = Modifier.size(14.dp))
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Copy", fontSize = 11.sp)
                            }

                            Button(
                                onClick = {
                                    viewModel.selectBook(target.targetBook)
                                    viewModel.selectChapter(target.targetChapter)
                                    viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                                    viewModel.logReadingHistory(target.targetBook, target.targetChapter)
                                    previewCrossRef = null
                                },
                                shape = RoundedCornerShape(14.dp),
                                modifier = Modifier.weight(1.3f)
                            ) {
                                Text("Jump Now", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                Spacer(modifier = Modifier.width(4.dp))
                                Icon(Icons.AutoMirrored.Filled.ArrowForward, contentDescription = null, modifier = Modifier.size(14.dp))
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun ConcordanceVersePopup(
    ref: String,
    viewModel: BibleViewModel,
    onDismiss: () -> Unit
) {
    val (book, chapter, verseRange) = remember(ref) { parseScriptureFullRef(ref) }
    val translation by viewModel.selectedTranslation.collectAsStateWithLifecycle()
    
    var versesList by remember { mutableStateOf<List<BibleVerse>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    var errorMessage by remember { mutableStateOf<String?>(null) }
    
    LaunchedEffect(book, chapter, translation) {
        isLoading = true
        errorMessage = null
        try {
            viewModel.getVersesForReference(translation, book, chapter).collect { localList ->
                if (localList.isNotEmpty()) {
                    versesList = localList
                    isLoading = false
                } else {
                    try {
                        val streamed = com.example.data.GeminiService.streamBibleChapter(translation, book, chapter)
                        if (streamed.isNotEmpty()) {
                            viewModel.saveDownloadedVerses(streamed)
                            versesList = streamed
                        } else {
                            errorMessage = "Verse text not found in local cache."
                        }
                    } catch (e: Exception) {
                        errorMessage = "Offline or API Error: ${e.localizedMessage ?: "Could not load verse text"}"
                    } finally {
                        isLoading = false
                    }
                }
            }
        } catch (e: Exception) {
            errorMessage = e.localizedMessage ?: "Failed to load"
            isLoading = false
        }
    }
    
    androidx.compose.ui.window.Dialog(onDismissRequest = onDismiss) {
        Card(
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp)
        ) {
            Column(
                modifier = Modifier
                    .padding(18.dp)
                    .fillMaxWidth()
            ) {
                // Header
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column {
                        Text(
                            text = ref,
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                        Text(
                            text = "Translation: $translation",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                        )
                    }
                    IconButton(onClick = onDismiss) {
                        Icon(Icons.Default.Close, "Close")
                    }
                }
                
                Spacer(modifier = Modifier.height(16.dp))
                
                Box(
                    modifier = Modifier
                        .weight(1f, fill = false)
                        .verticalScroll(rememberScrollState())
                ) {
                    if (isLoading) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(24.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            CircularProgressIndicator(color = MaterialTheme.colorScheme.primary)
                            Spacer(modifier = Modifier.height(12.dp))
                            Text("Loading verse text...", style = MaterialTheme.typography.bodyMedium)
                        }
                    } else if (errorMessage != null) {
                        Text(
                            text = errorMessage ?: "Error loading scripture text.",
                            color = MaterialTheme.colorScheme.error,
                            style = MaterialTheme.typography.bodyMedium
                        )
                    } else {
                        val startVerse = verseRange.split("-").firstOrNull()?.filter { it.isDigit() }?.toIntOrNull() ?: 1
                        val endVerse = verseRange.split("-").getOrNull(1)?.filter { it.isDigit() }?.toIntOrNull() ?: startVerse
                        
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            versesList.forEach { verse ->
                                val isTarget = verse.verseNumber in startVerse..endVerse
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .background(
                                            if (isTarget) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.25f)
                                            else androidx.compose.ui.graphics.Color.Transparent,
                                            RoundedCornerShape(4.dp)
                                        )
                                        .padding(4.dp)
                                ) {
                                    Text(
                                        text = "${verse.verseNumber} ",
                                        fontWeight = FontWeight.Bold,
                                        color = if (isTarget) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f),
                                        fontSize = 13.sp
                                    )
                                    Text(
                                        text = verse.text,
                                        color = if (isTarget) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                                        fontSize = 14.sp,
                                        fontWeight = if (isTarget) FontWeight.Bold else FontWeight.Normal,
                                        lineHeight = 20.sp
                                    )
                                }
                            }
                        }
                    }
                }
                
                Spacer(modifier = Modifier.height(16.dp))
                
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.End
                ) {
                    TextButton(onClick = onDismiss) {
                        Text("Close")
                    }
                }
            }
        }
    }
}

fun getTimelineIcon(iconName: String): androidx.compose.ui.graphics.vector.ImageVector {
    return when (iconName) {
        "landscape" -> Icons.Default.Terrain
        "tsunami" -> Icons.Default.Opacity
        "star" -> Icons.Default.Star
        "waves" -> Icons.Default.Waves
        "gavel" -> Icons.Default.Gavel
        "crown" -> Icons.Default.WorkspacePremium
        "call_split" -> Icons.Default.CallSplit
        "door_open" -> Icons.Default.ExitToApp
        "child_care" -> Icons.Default.Face
        "menu_book" -> Icons.Default.MenuBook
        "wb_sunny" -> Icons.Default.WbSunny
        "local_fire_department" -> Icons.Default.Whatshot
        else -> Icons.Default.Info
    }
}

// -----------------------------------------------------------------
// 1. READ SCREEN (BIBLE READER)
// -----------------------------------------------------------------
@OptIn(ExperimentalFoundationApi::class, androidx.compose.foundation.layout.ExperimentalLayoutApi::class)
@Composable
fun ReadScreen(
    viewModel: BibleViewModel,
    speakText: (String, String) -> Unit,
    speakBibleChapter: (List<BibleVerse>, String, Int) -> Unit,
    stopSpeaking: () -> Unit,
    pauseSpeaking: () -> Unit = {},
    resumeSpeaking: () -> Unit = {},
    isReadingPaused: Boolean = false,
    currentReadingTitle: String?,
    confirmDeletion: (String, String, () -> Unit) -> Unit
) {
    val currentReadStep by viewModel.currentReadStep.collectAsStateWithLifecycle()
    val appLanguageState by viewModel.appLanguage.collectAsStateWithLifecycle()
    val isCompareMode by viewModel.isCompareMode.collectAsStateWithLifecycle()
    val compareTranslation by viewModel.compareTranslation.collectAsStateWithLifecycle()
    val compareSideBySide by viewModel.compareSideBySide.collectAsStateWithLifecycle()
    val comparedVerses by viewModel.comparedVerses.collectAsStateWithLifecycle()

    val verses by viewModel.currentVerses.collectAsStateWithLifecycle()
    val isStreamingChapter by viewModel.isStreamingChapter.collectAsStateWithLifecycle()
    val selectedTranslation by viewModel.selectedTranslation.collectAsStateWithLifecycle()
    val selectedBook by viewModel.selectedBook.collectAsStateWithLifecycle()
    val selectedChapter by viewModel.selectedChapter.collectAsStateWithLifecycle()
    val currentlyReadingVerseNumber by viewModel.currentlyReadingVerseNumber.collectAsStateWithLifecycle()
    
    val availableBooks by viewModel.availableBooks.collectAsStateWithLifecycle()
    val availableChapters by viewModel.availableChapters.collectAsStateWithLifecycle()
    val favorites by viewModel.favoriteVerses.collectAsStateWithLifecycle()
    val bookmarks by viewModel.bookmarkedVerses.collectAsStateWithLifecycle()
    val allReadingHistory by viewModel.allReadingHistoryList.collectAsStateWithLifecycle()
    val highlightedVerseForPopup by viewModel.selectedVerseForHighlight.collectAsStateWithLifecycle()
    val availableTranslationsList by viewModel.availableTranslationsList.collectAsStateWithLifecycle()
    val readerFontSize by viewModel.readerFontSize.collectAsStateWithLifecycle()
    val readerFontSerif by viewModel.readerFontSerif.collectAsStateWithLifecycle()
    val readerFontFamily by viewModel.readerFontFamily.collectAsStateWithLifecycle()
    val readerLineHeightMultiplier by viewModel.readerLineHeightMultiplier.collectAsStateWithLifecycle()
    val readerTheme by viewModel.readerTheme.collectAsStateWithLifecycle()
    val selectedTestament by viewModel.selectedTestament.collectAsStateWithLifecycle()
    val selectedVerse by viewModel.selectedVerse.collectAsStateWithLifecycle()
    var verseToShareStudio by remember { mutableStateOf<BibleVerse?>(null) }
    
    val isDyslexic = readerFontFamily == "Dyslexic"
    val dyslexicLetterSpacing = if (isDyslexic) 0.15.sp else androidx.compose.ui.unit.TextUnit.Companion.Unspecified
    val dyslexicFontWeight = if (isDyslexic) FontWeight.Medium else FontWeight.Normal

    val currentLineHeightSp = if (isDyslexic) (readerFontSize * (readerLineHeightMultiplier + 0.35f)).sp else (readerFontSize * readerLineHeightMultiplier).sp
    val fullViewLineHeightSp = if (isDyslexic) ((readerFontSize + 1f) * (readerLineHeightMultiplier + 0.35f)).sp else ((readerFontSize + 1f) * readerLineHeightMultiplier).sp

    val readerThemeBgColor = when (readerTheme) {
        "Sepia" -> Color(0xFFFBF0D9)
        "Dark" -> Color(0xFF14151E)
        "High Contrast" -> Color(0xFF000000)
        "OLED Night" -> Color(0xFF000000)
        "Nordic Blue" -> Color(0xFF0D1B2A)
        else -> MaterialTheme.colorScheme.background
    }

    val readerThemeCardBgColor = when (readerTheme) {
        "Sepia" -> Color(0xFFF3E5C8)
        "Dark" -> Color(0xFF1E202E)
        "High Contrast" -> Color(0xFF121212)
        "OLED Night" -> Color(0xFF0F0F12)
        "Nordic Blue" -> Color(0xFF1B263B)
        else -> MaterialTheme.colorScheme.surface
    }

    val readerThemeTextColor = when (readerTheme) {
        "Sepia" -> Color(0xFF4A3B2C)
        "Dark" -> Color(0xFFE2E2E9)
        "High Contrast" -> Color(0xFFFFFF00)
        "OLED Night" -> Color(0xFFC5C9D3)
        "Nordic Blue" -> Color(0xFFE0E1DD)
        else -> MaterialTheme.colorScheme.onBackground
    }

    val readerThemeSubtextColor = when (readerTheme) {
        "Sepia" -> Color(0xFF7A6855)
        "Dark" -> Color(0xFFA0A5B5)
        "High Contrast" -> Color(0xFFFFFFFF)
        "OLED Night" -> Color(0xFF808595)
        "Nordic Blue" -> Color(0xFF778DA9)
        else -> MaterialTheme.colorScheme.onSurfaceVariant
    }

    val readerThemeVerseNumColor = when (readerTheme) {
        "Sepia" -> Color(0xFF8C5A2B)
        "Dark" -> Color(0xFFFFD54F)
        "High Contrast" -> Color(0xFF00FFFF)
        "OLED Night" -> Color(0xFF80CBC4)
        "Nordic Blue" -> Color(0xFF48CAE4)
        else -> MaterialTheme.colorScheme.primary
    }

    val selectedFontFamily = remember(readerFontFamily) {
        when (readerFontFamily) {
            "Serif" -> FontFamily.Serif
            "SansSerif", "Sans-Serif" -> FontFamily.SansSerif
            "Monospace" -> FontFamily.Monospace
            "Cursive" -> FontFamily.Cursive
            "Dyslexic" -> FontFamily.SansSerif
            else -> FontFamily.Default
        }
    }
    
    val savedScrollIndex by viewModel.savedReadScrollIndex.collectAsStateWithLifecycle()
    val savedScrollOffset by viewModel.savedReadScrollOffset.collectAsStateWithLifecycle()

    val listState = rememberLazyListState(
        initialFirstVisibleItemIndex = savedScrollIndex,
        initialFirstVisibleItemScrollOffset = savedScrollOffset
    )
    val coroutineScope = rememberCoroutineScope()
    val context = LocalContext.current

    var isFullViewActive by remember { mutableStateOf(false) }
    var showQuickJumpDialog by remember { mutableStateOf(false) }
    var showReaderSettingsModal by remember { mutableStateOf(false) }
    var readHeaderImageIdx by remember { mutableIntStateOf(0) }
    var selectedTranslationForDetails by remember { mutableStateOf<String?>(null) }
    var showBookDropdown by remember { mutableStateOf(false) }
    var showChapterDropdown by remember { mutableStateOf(false) }
    var showTranslationDropdown by remember { mutableStateOf(false) }
    var showVerseDropdown by remember { mutableStateOf(false) }
    var showVersionComparerForVerse by remember { mutableStateOf<BibleVerse?>(null) }
    var selectedBookForGuide by remember { mutableStateOf<String?>(null) }

    // Continuously save scroll position as user scrolls
    LaunchedEffect(listState.firstVisibleItemIndex, listState.firstVisibleItemScrollOffset) {
        if (listState.isScrollInProgress || listState.firstVisibleItemIndex > 0 || listState.firstVisibleItemScrollOffset > 0) {
            viewModel.saveReadScrollPosition(listState.firstVisibleItemIndex, listState.firstVisibleItemScrollOffset)
        }
    }

    // Scroll to selected verse when chapter/book/verse changes
    var prevBookChapterKey by remember { mutableStateOf("$selectedBook-$selectedChapter-$selectedTranslation") }
    LaunchedEffect(verses, selectedVerse, selectedBook, selectedChapter, selectedTranslation) {
        val currentKey = "$selectedBook-$selectedChapter-$selectedTranslation"
        val hasChapterChanged = currentKey != prevBookChapterKey
        prevBookChapterKey = currentKey

        if (hasChapterChanged) {
            if (selectedVerse > 1 && verses.isNotEmpty()) {
                val index = verses.indexOfFirst { it.verseNumber == selectedVerse }
                if (index >= 0) {
                    listState.animateScrollToItem(index)
                }
            } else if (verses.isNotEmpty()) {
                listState.animateScrollToItem(0)
            }
        } else if (selectedVerse > 1 && verses.isNotEmpty()) {
            val index = verses.indexOfFirst { it.verseNumber == selectedVerse }
            if (index >= 0) {
                listState.animateScrollToItem(index)
            }
        }
    }

    var isHeaderVisible by remember { mutableStateOf(true) }
    var lastScrollIndex by remember { mutableIntStateOf(savedScrollIndex) }
    var lastScrollOffset by remember { mutableIntStateOf(savedScrollOffset) }

    // Scroll direction tracking for collapsing headers
    LaunchedEffect(listState.firstVisibleItemIndex, listState.firstVisibleItemScrollOffset) {
        val currentIndex = listState.firstVisibleItemIndex
        val currentOffset = listState.firstVisibleItemScrollOffset

        if (currentReadStep == BibleViewModel.ReadStep.VERSE_READ) {
            if (currentIndex > lastScrollIndex) {
                // Scrolling down into chapter -> hide header to maximize reading area
                isHeaderVisible = false
            } else if (currentIndex < lastScrollIndex) {
                // Scrolling up -> show header
                isHeaderVisible = true
            } else {
                val delta = currentOffset - lastScrollOffset
                if (delta > 15) {
                    isHeaderVisible = false
                } else if (delta < -15) {
                    isHeaderVisible = true
                }
            }

            if (currentIndex == 0 && currentOffset < 30) {
                isHeaderVisible = true
            }
        } else {
            isHeaderVisible = true
        }

        lastScrollIndex = currentIndex
        lastScrollOffset = currentOffset
    }

    // Auto-scroll when currently reading verse changes
    LaunchedEffect(currentlyReadingVerseNumber) {
        currentlyReadingVerseNumber?.let { verseNum ->
            val index = verses.indexOfFirst { it.verseNumber == verseNum }
            if (index >= 0) {
                listState.animateScrollToItem(index, scrollOffset = -250)
            }
        }
    }

    Column(modifier = Modifier.fillMaxSize()) {
        val tabLabel0 = if (!selectedTestament.isNullOrBlank()) {
            if (selectedTestament == "Old Testament") "Old Test." else "New Test."
        } else "Testament"

        val tabLabel1 = if (!selectedBook.isNullOrBlank()) selectedBook else "Book"
        val tabLabel2 = if (selectedChapter > 0) "Ch. $selectedChapter" else "Chapter"
        val tabLabel3 = if (selectedVerse > 1) "Ver. $selectedVerse" else if (selectedVerse == 1) "Whole Ch." else "Verse"
        val tabLabel4 = "Read"

        val currentTabIndex = when (currentReadStep) {
            BibleViewModel.ReadStep.TESTAMENT_SELECT -> 0
            BibleViewModel.ReadStep.COMMON_SELECT -> 1
            BibleViewModel.ReadStep.BOOK_SELECT -> 2
            BibleViewModel.ReadStep.CHAPTER_SELECT -> 3
            BibleViewModel.ReadStep.VERSE_SELECT -> 4
            BibleViewModel.ReadStep.VERSE_READ -> 5
        }

        AnimatedVisibility(
            visible = isHeaderVisible || currentReadStep != BibleViewModel.ReadStep.VERSE_READ,
            enter = expandVertically(animationSpec = tween(250)) + fadeIn(animationSpec = tween(250)),
            exit = shrinkVertically(animationSpec = tween(250)) + fadeOut(animationSpec = tween(250))
        ) {
            Column(modifier = Modifier.fillMaxWidth()) {
                // Top Hero Picture Header Banner for Read Page
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(start = 12.dp, top = 6.dp, end = 12.dp, bottom = 4.dp)
                        .height(135.dp),
                    shape = RoundedCornerShape(20.dp),
                    elevation = CardDefaults.cardElevation(defaultElevation = 4.dp),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.35f))
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .clickable { readHeaderImageIdx = (readHeaderImageIdx + 1) % 2 }
                    ) {
                        val headerImgDrawable = if (readHeaderImageIdx == 0) {
                            R.drawable.img_read_header_plants_1785646748508
                        } else {
                            R.drawable.img_chat_header_banner_1785646733250
                        }

                        androidx.compose.foundation.Image(
                            painter = androidx.compose.ui.res.painterResource(id = headerImgDrawable),
                            contentDescription = "Scripture Reader Header Banner",
                            contentScale = ContentScale.Crop,
                            modifier = Modifier.fillMaxSize()
                        )

                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .background(
                                    Brush.verticalGradient(
                                        colors = listOf(
                                            Color.Black.copy(alpha = 0.35f),
                                            Color.Black.copy(alpha = 0.85f)
                                        )
                                    )
                                )
                        )

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(12.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Surface(
                                shape = RoundedCornerShape(20.dp),
                                color = Color.Black.copy(alpha = 0.55f),
                                border = BorderStroke(1.dp, Color.White.copy(alpha = 0.35f)),
                                modifier = Modifier.clickable { readHeaderImageIdx = (readHeaderImageIdx + 1) % 2 }
                            ) {
                                Row(
                                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    Icon(Icons.Default.Collections, contentDescription = null, tint = Color.White, modifier = Modifier.size(13.dp))
                                    Text(
                                        text = if (readHeaderImageIdx == 0) "Study Desk View" else "Fellowship View",
                                        fontSize = 11.sp,
                                        color = Color.White,
                                        fontWeight = FontWeight.SemiBold
                                    )
                                }
                            }

                            IconButton(
                                onClick = { showReaderSettingsModal = true },
                                modifier = Modifier
                                    .size(32.dp)
                                    .background(Color.Black.copy(alpha = 0.55f), CircleShape)
                                    .testTag("open_reader_settings_banner")
                            ) {
                                Icon(Icons.Default.FormatSize, contentDescription = "Reader Typography Settings", tint = Color.White, modifier = Modifier.size(18.dp))
                            }
                        }

                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(14.dp),
                            verticalArrangement = Arrangement.Bottom
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Surface(
                                    shape = CircleShape,
                                    color = Color(0xFF00E676),
                                    modifier = Modifier.size(8.dp)
                                ) {}
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(
                                    text = "HOLY SCRIPTURES",
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF00E676),
                                    letterSpacing = 1.sp
                                )
                            }
                            Spacer(modifier = Modifier.height(2.dp))
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = if (selectedBook.isNotBlank()) "$selectedBook $selectedChapter" else "Scripture Study Reader",
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    fontFamily = FontFamily.Serif,
                                    color = Color.White,
                                    maxLines = 1
                                )
                                Surface(
                                    shape = RoundedCornerShape(12.dp),
                                    color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.9f)
                                ) {
                                    Text(
                                        text = selectedTranslation,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.onPrimaryContainer,
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
                                    )
                                }
                            }
                        }
                    }
                }

                ScrollableTabRow(
                    selectedTabIndex = currentTabIndex,
                    edgePadding = 16.dp,
                    containerColor = MaterialTheme.colorScheme.surface,
                    contentColor = Color(0xFF00E676),
                    indicator = { tabPositions ->
                        if (currentTabIndex < tabPositions.size) {
                            TabRowDefaults.SecondaryIndicator(
                                Modifier.tabIndicatorOffset(tabPositions[currentTabIndex]),
                                color = Color(0xFF00E676),
                                height = 3.dp
                            )
                        }
                    },
                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp).testTag("read_navigation_tabs")
                ) {
                    val tabs = listOf(
                        Triple(0, tabLabel0, BibleViewModel.ReadStep.TESTAMENT_SELECT),
                        Triple(1, "Common", BibleViewModel.ReadStep.COMMON_SELECT),
                        Triple(2, tabLabel1, BibleViewModel.ReadStep.BOOK_SELECT),
                        Triple(3, tabLabel2, BibleViewModel.ReadStep.CHAPTER_SELECT),
                        Triple(4, tabLabel3, BibleViewModel.ReadStep.VERSE_SELECT),
                        Triple(5, tabLabel4, BibleViewModel.ReadStep.VERSE_READ)
                    )
                    tabs.forEach { (index, label, step) ->
                        val isEnabled = when (index) {
                            0 -> true
                            1 -> true
                            2 -> !selectedTestament.isNullOrBlank()
                            3 -> !selectedBook.isNullOrBlank()
                            4 -> selectedChapter > 0
                            5 -> selectedChapter > 0
                            else -> false
                        }
                        val isSelected = currentTabIndex == index
                        Tab(
                            selected = isSelected,
                            onClick = {
                                if (isEnabled) {
                                    viewModel.setReadStep(step)
                                } else {
                                    Toast.makeText(context, "Please complete previous selections first", Toast.LENGTH_SHORT).show()
                                }
                            },
                            modifier = Modifier
                                .padding(horizontal = 4.dp, vertical = 2.dp)
                                .clip(RoundedCornerShape(8.dp))
                                .then(
                                    if (isSelected) {
                                        Modifier
                                            .border(1.5.dp, Color(0xFF00E676), RoundedCornerShape(8.dp))
                                            .background(Color(0x0C00E676), RoundedCornerShape(8.dp))
                                    } else Modifier
                                ),
                            text = {
                                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.padding(vertical = 6.dp, horizontal = 4.dp)) {
                                    Text(
                                        text = translateUi(label, appLanguageState),
                                        fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
                                        fontSize = 12.sp,
                                        color = if (isSelected) Color(0xFF00E676) else if (isEnabled) MaterialTheme.colorScheme.onSurfaceVariant else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.38f)
                                    )
                                }
                            }
                        )
                    }
                }
            }
        }

        AnimatedContent(
            targetState = currentReadStep,
            transitionSpec = {
                val targetIndex = targetState.ordinal
                val initialIndex = initialState.ordinal
                if (targetIndex > initialIndex) {
                    (slideInHorizontally(initialOffsetX = { it }, animationSpec = tween(300)) + fadeIn()).togetherWith(
                        slideOutHorizontally(targetOffsetX = { -it / 3 }, animationSpec = tween(300)) + fadeOut()
                    )
                } else {
                    (slideInHorizontally(initialOffsetX = { -it }, animationSpec = tween(300)) + fadeIn()).togetherWith(
                        slideOutHorizontally(targetOffsetX = { it / 3 }, animationSpec = tween(300)) + fadeOut()
                    )
                }
            },
            label = "ReadStepTransition",
            modifier = Modifier.fillMaxSize().weight(1f)
        ) { step ->
            when (step) {
                BibleViewModel.ReadStep.COMMON_SELECT -> {
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .padding(16.dp)
                            .verticalScroll(rememberScrollState()),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            IconButton(onClick = { viewModel.setReadStep(BibleViewModel.ReadStep.TESTAMENT_SELECT) }) {
                                Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                            }
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = translateUi("Common Scriptures", appLanguageState),
                                style = MaterialTheme.typography.titleLarge,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }
                        
                        CommonScripturesView(
                            viewModel = viewModel,
                            appLanguageState = appLanguageState,
                            onNavigateToRead = { book, chapter, verse ->
                                val testament = if (bookNameInOldTestament(book)) "Old Testament" else "New Testament"
                                viewModel.selectTestament(testament)
                                viewModel.selectBook(book)
                                viewModel.selectChapter(chapter)
                                viewModel.selectVerse(verse)
                                viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                            }
                        )
                    }
                }

                BibleViewModel.ReadStep.TESTAMENT_SELECT -> {
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .padding(16.dp)
                            .verticalScroll(rememberScrollState()),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            IconButton(onClick = { viewModel.navigateTo(Screen.HOME) }) {
                                Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back to Home")
                            }
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = "Select Testament",
                                style = MaterialTheme.typography.titleLarge,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }

                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)),
                            shape = RoundedCornerShape(14.dp),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.25f))
                        ) {
                            Row(
                                modifier = Modifier.padding(14.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(38.dp)
                                        .clip(CircleShape)
                                        .background(Color(0x1800E676)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(Icons.AutoMirrored.Filled.MenuBook, null, tint = Color(0xFF00E676), modifier = Modifier.size(20.dp))
                                }
                                Spacer(modifier = Modifier.width(12.dp))
                                Column {
                                    Text("Step 1: Choose Testament", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface)
                                    Text("Select a Testament to filter scriptures and start studying.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                }
                            }
                        }

                        Row(
                            modifier = Modifier.fillMaxWidth().height(125.dp),
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            // Old Testament Card
                            val isOldSelected = selectedTestament == "Old Testament"
                            Card(
                                modifier = Modifier
                                    .weight(1f)
                                    .fillMaxHeight()
                                    .greenGlowBorder(enabled = isOldSelected, shape = RoundedCornerShape(16.dp))
                                    .clickable {
                                        viewModel.selectTestament("Old Testament")
                                        viewModel.setReadStep(BibleViewModel.ReadStep.BOOK_SELECT)
