                Row(
                    modifier = Modifier.fillMaxWidth().padding(bottom = 16.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(onClick = { viewModel.setReadStep(BibleViewModel.ReadStep.CHAPTER_SELECT) }) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back to Chapters")
                    }
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "Select Verse",
                        style = MaterialTheme.typography.titleLarge,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary
                    )
                }

                Card(
                    modifier = Modifier.fillMaxWidth().padding(bottom = 16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.7f)),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Row(
                        modifier = Modifier.padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Icon(Icons.AutoMirrored.Filled.MenuBook, null, tint = MaterialTheme.colorScheme.primary)
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text("Step 4: Choose Verse of $selectedBook $selectedChapter", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodyMedium)
                            Text("Select a verse number to open directly at that position.", style = MaterialTheme.typography.bodySmall)
                        }
                    }
                }

                Button(
                    onClick = {
                        viewModel.selectVerse(1)
                        viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 16.dp)
                        .testTag("read_whole_chapter_button"),
                    shape = RoundedCornerShape(12.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.secondary)
                ) {
                    Icon(Icons.AutoMirrored.Filled.MenuBook, contentDescription = null)
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(translateUi("Read Whole Chapter", appLanguageState), fontWeight = FontWeight.Bold)
                }

                LazyColumn(
                    modifier = Modifier.fillMaxSize().weight(1f),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    item {
                        FlowRow(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            // Ensure we have verse numbers
                            val verseCount = if (verses.isEmpty()) 20 else verses.size
                            (1..verseCount).forEach { vNum ->
                                val isVSelected = vNum == selectedVerse
                                Card(
                                    modifier = Modifier
                                        .size(64.dp)
                                        .greenGlowBorder(enabled = isVSelected, shape = RoundedCornerShape(12.dp))
                                        .clickable {
                                            viewModel.selectVerse(vNum)
                                            viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                                        }
                                        .testTag("verse_select_$vNum"),
                                    colors = CardDefaults.cardColors(
                                        containerColor = if (vNum == selectedVerse) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surface
