        BibleViewModel.ReadStep.VERSE_READ -> {
            Column(modifier = Modifier.fillMaxSize()) {
                // Collapsible selector bar with next/prev arrows & Back to chapters
                AnimatedVisibility(
                    visible = isHeaderVisible,
                    enter = expandVertically(animationSpec = tween(250)) + fadeIn(animationSpec = tween(250)),
                    exit = shrinkVertically(animationSpec = tween(250)) + fadeOut(animationSpec = tween(250))
                ) {
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(8.dp),
                        shape = RoundedCornerShape(12.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                    ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(8.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        // Row 1: Scrollable Dropdowns Row
                        androidx.compose.foundation.lazy.LazyRow(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(6.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            item {
                                // 1. Translation selector
                                Box {
                                    AssistChip(
                                        onClick = { showTranslationDropdown = true },
                                        label = { Text(selectedTranslation, fontWeight = FontWeight.Bold, fontSize = 11.sp) },
                                        modifier = Modifier.testTag("translation_selector")
                                    )
                                    DropdownMenu(
                                        expanded = showTranslationDropdown,
                                        onDismissRequest = { showTranslationDropdown = false },
                                        modifier = Modifier.heightIn(max = 280.dp)
                                    ) {
                                        availableTranslationsList.forEach { trans ->
                                            DropdownMenuItem(
                                                text = {
                                                    Row(
                                                        modifier = Modifier.fillMaxWidth(),
                                                        horizontalArrangement = Arrangement.SpaceBetween,
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Text(trans, modifier = Modifier.weight(1f))
                                                        IconButton(
                                                            onClick = {
                                                                showTranslationDropdown = false
                                                                selectedTranslationForDetails = trans
                                                            },
                                                            modifier = Modifier.size(24.dp)
                                                        ) {
                                                            Icon(
                                                                imageVector = Icons.Default.Info,
                                                                contentDescription = "Version Info",
                                                                tint = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f),
                                                                modifier = Modifier.size(16.dp)
                                                            )
                                                        }
                                                    }
                                                },
                                                onClick = {
                                                    viewModel.selectTranslation(trans)
                                                    showTranslationDropdown = false
                                                }
                                            )
                                        }
                                    }
                                }
                            }

                            item {
                                // 2. Book selector
                                Box {
                                    AssistChip(
                                        onClick = { showBookDropdown = true },
                                        label = { Text(selectedBook, fontWeight = FontWeight.Bold, fontSize = 11.sp) },
                                        modifier = Modifier.testTag("book_selector")
                                    )
                                    DropdownMenu(
                                        expanded = showBookDropdown,
                                        onDismissRequest = { showBookDropdown = false },
                                        modifier = Modifier.heightIn(max = 280.dp)
                                    ) {
                                        availableBooks.forEach { bk ->
                                            DropdownMenuItem(
                                                text = { Text(bk) },
                                                onClick = {
                                                    viewModel.selectBook(bk)
                                                    viewModel.selectChapter(1)
                                                    viewModel.selectVerse(1)
                                                    showBookDropdown = false
                                                }
                                            )
                                        }
                                    }
                                }
                            }

                            item {
                                // 3. Chapter selector
                                Box {
                                    AssistChip(
                                        onClick = { showChapterDropdown = true },
                                        label = { Text("Ch $selectedChapter", fontWeight = FontWeight.Bold, fontSize = 11.sp) },
                                        modifier = Modifier.testTag("chapter_selector")
                                    )
                                    DropdownMenu(
                                        expanded = showChapterDropdown,
                                        onDismissRequest = { showChapterDropdown = false },
                                        modifier = Modifier.heightIn(max = 280.dp)
                                    ) {
                                        availableChapters.forEach { ch ->
                                            DropdownMenuItem(
                                                text = { Text("Chapter $ch") },
                                                onClick = {
                                                    viewModel.selectChapter(ch)
                                                    viewModel.selectVerse(1)
                                                    showChapterDropdown = false
                                                }
                                            )
                                        }
                                    }
                                }
                            }

                            item {
                                // 4. Verse selector
                                Box {
                                    AssistChip(
                                        onClick = { showVerseDropdown = true },
                                        label = { Text("Ver $selectedVerse", fontWeight = FontWeight.Bold, fontSize = 11.sp) },
                                        modifier = Modifier.testTag("verse_selector")
                                    )
                                    DropdownMenu(
                                        expanded = showVerseDropdown,
                                        onDismissRequest = { showVerseDropdown = false },
                                        modifier = Modifier.heightIn(max = 280.dp)
                                    ) {
                                        val totalVerses = verses.size.coerceAtLeast(1)
                                        (1..totalVerses).forEach { vNum ->
                                            DropdownMenuItem(
                                                text = { Text("Verse $vNum") },
                                                onClick = {
                                                    viewModel.selectVerse(vNum)
                                                    showVerseDropdown = false
                                                    coroutineScope.launch {
                                                        val index = verses.indexOfFirst { it.verseNumber == vNum }
                                                        if (index >= 0) {
                                                            listState.animateScrollToItem(index)
                                                        }
                                                    }
                                                }
                                            )
                                        }
                                    }
                                }
                            }

                            item {
                                // Read Aloud whole chapter
                                val isCurrentlyReadingThis = currentReadingTitle == "$selectedBook $selectedChapter"
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    AssistChip(
                                        onClick = { showQuickJumpDialog = true },
                                        label = {
                                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                                Icon(Icons.Default.Bolt, contentDescription = "Quick Jump", modifier = Modifier.size(16.dp), tint = MaterialTheme.colorScheme.primary)
                                                Text("Quick Jump ⚡", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        modifier = Modifier.testTag("inline_quick_jump_btn")
                                    )

                                    AssistChip(
                                        onClick = {
                                            if (isCurrentlyReadingThis) {
                                                if (isReadingPaused) {
                                                    resumeSpeaking()
                                                } else {
                                                    pauseSpeaking()
                                                }
                                            } else {
                                                speakBibleChapter(verses, selectedBook, selectedChapter)
                                            }
                                        },
                                        label = {
                                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                                Icon(
                                                    imageVector = if (isCurrentlyReadingThis) {
                                                        if (isReadingPaused) Icons.Default.PlayArrow else Icons.Default.Pause
                                                    } else Icons.Default.VolumeUp,
                                                    contentDescription = if (isCurrentlyReadingThis) (if (isReadingPaused) "Resume" else "Pause") else "Read Chapter Aloud",
                                                    modifier = Modifier.size(16.dp),
                                                    tint = MaterialTheme.colorScheme.primary
                                                )
                                                Text(
                                                    text = if (isCurrentlyReadingThis) (if (isReadingPaused) "Resume" else "Pause") else "Listen", 
                                                    fontSize = 11.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = MaterialTheme.colorScheme.onSurface
                                                )
                                            }
                                        },
                                        modifier = Modifier
                                            .redGlowBorder(enabled = isCurrentlyReadingThis && !isReadingPaused, shape = RoundedCornerShape(8.dp))
                                            .testTag("read_chapter_aloud_btn")
                                    )

                                    if (isCurrentlyReadingThis) {
                                        IconButton(
                                            onClick = { stopSpeaking() },
                                            modifier = Modifier.size(28.dp).testTag("read_chapter_stop_btn")
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Stop,
                                                contentDescription = "Stop",
                                                tint = LivelyRed,
                                                modifier = Modifier.size(16.dp)
                                            )
                                        }
                                    }
                                }
                            }

                            item {
                                // 5. Reader Text Styling Options
                                AssistChip(
                                    onClick = { showReaderSettingsModal = true },
                                    leadingIcon = { Icon(Icons.Default.FormatSize, contentDescription = "Reader Settings", modifier = Modifier.size(15.dp)) },
                                    label = { Text("Settings ⚙️", fontSize = 11.sp, fontWeight = FontWeight.Bold) },
                                    modifier = Modifier.testTag("style_selector")
                                )
                            }
                        }

                        // Row 2: Navigation controls & current book display
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            IconButton(
                                onClick = { viewModel.selectPreviousChapter() },
                                modifier = Modifier.testTag("prev_chapter_btn")
                            ) {
                                Icon(
                                    imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                                    contentDescription = "Previous Chapter",
                                    tint = MaterialTheme.colorScheme.primary
                                )
                            }

                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.Center,
                                modifier = Modifier
                                    .weight(1f)
                                    .clickable { selectedBookForGuide = selectedBook }
                                    .padding(vertical = 4.dp, horizontal = 8.dp)
                                    .testTag("open_book_overview_from_title")
                            ) {
                                val isChRead = allReadingHistory.any {
                                    it.bookName.equals(selectedBook, ignoreCase = true) && it.chapter == selectedChapter
                                }
                                Text(
                                    text = "$selectedBook $selectedChapter",
                                    style = MaterialTheme.typography.titleMedium,
                                    fontWeight = FontWeight.Bold,
                                    fontFamily = FontFamily.Serif,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Spacer(modifier = Modifier.width(6.dp))
                                Icon(
                                    imageVector = Icons.Default.Info,
                                    contentDescription = "Book Overview",
                                    tint = MaterialTheme.colorScheme.secondary,
                                    modifier = Modifier.size(16.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                IconButton(
                                    onClick = {
                                        viewModel.toggleChapterReadStatus(selectedBook, selectedChapter, !isChRead)
                                        Toast.makeText(context, if (!isChRead) "Chapter completed!" else "Chapter unmarked", Toast.LENGTH_SHORT).show()
                                    },
                                    modifier = Modifier.size(28.dp).testTag("toggle_read_chapter_btn")
                                ) {
                                    Icon(
                                        imageVector = if (isChRead) Icons.Default.CheckCircle else Icons.Default.RadioButtonUnchecked,
                                        contentDescription = "Toggle Read Status",
                                        tint = if (isChRead) GreenTone else MaterialTheme.colorScheme.primary.copy(alpha = 0.4f),
                                        modifier = Modifier.size(20.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.width(8.dp))
                                IconButton(
                                    onClick = { isFullViewActive = true },
                                    modifier = Modifier.size(28.dp).testTag("enter_full_view_btn")
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Fullscreen,
                                        contentDescription = "Full Screen Reading Mode",
                                        tint = MaterialTheme.colorScheme.primary,
                                        modifier = Modifier.size(22.dp)
                                    )
                                }
                            }

                            IconButton(
                                onClick = { viewModel.selectNextChapter() },
                                modifier = Modifier.testTag("next_chapter_btn")
                            ) {
                                Icon(
                                    imageVector = Icons.AutoMirrored.Filled.ArrowForward,
                                    contentDescription = "Next Chapter",
                                    tint = MaterialTheme.colorScheme.primary
                                )
                            }
                        }
                    }
                }

                // Parallel Comparison Selector Bar
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 8.dp, vertical = 2.dp),
                    shape = RoundedCornerShape(8.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.45f))
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 4.dp, horizontal = 12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                imageVector = Icons.Default.Compare,
                                contentDescription = "Compare",
                                modifier = Modifier.size(16.dp),
                                tint = MaterialTheme.colorScheme.primary
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = "Compare Versions",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }
                        
                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            if (isCompareMode) {
                                var showCompareDropdown by remember { mutableStateOf(false) }
                                Box {
                                    AssistChip(
                                        onClick = { showCompareDropdown = true },
                                        label = { Text("With: $compareTranslation", fontSize = 10.sp) },
                                        modifier = Modifier.height(26.dp)
                                    )
                                    DropdownMenu(
                                        expanded = showCompareDropdown,
                                        onDismissRequest = { showCompareDropdown = false }
                                    ) {
                                        availableTranslationsList.forEach { trans ->
                                            DropdownMenuItem(
                                                text = {
                                                    Row(
                                                        modifier = Modifier.fillMaxWidth(),
                                                        horizontalArrangement = Arrangement.SpaceBetween,
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Text(trans, modifier = Modifier.weight(1f))
                                                        IconButton(
                                                            onClick = {
                                                                showCompareDropdown = false
                                                                selectedTranslationForDetails = trans
                                                            },
                                                            modifier = Modifier.size(24.dp)
                                                        ) {
                                                            Icon(
                                                                imageVector = Icons.Default.Info,
                                                                contentDescription = "Version Info",
                                                                tint = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f),
                                                                modifier = Modifier.size(16.dp)
                                                            )
                                                        }
                                                    }
                                                },
                                                onClick = {
                                                    viewModel.setCompareTranslation(trans)
                                                    showCompareDropdown = false
                                                }
                                            )
                                        }
                                    }
                                }

                                FilterChip(
                                    selected = compareSideBySide,
                                    onClick = { viewModel.setCompareSideBySide(!compareSideBySide) },
                                    label = {
                                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                            Icon(
                                                imageVector = if (compareSideBySide) Icons.Default.ViewColumn else Icons.Default.TableRows,
                                                contentDescription = null,
                                                modifier = Modifier.size(12.dp)
                                            )
                                            Text(if (compareSideBySide) "Side-by-Side" else "Stacked", fontSize = 10.sp)
                                        }
                                    },
                                    modifier = Modifier
                                        .height(28.dp)
                                        .redGlowBorder(enabled = compareSideBySide, shape = RoundedCornerShape(8.dp))
                                        .testTag("compare_side_by_side_toggle_btn")
                                )
                            }
                            Switch(
                                checked = isCompareMode,
                                onCheckedChange = { viewModel.setCompareMode(it) },
                                modifier = Modifier.testTag("compare_mode_switch")
                            )
                        }
                    }
                }
                }

                // Scripture Verse List
                AnimatedContent(
                    targetState = listOf(selectedBook, selectedChapter, selectedTranslation, isCompareMode, compareSideBySide),
                    transitionSpec = {
                        (fadeIn(animationSpec = tween(350)) + scaleIn(initialScale = 0.96f, animationSpec = tween(350)))
                            .togetherWith(fadeOut(animationSpec = tween(200)))
                    },
                    label = "ScriptureChapterAndModeTransition",
                    modifier = Modifier.fillMaxSize().weight(1f)
                ) { stateKeys ->
                    val targetBook = stateKeys[0] as String
                    val targetChapter = stateKeys[1] as Int
                    val targetTranslation = stateKeys[2] as String
                    val targetCompareMode = stateKeys[3] as Boolean

                    if (isStreamingChapter) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(32.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                CircularProgressIndicator(
                                    modifier = Modifier.size(48.dp),
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Spacer(modifier = Modifier.height(16.dp))
                                Text(
                                    text = "Streaming $targetBook $targetChapter ($targetTranslation)...",
                                    style = MaterialTheme.typography.titleMedium,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.primary,
                                    textAlign = TextAlign.Center
                                )
                                Spacer(modifier = Modifier.height(8.dp))
                                Text(
                                    text = "Connecting to retrieve undownloaded scripture verses in real-time.",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f),
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    } else if (verses.isEmpty()) {
                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(16.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(145.dp),
                                shape = RoundedCornerShape(20.dp),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.35f)),
                                elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxSize()
                                        .clickable { readHeaderImageIdx = (readHeaderImageIdx + 1) % 2 }
                                ) {
                                    val headerImg = if (readHeaderImageIdx == 0) R.drawable.img_read_header_plants_1785646748508 else R.drawable.img_chat_header_banner_1785646733250
                                    androidx.compose.foundation.Image(
                                        painter = androidx.compose.ui.res.painterResource(id = headerImg),
                                        contentDescription = "Scripture Reader Header",
                                        contentScale = ContentScale.Crop,
                                        modifier = Modifier.fillMaxSize()
                                    )
                                    Box(
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .background(
                                                Brush.verticalGradient(
                                                    colors = listOf(
                                                        Color.Black.copy(alpha = 0.3f),
                                                        Color.Black.copy(alpha = 0.85f)
                                                    )
                                                )
                                            )
                                    )
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(12.dp),
                                        horizontalArrangement = Arrangement.End
                                    ) {
                                        Surface(
                                            shape = RoundedCornerShape(20.dp),
                                            color = Color.Black.copy(alpha = 0.5f),
                                            border = BorderStroke(1.dp, Color.White.copy(alpha = 0.3f))
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp),
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                Icon(Icons.Default.Collections, contentDescription = null, tint = Color.White, modifier = Modifier.size(13.dp))
                                                Text(if (readHeaderImageIdx == 0) "Study Desk View" else "Fellowship View", fontSize = 11.sp, color = Color.White, fontWeight = FontWeight.SemiBold)
                                            }
                                        }
                                    }
                                    Column(
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .padding(14.dp),
                                        verticalArrangement = Arrangement.Bottom
                                    ) {
                                        Text(
                                            text = "$selectedBook $selectedChapter",
                                            fontSize = 22.sp,
                                            fontWeight = FontWeight.Bold,
                                            fontFamily = FontFamily.Serif,
                                            color = Color.White
                                        )
                                    }
                                }
                            }
                            Spacer(modifier = Modifier.height(32.dp))
                            Icon(
                                imageVector = Icons.Default.Info,
                                contentDescription = null,
                                modifier = Modifier.size(56.dp),
                                tint = MaterialTheme.colorScheme.secondary.copy(alpha = 0.5f)
                            )
                            Spacer(modifier = Modifier.height(16.dp))
                            Text(
                                text = "Scripture text not found in local database. Please select Genesis 1, Psalms 23, John 1, Proverbs 3, Romans 8, Isaiah 9, or Matthew 5.",
                                style = MaterialTheme.typography.bodyMedium,
                                textAlign = TextAlign.Center,
                                color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.7f)
                            )
                        }
                    } else {
                        LazyColumn(
                            state = listState,
                            modifier = Modifier
                                .fillMaxSize()
                                .background(if (readerTheme != "Light") readerThemeBgColor else Color.Transparent)
                                .padding(horizontal = 16.dp),
                            verticalArrangement = Arrangement.spacedBy(16.dp),
                            contentPadding = PaddingValues(bottom = 32.dp)
                        ) {
                            item {
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(bottom = 6.dp)
                                        .height(145.dp),
                                    shape = RoundedCornerShape(20.dp),
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.35f)),
                                    elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .clickable { readHeaderImageIdx = (readHeaderImageIdx + 1) % 2 }
                                    ) {
                                        val headerImg = if (readHeaderImageIdx == 0) R.drawable.img_read_header_plants_1785646748508 else R.drawable.img_chat_header_banner_1785646733250
                                        androidx.compose.foundation.Image(
                                            painter = androidx.compose.ui.res.painterResource(id = headerImg),
                                            contentDescription = "$selectedBook Scripture Header",
                                            contentScale = ContentScale.Crop,
                                            modifier = Modifier.fillMaxSize()
                                        )
                                        Box(
                                            modifier = Modifier
                                                .fillMaxSize()
                                                .background(
                                                    Brush.verticalGradient(
                                                        colors = listOf(
                                                            Color.Black.copy(alpha = 0.3f),
                                                            Color.Black.copy(alpha = 0.85f)
                                                        )
                                                    )
                                                )
                                        )
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(12.dp),
                                            horizontalArrangement = Arrangement.End
                                        ) {
                                            Surface(
                                                shape = RoundedCornerShape(20.dp),
                                                color = Color.Black.copy(alpha = 0.5f),
                                                border = BorderStroke(1.dp, Color.White.copy(alpha = 0.3f))
                                            ) {
                                                Row(
                                                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                                ) {
                                                    Icon(Icons.Default.Collections, contentDescription = null, tint = Color.White, modifier = Modifier.size(13.dp))
                                                    Text(if (readHeaderImageIdx == 0) "Study Desk View" else "Fellowship View", fontSize = 11.sp, color = Color.White, fontWeight = FontWeight.SemiBold)
                                                }
                                            }
                                        }
                                        Column(
                                            modifier = Modifier
                                                .fillMaxSize()
                                                .padding(14.dp),
                                            verticalArrangement = Arrangement.Bottom
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Surface(
                                                    shape = RoundedCornerShape(20.dp),
                                                    color = Color(0xFF00E676),
                                                    contentColor = Color.Black
                                                ) {
                                                    Text(
                                                        text = selectedTranslation,
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp)
                                                    )
                                                }
                                                Surface(
                                                    shape = RoundedCornerShape(20.dp),
                                                    color = Color.White.copy(alpha = 0.25f),
                                                    contentColor = Color.White
                                                ) {
                                                    Text(
                                                        text = "${verses.size} Verses",
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.SemiBold,
                                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp)
                                                    )
                                                }
                                            }
                                            Spacer(modifier = Modifier.height(4.dp))
                                            Text(
                                                text = "$selectedBook $selectedChapter",
                                                fontSize = 22.sp,
                                                fontWeight = FontWeight.Bold,
                                                fontFamily = FontFamily.Serif,
                                                color = Color.White
                                            )
                                        }
                                    }
                                }
                            }

                            items(verses, key = { it.id }) { verse ->
                            val haptic = LocalHapticFeedback.current
                            // Find if favorited
                            val favorite = favorites.find {
                                it.translation == verse.translation &&
                                it.bookName == verse.bookName &&
                                it.chapter == verse.chapter &&
                                it.verseNumber == verse.verseNumber
                            }

                            val isCurrentlyReadingThisChapter = currentReadingTitle == "$selectedBook $selectedChapter"
                            val isCurrentlyReadingThisVerse = isCurrentlyReadingThisChapter && currentlyReadingVerseNumber == verse.verseNumber
                            val cardBgColor = when {
                                isCurrentlyReadingThisVerse -> MaterialTheme.colorScheme.primary.copy(alpha = 0.22f)
                                readerTheme == "Sepia" -> Color(0xFFF5E8CE)
                                readerTheme == "Dark" -> Color(0xFF1C1E2A)
                                else -> Color.Transparent
                            }
                            val cardBorder = when {
                                isCurrentlyReadingThisVerse -> androidx.compose.foundation.BorderStroke(2.dp, Color(0xFF00E676))
                                readerTheme == "Sepia" -> androidx.compose.foundation.BorderStroke(1.dp, Color(0xFFE5D5B5))
                                readerTheme == "Dark" -> androidx.compose.foundation.BorderStroke(1.dp, Color(0xFF2A2D3E))
                                else -> null
                            }

                            Card(
                                shape = RoundedCornerShape(8.dp),
                                colors = CardDefaults.cardColors(
                                    containerColor = cardBgColor
                                ),
                                border = cardBorder,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .redGlowBorder(enabled = isCurrentlyReadingThisVerse, shape = RoundedCornerShape(8.dp), glowColor = Color(0xFF00E676))
                                    .combinedClickable(
                                        onClick = {
                                            haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                                            viewModel.selectVerseForHighlight(verse)
                                        },
                                        onLongClick = {
                                            haptic.performHapticFeedback(HapticFeedbackType.LongPress)
                                            viewModel.selectVerseForHighlight(verse)
                                        }
                                    )
                            ) {
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(10.dp)
                                ) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            if (favorite != null) {
                                                Icon(
                                                    imageVector = Icons.Default.Favorite,
                                                    contentDescription = "Favorited",
                                                    tint = Color(0xFFFF1744),
                                                    modifier = Modifier.size(14.dp).padding(end = 4.dp)
                                                )
                                            }
                                            Text(
                                                text = "${verse.bookName} ${verse.chapter}:${verse.verseNumber}",
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 12.sp,
                                                color = if (readerTheme != "Light") readerThemeVerseNumColor else MaterialTheme.colorScheme.primary
                                            )
                                            if (isCurrentlyReadingThisVerse) {
                                                Spacer(modifier = Modifier.width(6.dp))
                                                Surface(
                                                    shape = RoundedCornerShape(12.dp),
                                                    color = MaterialTheme.colorScheme.primary,
                                                    border = BorderStroke(1.dp, Color(0xFF00E676))
                                                ) {
                                                    Row(
                                                        modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp),
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Icon(Icons.Default.VolumeUp, contentDescription = "Reading", tint = MaterialTheme.colorScheme.onPrimary, modifier = Modifier.size(11.dp))
                                                        Spacer(modifier = Modifier.width(3.dp))
                                                        Text("READING ALOUD", fontSize = 9.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onPrimary)
                                                    }
                                                }
                                            }
                                        }
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                                        ) {
                                            Text(
                                                text = if (isCompareMode) "$selectedTranslation vs $compareTranslation" else selectedTranslation,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 10.sp,
                                                color = if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.secondary
                                            )
                                            IconButton(
                                                onClick = {
                                                    verseToShareStudio = verse
                                                },
                                                modifier = Modifier
                                                    .size(24.dp)
                                                    .testTag("quick_share_verse_${verse.verseNumber}_btn")
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Share,
                                                    contentDescription = "Share Verse",
                                                    tint = if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.primary,
                                                    modifier = Modifier.size(15.dp)
                                                )
                                            }
                                        }
                                    }
                                    
                                    Spacer(modifier = Modifier.height(6.dp))

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        verticalAlignment = Alignment.Top
                                    ) {
                                        // Verse Number & Heart if favorited
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            modifier = Modifier.padding(end = 8.dp, top = 2.dp)
                                        ) {
                                            Text(
                                                text = "${verse.verseNumber}",
                                                fontWeight = FontWeight.Bold,
                                                fontSize = (readerFontSize - 2f).coerceAtLeast(12f).sp,
                                                color = if (readerTheme != "Light") readerThemeVerseNumColor else MaterialTheme.colorScheme.primary
                                            )
                                            if (favorite != null) {
                                                Spacer(modifier = Modifier.width(3.dp))
                                                Icon(
                                                    imageVector = Icons.Default.Favorite,
                                                    contentDescription = "Favorited",
                                                    tint = Color(0xFFFF1744),
                                                    modifier = Modifier.size(13.dp)
                                                )
                                            }
                                        }

                                        Column(modifier = Modifier.weight(1f)) {
                                            if (isCompareMode) {
                                                val compFontSize = (readerFontSize - 2f).coerceAtLeast(12f)
                                                val compLineHeightSp = if (isDyslexic) (compFontSize * (readerLineHeightMultiplier + 0.35f)).sp else (compFontSize * readerLineHeightMultiplier).sp
                                                val compVerse = comparedVerses.find { it.verseNumber == verse.verseNumber }

                                                if (compareSideBySide) {
                                                    Row(
                                                        modifier = Modifier.fillMaxWidth(),
                                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                    ) {
                                                        // Column 1: Primary Translation
                                                        Column(
                                                            modifier = Modifier
                                                                .weight(1f)
                                                                .background(
                                                                    color = (if (readerTheme != "Light") readerThemeBgColor else MaterialTheme.colorScheme.surfaceVariant).copy(alpha = 0.35f),
                                                                    shape = RoundedCornerShape(8.dp)
                                                                )
                                                                .border(
                                                                    width = 1.dp,
                                                                    color = (if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.onSurface).copy(alpha = 0.12f),
                                                                    shape = RoundedCornerShape(8.dp)
                                                                )
                                                                .padding(8.dp)
                                                        ) {
                                                            Text(
                                                                text = selectedTranslation,
                                                                fontSize = 10.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = if (readerTheme != "Light") readerThemeVerseNumColor else MaterialTheme.colorScheme.primary,
                                                                modifier = Modifier.padding(bottom = 4.dp)
                                                            )
                                                            Text(
                                                                text = verse.text,
                                                                fontSize = compFontSize.sp,
                                                                fontFamily = selectedFontFamily,
                                                                lineHeight = compLineHeightSp,
                                                                letterSpacing = dyslexicLetterSpacing,
                                                                fontWeight = dyslexicFontWeight,
                                                                color = if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground
                                                            )
                                                        }

                                                        // Column 2: Secondary Translation
                                                        Column(
                                                            modifier = Modifier
                                                                .weight(1f)
                                                                .background(
                                                                    color = (if (readerTheme != "Light") readerThemeBgColor else MaterialTheme.colorScheme.surfaceVariant).copy(alpha = 0.35f),
                                                                    shape = RoundedCornerShape(8.dp)
                                                                )
                                                                .border(
                                                                    width = 1.dp,
                                                                    color = (if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.onSurface).copy(alpha = 0.12f),
                                                                    shape = RoundedCornerShape(8.dp)
                                                                )
                                                                .padding(8.dp)
                                                        ) {
                                                            Text(
                                                                text = compareTranslation,
                                                                fontSize = 10.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = if (readerTheme != "Light") readerThemeVerseNumColor else MaterialTheme.colorScheme.secondary,
                                                                modifier = Modifier.padding(bottom = 4.dp)
                                                            )
                                                            if (compVerse != null) {
                                                                Text(
                                                                    text = compVerse.text,
                                                                    fontSize = compFontSize.sp,
                                                                    fontFamily = selectedFontFamily,
                                                                    lineHeight = compLineHeightSp,
                                                                    letterSpacing = dyslexicLetterSpacing,
                                                                    fontWeight = dyslexicFontWeight,
                                                                    color = (if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground).copy(alpha = 0.9f)
                                                                )
                                                            } else {
                                                                Text(
                                                                    text = "[$compareTranslation: tap to download in settings]",
                                                                    fontSize = 11.sp,
                                                                    color = MaterialTheme.colorScheme.error,
                                                                    fontStyle = FontStyle.Italic
                                                                )
                                                            }
                                                        }
                                                    }
                                                } else {
                                                    // Stacked layout
                                                    Text(
                                                        text = "$selectedTranslation: ${verse.text}",
                                                        fontSize = compFontSize.sp,
                                                        fontFamily = selectedFontFamily,
                                                        lineHeight = compLineHeightSp,
                                                        letterSpacing = dyslexicLetterSpacing,
                                                        fontWeight = dyslexicFontWeight,
                                                        color = if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground
                                                    )
                                                    if (compVerse != null) {
                                                        Spacer(modifier = Modifier.height(8.dp))
                                                        HorizontalDivider(color = (if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.onSurface).copy(alpha = 0.12f))
                                                        Spacer(modifier = Modifier.height(8.dp))
                                                        Text(
                                                            text = "$compareTranslation: ${compVerse.text}",
                                                            fontSize = compFontSize.sp,
                                                            fontFamily = selectedFontFamily,
                                                            lineHeight = compLineHeightSp,
                                                            letterSpacing = dyslexicLetterSpacing,
                                                            fontWeight = dyslexicFontWeight,
                                                            color = (if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground).copy(alpha = 0.85f),
                                                            fontStyle = FontStyle.Italic
                                                        )
                                                    } else {
                                                        Spacer(modifier = Modifier.height(4.dp))
                                                        Text(
                                                            text = "[$compareTranslation: tap to download in settings]",
                                                            fontSize = 12.sp,
                                                            color = MaterialTheme.colorScheme.error,
                                                            fontStyle = FontStyle.Italic
                                                        )
                                                    }
                                                }
                                            } else {
                                                // Verse Text
                                                Text(
                                                    text = verse.text,
                                                    fontSize = readerFontSize.sp,
                                                    fontFamily = selectedFontFamily,
                                                    lineHeight = currentLineHeightSp,
                                                    letterSpacing = dyslexicLetterSpacing,
                                                    fontWeight = dyslexicFontWeight,
                                                    color = if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        
                        // 3. Scripture Timeline (Chronological Flow)
                        item {
                            Spacer(modifier = Modifier.height(24.dp))
                            HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f))
                            Spacer(modifier = Modifier.height(16.dp))
                            
                            Column(modifier = Modifier.fillMaxWidth()) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.History,
                                        contentDescription = null,
                                        tint = MaterialTheme.colorScheme.primary,
                                        modifier = Modifier.size(20.dp)
                                    )
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text(
                                        text = "Chronological Narrative Flow ⏳",
                                        style = MaterialTheme.typography.titleMedium,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.primary
                                    )
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = "Tap on major historical milestones to navigate directly to their scriptures.",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                )
                                Spacer(modifier = Modifier.height(12.dp))
                                
                                androidx.compose.foundation.lazy.LazyRow(
                                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                                    contentPadding = PaddingValues(bottom = 8.dp),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    items(viewModel.timelineEvents) { event ->
                                        val (targetBook, targetChapter) = parseScriptureRef(event.scriptureRef)
                                        val isActive = selectedBook.equals(targetBook, ignoreCase = true) && selectedChapter == targetChapter
                                        
                                        Card(
                                            modifier = Modifier
                                                .width(260.dp)
                                                .height(145.dp)
                                                .clickable {
                                                    viewModel.selectBook(targetBook)
                                                    viewModel.selectChapter(targetChapter)
                                                    viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                                                    viewModel.logReadingHistory(targetBook, targetChapter)
                                                }
                                                .testTag("timeline_nav_card_${event.title.replace(" ", "_")}"),
                                            colors = CardDefaults.cardColors(
                                                containerColor = if (isActive) {
                                                    MaterialTheme.colorScheme.primaryContainer
                                                } else {
                                                    MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                                                }
                                            ),
                                            shape = RoundedCornerShape(12.dp),
                                            border = androidx.compose.foundation.BorderStroke(
                                                width = if (isActive) 2.2.dp else 1.5.dp,
                                                color = if (isActive) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline.copy(alpha = 0.35f)
                                            )
                                        ) {
                                            Column(
                                                modifier = Modifier.padding(12.dp).fillMaxSize(),
                                                verticalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Column {
                                                    Row(
                                                        modifier = Modifier.fillMaxWidth(),
                                                        horizontalArrangement = Arrangement.SpaceBetween,
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Row(
                                                            verticalAlignment = Alignment.CenterVertically,
                                                            modifier = Modifier.weight(1f)
                                                        ) {
                                                            Icon(
                                                                imageVector = getTimelineIcon(event.iconName),
                                                                contentDescription = null,
                                                                tint = if (isActive) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant,
                                                                modifier = Modifier.size(16.dp)
                                                            )
                                                            Spacer(modifier = Modifier.width(6.dp))
                                                            Text(
                                                                text = event.title,
                                                                fontWeight = FontWeight.Bold,
                                                                fontSize = 11.sp,
                                                                maxLines = 1,
                                                                color = if (isActive) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurface,
                                                                overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                                                            )
                                                        }
                                                        if (isActive) {
                                                            Card(
                                                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primary),
                                                                shape = RoundedCornerShape(4.dp)
                                                            ) {
                                                                Text(
                                                                    text = "CURRENT",
                                                                    fontSize = 8.sp,
                                                                    fontWeight = FontWeight.Bold,
                                                                    color = MaterialTheme.colorScheme.onPrimary,
                                                                    modifier = Modifier.padding(horizontal = 4.dp, vertical = 2.dp)
                                                                )
                                                            }
                                                        }
                                                    }
                                                    Spacer(modifier = Modifier.height(4.dp))
                                                    Text(
                                                        text = event.description,
                                                        fontSize = 10.sp,
                                                        lineHeight = 14.sp,
                                                        maxLines = 3,
                                                        overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
                                                        color = if (isActive) MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f) else MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                                                    )
                                                }
                                                
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text(
                                                        text = event.period,
                                                        fontSize = 9.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = MaterialTheme.colorScheme.primary
                                                    )
                                                    Text(
                                                        text = event.scriptureRef,
                                                        fontSize = 9.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        fontStyle = FontStyle.Italic,
                                                        color = MaterialTheme.colorScheme.secondary
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        
                        // 4. Chapter Cross-References Section for Deeper Study (Animated Carousel & Transitions)
                        item {
                            AnimatedCrossRefSection(
                                selectedBook = selectedBook,
                                selectedChapter = selectedChapter,
                                readerTheme = readerTheme,
                                readerThemeBgColor = readerThemeBgColor,
                                readerThemeVerseNumColor = readerThemeVerseNumColor,
                                readerThemeSubtextColor = readerThemeSubtextColor,
                                viewModel = viewModel,
                                context = context
                            )
                        }

                        // Bottom margin spacer / Continue to next chapter card
                        item {
                            Card(
                                onClick = {
                                    viewModel.selectNextChapter()
                                    viewModel.selectVerse(1)
                                },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 12.dp)
                                    .testTag("continue_to_next_chapter_card"),
                                colors = CardDefaults.cardColors(
                                    containerColor = MaterialTheme.colorScheme.primaryContainer
                                ),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Row(
                                    modifier = Modifier.padding(16.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.AutoMirrored.Filled.ArrowForward,
                                        contentDescription = null,
                                        tint = MaterialTheme.colorScheme.onPrimaryContainer
                                    )
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Text(
                                        text = translateUi("Continue to Next Chapter", appLanguageState) + " ➡️",
                                        fontWeight = FontWeight.Bold,
                                        style = MaterialTheme.typography.titleMedium,
                                    )
                                }
                            }
                            Spacer(modifier = Modifier.height(24.dp))
                        }
                    }
                }
                }
            }
        }
    }

    // Reader Typography & Visual Settings Modal Dialog
    if (showReaderSettingsModal) {
        ReaderSettingsModalDialog(
            currentTheme = readerTheme,
            currentFontSize = readerFontSize,
            currentLineHeight = readerLineHeightMultiplier,
            currentFontFamily = readerFontFamily,
            onThemeSelected = { viewModel.setReaderTheme(it) },
            onFontSizeChanged = { viewModel.setReaderFontSize(it) },
            onLineHeightChanged = { viewModel.setReaderLineHeightMultiplier(it) },
            onFontFamilySelected = { viewModel.setReaderFontFamily(it) },
            onDismiss = { showReaderSettingsModal = false }
        )
    }

    // Highlighting & Favorite Popup Dialog & Context Study Panel
    if (highlightedVerseForPopup != null) {
        val verse = highlightedVerseForPopup!!
        val context = LocalContext.current
        var studyTabState by remember { mutableStateOf(0) }
        
        Dialog(onDismissRequest = { viewModel.selectVerseForHighlight(null) }) {
            Card(
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                modifier = Modifier
                    .fillMaxWidth()
                    .fillMaxHeight(0.88f)
                    .padding(4.dp)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Title/Header with book, chapter, and verse
                    Text(
                        text = "${verse.bookName} ${verse.chapter}:${verse.verseNumber} (${verse.translation})",
                        fontWeight = FontWeight.Bold,
                        style = MaterialTheme.typography.titleMedium,
                        color = MaterialTheme.colorScheme.primary
                    )
                    
                    Spacer(modifier = Modifier.height(8.dp))
                    
                    // Verse Text Quote Container
                    Card(
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Text(
                            text = "\"${verse.text}\"",
                            fontStyle = FontStyle.Italic,
                            fontSize = 14.sp,
                            textAlign = TextAlign.Center,
                            lineHeight = 20.sp,
                            modifier = Modifier.padding(12.dp)
                        )
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    // Row for highlighting dots and actions
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // Highlight Colors
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            HighlightColorDot(color = LivelyRed, name = "Red") {
                                viewModel.highlightVerse(verse, "#FF1744")
                            }
                            HighlightColorDot(color = GreenTone, name = "Vibrant Green") {
                                viewModel.highlightVerse(verse, "#00FF00")
                            }
                            HighlightColorDot(color = Color(0xFFFF4081), name = "Pink") {
                                viewModel.highlightVerse(verse, "#FF4081")
                            }
                            HighlightColorDot(color = Color(0xFFFFD54F), name = "Amber") {
                                viewModel.highlightVerse(verse, "#FFD54F")
                            }
                        }

                        // Bookmark State Button
                        val isBookmarked = bookmarks.any {
                            it.translation == verse.translation &&
                            it.bookName == verse.bookName &&
                            it.chapter == verse.chapter &&
                            it.verseNumber == verse.verseNumber
                        }

                        IconButton(
                            onClick = {
                                viewModel.toggleBookmark(verse)
                                Toast.makeText(context, if (isBookmarked) "Bookmark removed" else "Added to Bookmarks!", Toast.LENGTH_SHORT).show()
                                viewModel.selectVerseForHighlight(null)
                            }
                        ) {
                            Icon(
                                imageVector = if (isBookmarked) Icons.Default.Bookmark else Icons.Default.BookmarkBorder,
                                contentDescription = if (isBookmarked) "Bookmarked" else "Bookmark",
                                tint = if (isBookmarked) MaterialTheme.colorScheme.secondary else MaterialTheme.colorScheme.primary,
                                modifier = Modifier.size(24.dp)
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    // Toolbar action buttons (Copy, Read Aloud, and Share Card Studio)
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        OutlinedButton(
                            onClick = {
                                val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
                                val clip = ClipData.newPlainText("Scripture", "${verse.bookName} ${verse.chapter}:${verse.verseNumber} - ${verse.text}")
                                clipboard.setPrimaryClip(clip)
                                Toast.makeText(context, "Copied verse to clipboard!", Toast.LENGTH_SHORT).show()
                                viewModel.selectVerseForHighlight(null)
                            },
                            modifier = Modifier.weight(1f).height(36.dp)
                        ) {
                            Icon(Icons.Default.ContentCopy, contentDescription = null, modifier = Modifier.size(14.dp))
                            Spacer(modifier = Modifier.width(2.dp))
                            Text("Copy", fontSize = 11.sp)
                        }

                        Button(
                            onClick = {
                                speakText(verse.text, "${verse.bookName} ${verse.chapter}:${verse.verseNumber}")
                                viewModel.selectVerseForHighlight(null)
                            },
                            modifier = Modifier.weight(1.1f).height(36.dp).testTag("read_aloud_btn")
                        ) {
                            Icon(Icons.Default.VolumeUp, contentDescription = null, modifier = Modifier.size(14.dp))
                            Spacer(modifier = Modifier.width(2.dp))
                            Text("Read", fontSize = 11.sp)
                        }

                        Button(
                            onClick = {
                                verseToShareStudio = verse
                                viewModel.selectVerseForHighlight(null)
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary),
                            modifier = Modifier.weight(1.3f).height(36.dp).testTag("open_share_card_studio_btn")
                        ) {
                            Icon(Icons.Default.Share, contentDescription = null, modifier = Modifier.size(14.dp))
                            Spacer(modifier = Modifier.width(4.dp))
                            Text("Share Card", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))

                    Button(
                        onClick = {
                            viewModel.generateDevotionalForVerse(verse)
                            viewModel.selectVerseForHighlight(null)
                            viewModel.navigateTo(Screen.DEVOTIONS)
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.tertiary),
                        modifier = Modifier.fillMaxWidth().height(38.dp).testTag("generate_verse_devotional_btn")
                    ) {
                        Icon(Icons.Default.AutoAwesome, contentDescription = null, modifier = Modifier.size(16.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text("Generate AI Devotional for this Verse", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    }

                    Spacer(modifier = Modifier.height(12.dp))
                    HorizontalDivider(thickness = 1.dp, color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                    Spacer(modifier = Modifier.height(8.dp))

                    // Tabrow Switcher for Context Panel
                    ScrollableTabRow(
                        selectedTabIndex = studyTabState,
                        containerColor = Color.Transparent,
                        edgePadding = 0.dp,
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Tab(
                            selected = studyTabState == 0,
                            onClick = { studyTabState = 0 },
                            text = { Text("Timeline", fontSize = 12.sp, fontWeight = FontWeight.Bold) }
                        )
                        Tab(
                            selected = studyTabState == 1,
                            onClick = { studyTabState = 1 },
                            text = { Text("Cross Refs", fontSize = 12.sp, fontWeight = FontWeight.Bold) }
                        )
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    // Scrollable study tab content
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxWidth()
                            .verticalScroll(rememberScrollState())
                    ) {
                        when (studyTabState) {
                            0 -> {
                                // Timeline Tab
                                val relevantEvents = remember(verse.bookName) {
                                    val b = verse.bookName.lowercase().trim()
                                    val allEvents = viewModel.timelineEvents
                                    when {
                                        b == "genesis" -> allEvents.filter { it.title in listOf("Creation & The Fall", "The Great Flood & Covenant", "The Call of Abraham") }
                                        b in listOf("exodus", "leviticus", "numbers", "deuteronomy") -> allEvents.filter { it.title in listOf("The Exodus from Egypt", "The Giving of the Law") }
                                        b in listOf("joshua", "judges", "ruth", "1 samuel", "2 samuel", "1 chronicles", "2 chronicles") -> allEvents.filter { it.title == "The Reign of King David" }
                                        b in listOf("1 kings", "2 kings") -> allEvents.filter { it.title in listOf("The Reign of King David", "The Division of the Kingdom", "Babylonian Exile") }
                                        b in listOf("ezra", "nehemiah", "esther", "daniel", "ezekiel", "jeremiah", "lamentations") -> allEvents.filter { it.title == "Babylonian Exile" }
                                        b in listOf("matthew", "mark", "luke", "john") -> allEvents.filter { it.title in listOf("Birth of Jesus Christ", "The Sermon on the Mount", "Crucifixion, Resurrection & Ascension") }
                                        else -> allEvents.filter { it.title == "Pentecost & The Early Church" }
                                    }
                                }

                                Column(modifier = Modifier.padding(4.dp)) {
                                    Text(
                                        text = "Historical Redemptive Context",
                                        fontWeight = FontWeight.Bold,
                                        style = MaterialTheme.typography.titleSmall,
                                        color = GreenTone,
                                        modifier = Modifier.padding(bottom = 6.dp)
                                    )
                                    relevantEvents.forEach { event ->
                                        Card(
                                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)),
                                            shape = RoundedCornerShape(12.dp),
                                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)
                                        ) {
                                            Row(modifier = Modifier.padding(12.dp), verticalAlignment = Alignment.Top) {
                                                Icon(
                                                    imageVector = getTimelineIcon(event.iconName),
                                                    contentDescription = null,
                                                    tint = GreenTone,
                                                    modifier = Modifier.size(24.dp).padding(end = 8.dp)
                                                )
                                                Column {
                                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                                        Text(event.title, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = MaterialTheme.colorScheme.onSurface)
                                                        Text(event.period, fontSize = 11.sp, color = GreenTone, fontWeight = FontWeight.SemiBold)
                                                    }
                                                    Spacer(modifier = Modifier.height(4.dp))
                                                    Text(event.description, fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                                    Spacer(modifier = Modifier.height(6.dp))
                                                    Text("Ref: ${event.scriptureRef}", fontSize = 11.sp, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            1 -> {
                                // Cross References Tab
                                val crossRefs = remember(verse.bookName, verse.chapter, verse.verseNumber) {
                                    val b = verse.bookName.lowercase().trim()
                                    val ch = verse.chapter
                                    val vNum = verse.verseNumber
                                    when (b) {
                                        "genesis" -> {
                                            if (ch == 1 && vNum == 1) {
                                                listOf(
                                                    "John 1:1-3" to "In the beginning was the Word, and the Word was with God, and the Word was God. He was in the beginning with God. All things were made through him...",
                                                    "Hebrews 11:3" to "By faith we understand that the universe was created by the word of God, so that what is seen was not made out of things that are visible.",
                                                    "Psalms 102:25" to "Of old you laid the foundation of the earth, and the heavens are the work of your hands."
                                                )
                                            } else {
                                                listOf(
                                                    "Hebrews 11:1-6" to "Now faith is the assurance of things hoped for, the conviction of things not seen. For by it the people of old received their commendation.",
                                                    "Romans 4:3" to "For what does the Scripture say? 'Abraham believed God, and it was counted to him as righteousness.'"
                                                )
                                            }
                                        }
                                        "exodus" -> {
                                            listOf(
                                                "Hebrews 11:24-27" to "By faith Moses, when he was grown up, refused to be called the son of Pharaoh's daughter, choosing rather to be mistreated with the people of God...",
                                                "John 1:17" to "For the law was given through Moses; grace and truth came through Jesus Christ."
                                            )
                                        }
                                        "matthew" -> {
                                            if (ch == 6 && vNum == 33) {
                                                listOf(
                                                    "Luke 12:31" to "Instead, seek his kingdom, and these things will be added to you.",
                                                    "Psalms 37:4" to "Delight yourself in the LORD, and he will give you the desires of your heart.",
                                                    "Philippians 4:19" to "And my God will supply every need of yours according to his riches in glory in Christ Jesus."
                                                )
                                            } else {
                                                listOf(
                                                    "Mark 1:14-15" to "Now after John was arrested, Jesus came into Galilee, proclaiming the gospel of God, and saying, 'The time is fulfilled, and the kingdom of God is at hand...'",
                                                    "Romans 14:17" to "For the kingdom of God is not a matter of eating and drinking but of righteousness and peace and joy in the Holy Spirit."
                                                )
                                            }
                                        }
                                        "john" -> {
                                            if (ch == 3 && vNum == 16) {
                                                listOf(
                                                    "Romans 5:8" to "But God shows his love for us in that while we were still sinners, Christ died for us.",
                                                    "1 John 4:9" to "In this the love of God was made manifest among us, that God sent his only Son into the world, so that we might live through him.",
                                                    "Ephesians 2:4-5" to "But God, being rich in mercy, because of the great love with which he loved us, even when we were dead in our trespasses, made us alive together with Christ..."
                                                )
                                            } else if (ch == 1 && vNum == 1) {
                                                listOf(
                                                    "Genesis 1:1" to "In the beginning, God created the heavens and the earth.",
                                                    "Colossians 1:16-17" to "For by him all things were created, in heaven and on earth, visible and invisible... All things were created through him and for him.",
                                                    "1 John 1:1" to "That which was from the beginning, which we have heard, which we have seen with our eyes, which we looked upon and have touched with our hands..."
                                                )
                                            } else {
                                                listOf(
                                                    "John 20:31" to "But these are written so that you may believe that Jesus is the Christ, the Son of God, and that by believing you may have life in his name.",
                                                    "Galatians 2:20" to "I have been crucified with Christ. It is no longer I who live, but Christ who lives in me. And the life I now live in the flesh I live by faith..."
                                                )
                                            }
                                        }
                                        "romans" -> {
                                            if (ch == 12 && vNum == 1) {
                                                listOf(
                                                    "Romans 12:2" to "Do not be conformed to this world, but be transformed by the renewal of your mind, that by testing you may discern what is the will of God...",
                                                    "1 Peter 2:5" to "You yourselves like living stones are being built up as a spiritual house, to be a holy priesthood, to offer spiritual sacrifices acceptable to God through Jesus Christ.",
                                                    "Hebrews 13:15" to "Through him then let us continually offer up a sacrifice of praise to God, that is, the fruit of lips that acknowledge his name."
                                                )
                                            } else {
                                                listOf(
                                                    "Romans 3:23" to "For all have sinned and fall short of the glory of God.",
                                                    "Romans 6:23" to "For the wages of sin is death, but the free gift of God is eternal life in Christ Jesus our Lord."
                                                )
                                            }
                                        }
                                        "psalms" -> {
                                            if (ch == 23) {
                                                listOf(
                                                    "John 10:11" to "I am the good shepherd. The good shepherd lays down his life for the sheep.",
                                                    "Isaiah 40:11" to "He will tend his flock like a shepherd; he will gather the lambs in his arms; he will carry them in his bosom, and gently lead those that are with young.",
                                                    "Revelation 7:17" to "For the Lamb in the midst of the throne will be their shepherd, and he will guide them to springs of living water, and God will wipe away every tear from their eyes."
                                                )
                                            } else {
                                                listOf(
                                                    "Psalms 119:105" to "Your word is a lamp to my feet and a light to my path.",
                                                    "Psalms 46:1" to "God is our refuge and strength, a very present help in trouble."
                                                )
                                            }
                                        }
                                        else -> {
                                            listOf(
                                                "Hebrews 4:12" to "For the word of God is living and active, sharper than any two-edged sword, piercing to the division of soul and of spirit...",
                                                "2 Timothy 3:16-17" to "All Scripture is breathed out by God and profitable for teaching, for reproof, for correction, and for training in righteousness..."
                                            )
                                        }
                                    }
                                }

                                Column(modifier = Modifier.padding(4.dp)) {
                                    Text(
                                        text = "Interactive Cross References",
                                        fontWeight = FontWeight.Bold,
                                        style = MaterialTheme.typography.titleSmall,
                                        color = GreenTone,
                                        modifier = Modifier.padding(bottom = 6.dp)
                                    )
                                    Text(
                                        text = "Tap a reference below to instantly jump to that passage.",
                                        fontSize = 11.sp,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                                        modifier = Modifier.padding(bottom = 8.dp)
                                    )
                                    crossRefs.forEach { (ref, txt) ->
                                        Card(
                                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.4f)),
                                            shape = RoundedCornerShape(12.dp),
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(vertical = 4.dp)
                                                .clickable {
                                                    try {
                                                        val lastSpace = ref.lastIndexOf(' ')
                                                        if (lastSpace != -1) {
                                                            val book = ref.substring(0, lastSpace).trim()
                                                            val chapVerse = ref.substring(lastSpace + 1).trim()
                                                            val colonIdx = chapVerse.indexOf(':')
                                                            if (colonIdx != -1) {
                                                                val chapterStr = chapVerse.substring(0, colonIdx)
                                                                val versePart = chapVerse.substring(colonIdx + 1)
                                                                val dashIdx = versePart.indexOf('-')
                                                                val verseStr = if (dashIdx != -1) versePart.substring(0, dashIdx) else versePart
                                                                
                                                                val chapterNum = chapterStr.toIntOrNull() ?: 1
                                                                val verseNum = verseStr.toIntOrNull() ?: 1
                                                                
                                                                viewModel.selectBook(book)
                                                                viewModel.selectChapter(chapterNum)
                                                                viewModel.selectVerse(verseNum)
                                                                viewModel.selectVerseForHighlight(null)
                                                                Toast.makeText(context, "Navigated to $ref", Toast.LENGTH_SHORT).show()
                                                            }
                                                        }
                                                    } catch (e: Exception) {
                                                        e.printStackTrace()
                                                    }
                                                }
                                        ) {
                                            Column(modifier = Modifier.padding(10.dp)) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.SpaceBetween
                                                ) {
                                                    Text(ref, fontWeight = FontWeight.Bold, fontSize = 12.sp, color = MaterialTheme.colorScheme.primary)
                                                    Icon(Icons.Default.ArrowForward, contentDescription = "Jump", tint = GreenTone, modifier = Modifier.size(14.dp))
                                                }
                                                Spacer(modifier = Modifier.height(4.dp))
                                                Text("\"$txt\"", fontSize = 11.sp, fontStyle = FontStyle.Italic, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Button(
                            onClick = {
                                showVersionComparerForVerse = verse
                                viewModel.selectVerseForHighlight(null)
                            },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = MaterialTheme.colorScheme.secondaryContainer,
                                contentColor = MaterialTheme.colorScheme.onSecondaryContainer
                            ),
                            modifier = Modifier.weight(1f).height(38.dp).testTag("popup_compare_versions_btn")
                        ) {
                            Icon(Icons.Default.Compare, contentDescription = null, modifier = Modifier.size(14.dp))
                            Spacer(modifier = Modifier.width(4.dp))
                            Text("Compare Versions", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }

                        Button(
                            onClick = { viewModel.selectVerseForHighlight(null) },
                            colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary),
                            modifier = Modifier.weight(1f).height(38.dp).testTag("cancel_popup_btn")
                        ) {
                            Text("Dismiss", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }
    }

    if (showVersionComparerForVerse != null) {
        VersionComparerDialog(
            verse = showVersionComparerForVerse!!,
            viewModel = viewModel,
            onDismiss = { showVersionComparerForVerse = null }
        )
    }

    verseToShareStudio?.let { verse ->
        ScriptureShareStudioDialog(
            verse = verse,
            onDismiss = { verseToShareStudio = null }
        )
    }

    selectedBookForGuide?.let { bookName ->
        val guide = BookOverviews.getOverviewForBook(bookName)
        Dialog(onDismissRequest = { selectedBookForGuide = null }) {
            Card(
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp)
            ) {
                Column(
                    modifier = Modifier
                        .padding(18.dp)
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = guide.name,
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold,
                            fontFamily = FontFamily.Serif,
                            color = MaterialTheme.colorScheme.primary
                        )
                        IconButton(onClick = { selectedBookForGuide = null }) {
                            Icon(Icons.Default.Close, "Close")
                        }
                    }

                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        SuggestionChip(onClick = {}, label = { Text(guide.category) })
                        SuggestionChip(onClick = {}, label = { Text("Author: ${guide.author}") })
                        
                        val overviewTitle = "Book of ${guide.name} Overview"
                        val isListeningOverview = currentReadingTitle == overviewTitle
                        AssistChip(
                            onClick = {
                                if (isListeningOverview) {
                                    stopSpeaking()
                                } else {
                                    val speakTextForGuide = "Book of ${guide.name}. Category: ${guide.category}. Author: ${guide.author}. Key Theme: ${guide.theme}. Key Scripture: ${guide.keyVerse}. Summary Overview: ${guide.summary}."
                                    speakText(speakTextForGuide, overviewTitle)
                                }
                            },
                            label = {
                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                    Icon(
                                        imageVector = if (isListeningOverview) Icons.Default.VolumeOff else Icons.Default.VolumeUp,
                                        contentDescription = if (isListeningOverview) "Stop" else "Listen",
                                        modifier = Modifier.size(14.dp),
                                        tint = if (isListeningOverview) Color(0xFF00E676) else MaterialTheme.colorScheme.primary
                                    )
                                    Text(if (isListeningOverview) "Stop" else "Listen", fontSize = 11.sp)
                                }
                            },
                            modifier = Modifier.testTag("listen_book_overview_btn")
                        )
                    }

                    RowValue(label = "Date Written", value = guide.dateWritten)
                    RowValue(label = "Key Theme", value = guide.theme)

                    Card(
                        shape = RoundedCornerShape(12.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.25f)),
                        modifier = Modifier.fillMaxWidth(),
                        border = androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.1f))
                    ) {
                        Column(modifier = Modifier.padding(14.dp)) {
                            Text("🔑 KEY SCRIPTURE", fontSize = 11.sp, fontWeight = FontWeight.ExtraBold, color = MaterialTheme.colorScheme.primary, letterSpacing = 0.5.sp)
                            Spacer(modifier = Modifier.height(6.dp))
                            Text(
                                text = guide.keyVerse,
                                fontStyle = FontStyle.Italic,
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onPrimaryContainer,
                                fontWeight = FontWeight.Medium,
                                lineHeight = 18.sp
                            )
                        }
                    }

                    Text("📖 Summary Overview", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.titleSmall)
                    Text(
                        text = formatDocumentText(guide.summary),
                        fontSize = 14.sp,
                        lineHeight = 21.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.85f)
                    )

                    // Key Characters Section
                    if (guide.keyCharacters.isNotEmpty() || guide.characters.isNotEmpty()) {
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("👥 Key Characters & Figures", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.titleSmall)
                        if (guide.keyCharacters.isNotEmpty()) {
                            FlowRow(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                guide.keyCharacters.forEach { char ->
                                    Surface(
                                        shape = RoundedCornerShape(8.dp),
                                        color = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.6f),
                                        contentColor = MaterialTheme.colorScheme.onSecondaryContainer
                                    ) {
                                        Text(text = char, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp))
                                    }
                                }
                            }
                        } else {
                            Text(
                                text = formatDocumentText(guide.characters),
                                fontSize = 13.sp,
                                lineHeight = 19.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                            )
                        }
                    }

                    // Spiritual Lessons Section
                    if (guide.centralLessons.isNotEmpty() || guide.lessons.isNotEmpty()) {
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("💡 Essential Spiritual Lessons", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.titleSmall)
                        if (guide.centralLessons.isNotEmpty()) {
                            Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                guide.centralLessons.forEach { lesson ->
                                    Row(verticalAlignment = Alignment.Top, modifier = Modifier.fillMaxWidth()) {
                                        Text("• ", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                        Text(
                                            text = formatDocumentText(lesson),
                                            fontSize = 13.sp,
                                            lineHeight = 18.sp,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                                        )
                                    }
                                }
                            }
                        } else {
                            Text(
                                text = formatDocumentText(guide.lessons),
                                fontSize = 13.sp,
                                lineHeight = 19.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                            )
                        }
                    }

                    // Major Scenes Outline
                    if (guide.majorScenes.isNotEmpty()) {
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("📍 Major Scenes & Historical Outline", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.titleSmall)
                        Text(
                            text = formatDocumentText(guide.majorScenes),
                            fontSize = 13.sp,
                            lineHeight = 19.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                        )
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Button(
                        onClick = {
                            viewModel.updateAiTopicInput("A devotional based on the themes of the Book of $bookName")
                            viewModel.navigateTo(Screen.DEVOTIONS)
                            selectedBookForGuide = null
                        },
                        modifier = Modifier.fillMaxWidth().testTag("ai_devotion_from_guide_btn")
                    ) {
                        Icon(Icons.Default.AutoAwesome, null, modifier = Modifier.size(16.dp))
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Generate AI Devotion")
                    }
                }
            }
        }
    }
        }
    } // Close Column

// -----------------------------------------------------------------
// QUICK JUMP DIALOG FOR DIRECT SCRIPTURE NAVIGATION
// -----------------------------------------------------------------
@Composable
fun QuickJumpDialog(
    viewModel: BibleViewModel,
    onDismiss: () -> Unit
) {
    var searchQuery by remember { mutableStateOf("") }
    val selectedBookState by viewModel.selectedBook.collectAsStateWithLifecycle()
    val selectedChapterState by viewModel.selectedChapter.collectAsStateWithLifecycle()

    var selectedBook by remember { mutableStateOf(if (selectedBookState.isNotBlank()) selectedBookState else "Matthew") }
    var selectedChapter by remember { mutableIntStateOf(selectedChapterState) }

    val context = LocalContext.current

    val allBooks = remember {
        listOf(
            "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy", "Joshua", "Judges", "Ruth",
            "1 Samuel", "2 Samuel", "1 Kings", "2 Kings", "1 Chronicles", "2 Chronicles", "Ezra",
            "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "Song of Solomon",
            "Isaiah", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel", "Amos",
            "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi",
            "Matthew", "Mark", "Luke", "John", "Acts", "Romans", "1 Corinthians", "2 Corinthians",
            "Galatians", "Ephesians", "Philippians", "Colossians", "1 Thessalonians", "2 Thessalonians",
            "1 Timothy", "2 Timothy", "Titus", "Philemon", "Hebrews", "James", "1 Peter", "2 Peter",
            "1 John", "2 John", "3 John", "Jude", "Revelation"
        )
    }

    val filteredBooks = remember(searchQuery) {
        if (searchQuery.isBlank()) allBooks else allBooks.filter { it.contains(searchQuery, ignoreCase = true) }
    }

    Dialog(
        onDismissRequest = onDismiss,
        properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Card(
            shape = RoundedCornerShape(24.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            elevation = CardDefaults.cardElevation(defaultElevation = 8.dp),
            modifier = Modifier
                .fillMaxWidth(0.92f)
                .padding(16.dp)
                .testTag("quick_jump_dialog")
        ) {
            Column(
                modifier = Modifier
                    .padding(20.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(14.dp)
            ) {
                // Header
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        Box(
                            modifier = Modifier
                                .size(40.dp)
                                .clip(CircleShape)
                                .background(MaterialTheme.colorScheme.primaryContainer),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(Icons.Default.Bolt, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(22.dp))
                        }
                        Column {
                            Text("Quick Jump ⚡", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                            Text("Jump directly to book & chapter", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f))
                        }
                    }
                    IconButton(onClick = onDismiss) {
                        Icon(Icons.Default.Close, contentDescription = "Close")
                    }
                }

                // Search Bar
                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { searchQuery = it },
                    placeholder = { Text("Filter book (e.g. John, Psalms, Gen)...", fontSize = 13.sp) },
                    leadingIcon = { Icon(Icons.Default.Search, contentDescription = null, tint = MaterialTheme.colorScheme.primary) },
                    trailingIcon = {
                        if (searchQuery.isNotEmpty()) {
                            IconButton(onClick = { searchQuery = "" }) {
                                Icon(Icons.Default.Clear, contentDescription = "Clear search")
                            }
                        }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("quick_jump_search_input"),
                    singleLine = true,
                    shape = RoundedCornerShape(12.dp)
                )

                // Popular Passages Shortcuts
                Text("Popular Passages Shortcuts", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(rememberScrollState()),
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    val shortcuts = listOf("John 3:16", "Psalm 23:1", "Romans 8:28", "Genesis 1:1", "Proverbs 3:5", "Philippians 4:13", "Revelation 21:4")
                    shortcuts.forEach { shortcut ->
                        AssistChip(
                            onClick = {
                                val parts = shortcut.split(" ")
                                val bk = if (parts.size == 3) "${parts[0]} ${parts[1]}" else parts[0]
                                val chVs = parts.last().split(":")
                                val ch = chVs[0].toIntOrNull() ?: 1
                                val vs = if (chVs.size > 1) chVs[1].toIntOrNull() ?: 1 else 1

                                viewModel.selectTestament(if (bookNameInOldTestament(bk)) "Old Testament" else "New Testament")
                                viewModel.selectBook(bk)
                                viewModel.selectChapter(ch)
                                viewModel.selectVerse(vs)
                                viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                                Toast.makeText(context, "Jumped to $shortcut", Toast.LENGTH_SHORT).show()
                                onDismiss()
                            },
                            label = { Text(shortcut, fontSize = 11.sp, fontWeight = FontWeight.Bold) },
                            leadingIcon = { Icon(Icons.Default.FastForward, contentDescription = null, modifier = Modifier.size(12.dp), tint = MaterialTheme.colorScheme.primary) }
                        )
                    }
                }

                HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.35f))

                // Select Book Grid
                Text("Select Book: $selectedBook", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                androidx.compose.foundation.layout.FlowRow(
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                    verticalArrangement = Arrangement.spacedBy(6.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 130.dp)
                        .verticalScroll(rememberScrollState())
                ) {
                    filteredBooks.forEach { bk ->
                        val isSel = bk.equals(selectedBook, ignoreCase = true)
                        FilterChip(
                            selected = isSel,
                            onClick = {
                                selectedBook = bk
                                selectedChapter = 1
                            },
                            label = { Text(bk, fontSize = 11.sp) }
                        )
                    }
                }

                // Select Chapter Number
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text("Select Chapter: $selectedChapter", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                        IconButton(
                            onClick = { if (selectedChapter > 1) selectedChapter-- },
                            modifier = Modifier.size(28.dp)
                        ) {
                            Icon(Icons.Default.Remove, contentDescription = "Decrease Chapter", modifier = Modifier.size(16.dp))
                        }
                        Text("$selectedChapter", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                        IconButton(
                            onClick = { selectedChapter++ },
                            modifier = Modifier.size(28.dp)
                        ) {
                            Icon(Icons.Default.Add, contentDescription = "Increase Chapter", modifier = Modifier.size(16.dp))
                        }
                    }
                }

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(rememberScrollState()),
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    (1..30).forEach { ch ->
                        SuggestionChip(
                            onClick = { selectedChapter = ch },
                            label = { Text("Ch $ch", fontSize = 10.sp) },
                            colors = SuggestionChipDefaults.suggestionChipColors(
                                containerColor = if (selectedChapter == ch) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceVariant
                            )
                        )
                    }
                }

                // Primary Jump Button
                Button(
                    onClick = {
                        val testament = if (bookNameInOldTestament(selectedBook)) "Old Testament" else "New Testament"
                        viewModel.selectTestament(testament)
                        viewModel.selectBook(selectedBook)
                        viewModel.selectChapter(selectedChapter)
                        viewModel.selectVerse(1)
                        viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                        Toast.makeText(context, "Jumped to $selectedBook $selectedChapter!", Toast.LENGTH_SHORT).show()
                        onDismiss()
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(48.dp)
                        .testTag("quick_jump_go_btn"),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Icon(Icons.Default.Bolt, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Go to $selectedBook $selectedChapter", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                }
            }
        }
    }
}

    if (showQuickJumpDialog) {
        QuickJumpDialog(viewModel = viewModel, onDismiss = { showQuickJumpDialog = false })
    }

    // -----------------------------------------------------------------
    // FULL VIEW READING MODE OVERLAY
    // -----------------------------------------------------------------
    if (isFullViewActive) {
        Dialog(
            onDismissRequest = { isFullViewActive = false },
            properties = androidx.compose.ui.window.DialogProperties(
                usePlatformDefaultWidth = false,
                dismissOnBackPress = true,
                dismissOnClickOutside = false
            )
        ) {
            val themePref by viewModel.themePreference.collectAsStateWithLifecycle()
            val fullViewListState = rememberLazyListState()
            var selectedFullViewVerse by remember { mutableStateOf<BibleVerse?>(null) }
            
            // Auto scroll full view list if currentlyReadingVerseNumber changes during active TTS reading
            LaunchedEffect(currentlyReadingVerseNumber) {
                currentlyReadingVerseNumber?.let { verseNum ->
                    val index = verses.indexOfFirst { it.verseNumber == verseNum }
                    if (index >= 0) {
                        fullViewListState.animateScrollToItem(index, scrollOffset = -250)
                    }
                }
            }

            Surface(
                modifier = Modifier.fillMaxSize(),
                color = MaterialTheme.colorScheme.background
            ) {
                Box(modifier = Modifier.fillMaxSize()) {
                    Column(modifier = Modifier.fillMaxSize()) {
                        // 1. TOP HEADER BAR
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 16.dp, vertical = 12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            IconButton(
                                onClick = { isFullViewActive = false },
                                modifier = Modifier.testTag("full_view_close_btn")
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Close,
                                    contentDescription = "Close Full View Mode",
                                    tint = MaterialTheme.colorScheme.onBackground
                                )
                            }
                            
                            // Title
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text(
                                    text = "$selectedBook $selectedChapter",
                                    style = MaterialTheme.typography.titleLarge,
                                    fontWeight = FontWeight.Bold,
                                    fontFamily = selectedFontFamily,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Text(
                                    text = "Version: $selectedTranslation",
                                    style = MaterialTheme.typography.labelSmall,
                                    color = MaterialTheme.colorScheme.secondary
                                )
                            }

                            // Theme Toggle
                            IconButton(
                                onClick = { 
                                    viewModel.setThemePreference(if (themePref == "Dark") "Light" else "Dark")
                                },
                                modifier = Modifier.testTag("full_view_theme_toggle")
                            ) {
                                Icon(
                                    imageVector = if (themePref == "Dark") Icons.Default.LightMode else Icons.Default.DarkMode,
                                    contentDescription = "Toggle Theme",
                                    tint = MaterialTheme.colorScheme.onBackground
                                )
                            }
                        }

                        HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))

                        // 1.5. COMPARE VERSION BAR (Optionally active in full view mode)
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.15f))
                                .padding(vertical = 4.dp, horizontal = 16.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(
                                    imageVector = Icons.Default.Compare,
                                    contentDescription = "Compare",
                                    modifier = Modifier.size(16.dp),
                                    tint = MaterialTheme.colorScheme.primary
                                )
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(
                                    text = translateUi("Compare Versions", appLanguageState),
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = MaterialTheme.colorScheme.primary
                                )
                            }
                            
                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                if (isCompareMode) {
                                    var showCompareDropdown by remember { mutableStateOf(false) }
                                    Box {
                                        AssistChip(
                                            onClick = { showCompareDropdown = true },
                                            label = { Text("With: $compareTranslation", fontSize = 10.sp) },
                                            modifier = Modifier.height(26.dp)
                                        )
                                        DropdownMenu(
                                            expanded = showCompareDropdown,
                                            onDismissRequest = { showCompareDropdown = false }
                                        ) {
                                            availableTranslationsList.forEach { trans ->
                                                DropdownMenuItem(
                                                    text = {
                                                        Row(
                                                            modifier = Modifier.fillMaxWidth(),
                                                            horizontalArrangement = Arrangement.SpaceBetween,
                                                            verticalAlignment = Alignment.CenterVertically
                                                        ) {
                                                            Text(trans, modifier = Modifier.weight(1f))
                                                            IconButton(
                                                                onClick = {
                                                                    showCompareDropdown = false
                                                                    selectedTranslationForDetails = trans
                                                                },
                                                                modifier = Modifier.size(24.dp)
                                                            ) {
                                                                Icon(
                                                                    imageVector = Icons.Default.Info,
                                                                    contentDescription = "Version Info",
                                                                    tint = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f),
                                                                    modifier = Modifier.size(16.dp)
                                                                )
                                                            }
                                                        }
                                                    },
                                                    onClick = {
                                                        viewModel.setCompareTranslation(trans)
                                                        showCompareDropdown = false
                                                    }
                                                )
                                            }
                                        }
                                    }

                                    FilterChip(
                                        selected = compareSideBySide,
                                        onClick = { viewModel.setCompareSideBySide(!compareSideBySide) },
                                        label = {
                                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                                Icon(
                                                    imageVector = if (compareSideBySide) Icons.Default.ViewColumn else Icons.Default.TableRows,
                                                    contentDescription = null,
                                                    modifier = Modifier.size(12.dp)
                                                )
                                                Text(if (compareSideBySide) "Side-by-Side" else "Stacked", fontSize = 10.sp)
                                            }
                                        },
                                        modifier = Modifier
                                            .height(28.dp)
                                            .redGlowBorder(enabled = compareSideBySide, shape = RoundedCornerShape(8.dp))
                                            .testTag("full_view_compare_side_by_side_toggle_btn")
                                    )
                                }
                                Switch(
                                    checked = isCompareMode,
                                    onCheckedChange = { viewModel.setCompareMode(it) },
                                    modifier = Modifier.testTag("full_view_compare_switch")
                                )
                            }
                        }
                        
                        HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))

                        // 2. MAIN BIBLE SCRIPTURE TEXT LIST
                        AnimatedContent(
                            targetState = listOf(selectedBook, selectedChapter, selectedTranslation, isCompareMode, compareTranslation, compareSideBySide),
                            transitionSpec = {
                                (fadeIn(animationSpec = tween(350)) + scaleIn(initialScale = 0.96f, animationSpec = tween(350)))
                                    .togetherWith(fadeOut(animationSpec = tween(200)))
                            },
                            label = "FullViewChapterTransition",
                            modifier = Modifier.fillMaxSize().weight(1f)
                        ) { _ ->
                            if (verses.isEmpty()) {
                                Box(
                                    modifier = Modifier.fillMaxSize(),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text("No bible verses loaded.", style = MaterialTheme.typography.bodyLarge)
                                }
                            } else {
                                LazyColumn(
                                    state = fullViewListState,
                                    modifier = Modifier
                                        .fillMaxSize()
                                        .background(if (readerTheme != "Light") readerThemeBgColor else MaterialTheme.colorScheme.background)
                                        .padding(horizontal = 24.dp, vertical = 16.dp),
                                    verticalArrangement = Arrangement.spacedBy(18.dp),
                                    contentPadding = PaddingValues(bottom = 80.dp)
                                ) {
                                    items(verses.size) { index ->
                                        val verse = verses[index]
                                        val isHighlighted = currentlyReadingVerseNumber == verse.verseNumber
                                        val isBookmarked = bookmarks.any {
                                            it.translation == verse.translation &&
                                            it.bookName == verse.bookName &&
                                            it.chapter == verse.chapter &&
                                            it.verseNumber == verse.verseNumber
                                        }
                                        val matchingFavorite = favorites.firstOrNull {
                                            it.translation == verse.translation &&
                                            it.bookName == verse.bookName &&
                                            it.chapter == verse.chapter &&
                                            it.verseNumber == verse.verseNumber
                                        }
                                        
                                        Surface(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .redGlowBorder(enabled = isHighlighted, shape = RoundedCornerShape(12.dp), glowColor = Color(0xFF00E676))
                                                .clickable { selectedFullViewVerse = verse },
                                            shape = RoundedCornerShape(12.dp),
                                            color = when {
                                                isHighlighted -> MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.35f)
                                                isBookmarked -> MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.15f)
                                                readerTheme == "Sepia" -> Color(0xFFF3E5C8)
                                                readerTheme == "Dark" -> Color(0xFF1E202E)
                                                else -> Color.Transparent
                                            },
                                            border = when {
                                                isHighlighted -> BorderStroke(2.dp, Color(0xFF00E676))
                                                isBookmarked -> BorderStroke(1.dp, MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.3f))
                                                readerTheme == "Sepia" -> BorderStroke(1.dp, Color(0xFFE5D5B5))
                                                readerTheme == "Dark" -> BorderStroke(1.dp, Color(0xFF2A2D3E))
                                                else -> null
                                            }
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(12.dp),
                                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                                            ) {
                                                // Superscript/Badge for Verse Number
                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    Text(
                                                        text = verse.verseNumber.toString(),
                                                        style = MaterialTheme.typography.bodyMedium.copy(
                                                            fontWeight = FontWeight.Bold,
                                                            color = if (readerTheme != "Light") readerThemeVerseNumColor else MaterialTheme.colorScheme.primary
                                                        )
                                                    )
                                                    if (isHighlighted) {
                                                        Spacer(modifier = Modifier.width(4.dp))
                                                        Surface(
                                                            shape = RoundedCornerShape(10.dp),
                                                            color = MaterialTheme.colorScheme.primary,
                                                            border = BorderStroke(1.dp, Color(0xFF00E676))
                                                        ) {
                                                            Row(
                                                                modifier = Modifier.padding(horizontal = 5.dp, vertical = 2.dp),
                                                                verticalAlignment = Alignment.CenterVertically
                                                            ) {
                                                                Icon(Icons.Default.VolumeUp, contentDescription = "Reading", tint = MaterialTheme.colorScheme.onPrimary, modifier = Modifier.size(10.dp))
                                                                Spacer(modifier = Modifier.width(2.dp))
                                                                Text("READING", fontSize = 8.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onPrimary)
                                                            }
                                                        }
                                                    }
                                                    if (matchingFavorite != null) {
                                                        Spacer(modifier = Modifier.width(3.dp))
                                                        Icon(
                                                            imageVector = Icons.Default.Favorite,
                                                            contentDescription = "Favorited",
                                                            tint = Color(0xFFFF1744),
                                                            modifier = Modifier.size(13.dp)
                                                        )
                                                    }
                                                }
                                                
                                                // Verse content column
                                                Column(modifier = Modifier.weight(1f)) {
                                                    if (isCompareMode) {
                                                        val compVerse = comparedVerses.find { it.verseNumber == verse.verseNumber }

                                                        if (compareSideBySide) {
                                                            Row(
                                                                modifier = Modifier.fillMaxWidth(),
                                                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                            ) {
                                                                // Column 1: Primary Translation
                                                                Column(
                                                                    modifier = Modifier
                                                                        .weight(1f)
                                                                        .background(
                                                                            color = (if (readerTheme != "Light") readerThemeBgColor else MaterialTheme.colorScheme.surfaceVariant).copy(alpha = 0.35f),
                                                                            shape = RoundedCornerShape(8.dp)
                                                                        )
                                                                        .border(
                                                                            width = 1.dp,
                                                                            color = (if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.onSurface).copy(alpha = 0.12f),
                                                                            shape = RoundedCornerShape(8.dp)
                                                                        )
                                                                        .padding(8.dp)
                                                                ) {
                                                                    Text(
                                                                        text = selectedTranslation,
                                                                        style = MaterialTheme.typography.labelSmall,
                                                                        fontWeight = FontWeight.Bold,
                                                                        color = if (readerTheme != "Light") readerThemeVerseNumColor else MaterialTheme.colorScheme.primary,
                                                                        modifier = Modifier.padding(bottom = 4.dp)
                                                                    )
                                                                    Text(
                                                                        text = verse.text,
                                                                        style = MaterialTheme.typography.bodyLarge.copy(
                                                                            fontSize = (readerFontSize + 1f).sp,
                                                                            fontFamily = selectedFontFamily,
                                                                            lineHeight = fullViewLineHeightSp,
                                                                            letterSpacing = dyslexicLetterSpacing,
                                                                            fontWeight = dyslexicFontWeight
                                                                        ),
                                                                        color = if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground
                                                                    )
                                                                }

                                                                // Column 2: Secondary Translation
                                                                Column(
                                                                    modifier = Modifier
                                                                        .weight(1f)
                                                                        .background(
                                                                            color = (if (readerTheme != "Light") readerThemeBgColor else MaterialTheme.colorScheme.surfaceVariant).copy(alpha = 0.35f),
                                                                            shape = RoundedCornerShape(8.dp)
                                                                        )
                                                                        .border(
                                                                            width = 1.dp,
                                                                            color = (if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.onSurface).copy(alpha = 0.12f),
                                                                            shape = RoundedCornerShape(8.dp)
                                                                        )
                                                                        .padding(8.dp)
                                                                ) {
                                                                    Text(
                                                                        text = compareTranslation,
                                                                        style = MaterialTheme.typography.labelSmall,
                                                                        fontWeight = FontWeight.Bold,
                                                                        color = if (readerTheme != "Light") readerThemeVerseNumColor else MaterialTheme.colorScheme.secondary,
                                                                        modifier = Modifier.padding(bottom = 4.dp)
                                                                    )
                                                                    if (compVerse != null) {
                                                                        Text(
                                                                            text = compVerse.text,
                                                                            style = MaterialTheme.typography.bodyLarge.copy(
                                                                                fontSize = (readerFontSize + 1f).sp,
                                                                                fontFamily = selectedFontFamily,
                                                                                lineHeight = fullViewLineHeightSp,
                                                                                letterSpacing = dyslexicLetterSpacing,
                                                                                fontWeight = dyslexicFontWeight
                                                                            ),
                                                                            color = (if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground).copy(alpha = 0.9f)
                                                                        )
                                                                    } else {
                                                                        Text(
                                                                            text = "[$compareTranslation: tap to download in settings]",
                                                                            fontSize = 11.sp,
                                                                            color = MaterialTheme.colorScheme.error,
                                                                            fontStyle = FontStyle.Italic
                                                                        )
                                                                    }
                                                                }
                                                            }
                                                        } else {
                                                            // Stacked layout
                                                            Text(
                                                                text = "$selectedTranslation: ${verse.text}",
                                                                style = MaterialTheme.typography.bodyLarge.copy(
                                                                    fontSize = (readerFontSize + 1f).sp,
                                                                    fontFamily = selectedFontFamily,
                                                                    lineHeight = fullViewLineHeightSp,
                                                                    letterSpacing = dyslexicLetterSpacing,
                                                                    fontWeight = dyslexicFontWeight
                                                                ),
                                                                color = if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground
                                                            )
                                                            if (compVerse != null) {
                                                                Spacer(modifier = Modifier.height(8.dp))
                                                                HorizontalDivider(color = (if (readerTheme != "Light") readerThemeSubtextColor else MaterialTheme.colorScheme.onSurface).copy(alpha = 0.12f))
                                                                Spacer(modifier = Modifier.height(8.dp))
                                                                Text(
                                                                    text = "$compareTranslation: ${compVerse.text}",
                                                                    style = MaterialTheme.typography.bodyLarge.copy(
                                                                        fontSize = (readerFontSize + 1f).sp,
                                                                        fontFamily = selectedFontFamily,
                                                                        lineHeight = fullViewLineHeightSp,
                                                                        letterSpacing = dyslexicLetterSpacing,
                                                                        fontWeight = dyslexicFontWeight
                                                                    ),
                                                                    color = (if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground).copy(alpha = 0.85f),
                                                                    fontStyle = FontStyle.Italic
                                                                )
                                                            } else {
                                                                Spacer(modifier = Modifier.height(4.dp))
                                                                Text(
                                                                    text = "[$compareTranslation: tap to download in settings]",
                                                                    fontSize = 12.sp,
                                                                    color = MaterialTheme.colorScheme.error,
                                                                    fontStyle = FontStyle.Italic
                                                                )
                                                            }
                                                        }
                                                    } else {
                                                        Text(
                                                            text = verse.text,
                                                            style = MaterialTheme.typography.bodyLarge.copy(
                                                                fontSize = (readerFontSize + 1f).sp,
                                                                fontFamily = selectedFontFamily,
                                                                lineHeight = fullViewLineHeightSp,
                                                                letterSpacing = dyslexicLetterSpacing,
                                                                fontWeight = dyslexicFontWeight
                                                            ),
                                                            color = if (readerTheme != "Light") readerThemeTextColor else MaterialTheme.colorScheme.onBackground
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    // 3. ERGONOMIC FLOATING CHEVRON CHAPTER NAVIGATION (Favourable Navigation)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .align(Alignment.BottomCenter)
                            .padding(bottom = 16.dp, start = 24.dp, end = 24.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // Previous Chapter
                        FloatingActionButton(
                            onClick = { viewModel.selectPreviousChapter() },
                            containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.85f),
                            contentColor = MaterialTheme.colorScheme.onPrimaryContainer,
                            shape = CircleShape,
                            modifier = Modifier.testTag("full_view_prev_btn")
                        ) {
                            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Previous Chapter")
                        }

                        // Quick Jump Floating Action Button
                        ExtendedFloatingActionButton(
                            onClick = { showQuickJumpDialog = true },
                            icon = { Icon(Icons.Default.Bolt, contentDescription = "Quick Jump", tint = MaterialTheme.colorScheme.onPrimary) },
                            text = { Text("Quick Jump", fontWeight = FontWeight.Bold, fontSize = 12.sp, color = MaterialTheme.colorScheme.onPrimary) },
                            containerColor = MaterialTheme.colorScheme.primary,
                            contentColor = MaterialTheme.colorScheme.onPrimary,
                            shape = CircleShape,
                            modifier = Modifier.testTag("full_view_quick_jump_btn")
                        )

                        // Floating Active Reading Indicator & Play/Pause bar
                        val isCurrentlyReadingThis = currentReadingTitle == "$selectedBook $selectedChapter"
                        if (isCurrentlyReadingThis) {
                            Surface(
                                shape = RoundedCornerShape(24.dp),
                                color = MaterialTheme.colorScheme.tertiaryContainer.copy(alpha = 0.95f),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.tertiary.copy(alpha = 0.3f))
                            ) {
                                Row(
                                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    IconButton(
                                        onClick = {
                                            if (isReadingPaused) resumeSpeaking() else pauseSpeaking()
                                        },
                                        modifier = Modifier.size(28.dp).testTag("full_view_play_pause_btn")
                                    ) {
                                        Icon(
                                            imageVector = if (isReadingPaused) Icons.Default.PlayArrow else Icons.Default.Pause,
                                            contentDescription = if (isReadingPaused) "Resume" else "Pause",
                                            tint = MaterialTheme.colorScheme.onTertiaryContainer,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                    Text(
                                        text = if (isReadingPaused) "Paused" else "Reading...",
                                        style = MaterialTheme.typography.labelMedium,
                                        color = MaterialTheme.colorScheme.onTertiaryContainer
                                    )
                                    IconButton(
                                        onClick = { stopSpeaking() },
                                        modifier = Modifier.size(24.dp).testTag("full_view_stop_btn")
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Stop,
                                            contentDescription = "Stop",
                                            tint = LivelyRed,
                                            modifier = Modifier.size(14.dp)
                                        )
                                    }
                                }
                            }
                        } else {
                            FloatingActionButton(
                                onClick = { speakBibleChapter(verses, selectedBook, selectedChapter) },
                                containerColor = MaterialTheme.colorScheme.tertiaryContainer.copy(alpha = 0.85f),
                                contentColor = MaterialTheme.colorScheme.onTertiaryContainer,
                                shape = CircleShape,
                                modifier = Modifier.testTag("full_view_play_btn")
                            ) {
                                Icon(Icons.Default.VolumeUp, contentDescription = "Read Aloud")
                            }
                        }

                        // Next Chapter
                        FloatingActionButton(
                            onClick = { viewModel.selectNextChapter() },
                            containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.85f),
                            contentColor = MaterialTheme.colorScheme.onPrimaryContainer,
                            shape = CircleShape,
                            modifier = Modifier.testTag("full_view_next_btn")
                        ) {
                            Icon(Icons.AutoMirrored.Filled.ArrowForward, contentDescription = "Next Chapter")
                        }
                    }
                }
            }

            // 4. VERSE ACTIONS & COMPARATIVE TRANSLATIONS POPUP (Tapping on a verse)
            selectedFullViewVerse?.let { verse ->
                val comparedList by viewModel.getVerseAcrossTranslations(verse.bookName, verse.chapter, verse.verseNumber).collectAsState(initial = emptyList())
                val isFavorited = favorites.any {
                    it.translation == verse.translation &&
                    it.bookName == verse.bookName &&
                    it.chapter == verse.chapter &&
                    it.verseNumber == verse.verseNumber
                }
                val isBookmarked = bookmarks.any {
                    it.translation == verse.translation &&
                    it.bookName == verse.bookName &&
                    it.chapter == verse.chapter &&
                    it.verseNumber == verse.verseNumber
                }
                val matchingFavorite = favorites.firstOrNull {
                    it.translation == verse.translation &&
                    it.bookName == verse.bookName &&
                    it.chapter == verse.chapter &&
                    it.verseNumber == verse.verseNumber
                }

                Dialog(onDismissRequest = { selectedFullViewVerse = null }) {
                    Card(
                        shape = RoundedCornerShape(16.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                        modifier = Modifier
                            .fillMaxWidth()
                            .fillMaxHeight(0.8f)
                            .padding(8.dp)
                            .testTag("full_view_verse_dialog")
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(16.dp)
                        ) {
                            // Header
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "${verse.bookName} ${verse.chapter}:${verse.verseNumber}",
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.titleMedium,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                IconButton(onClick = { selectedFullViewVerse = null }) {
                                    Icon(Icons.Default.Close, contentDescription = "Close")
                                }
                            }

                            Spacer(modifier = Modifier.height(12.dp))

                            // Verse text quote
                            Card(
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)),
                                shape = RoundedCornerShape(8.dp),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Text(
                                    text = "\"${verse.text}\"",
                                    fontStyle = FontStyle.Italic,
                                    fontSize = 14.sp,
                                    lineHeight = 20.sp,
                                    modifier = Modifier.padding(12.dp)
                                )
                            }

                            Spacer(modifier = Modifier.height(16.dp))

                            // Interactive Verse Action Controls
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                // Favorite Button
                                val isFavorite = matchingFavorite != null
                                Button(
                                    onClick = {
                                        if (isFavorite) {
                                            viewModel.removeFavorite(verse)
                                            Toast.makeText(context, "Removed from Favorites", Toast.LENGTH_SHORT).show()
                                        } else {
                                            viewModel.highlightVerse(verse, "#FFD54F")
                                            Toast.makeText(context, "Added to Favorites!", Toast.LENGTH_SHORT).show()
                                        }
                                    },
                                    modifier = Modifier.weight(1f).testTag("full_view_dialog_favorite_btn"),
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = if (isFavorite) Color(0xFFFF1744) else MaterialTheme.colorScheme.surfaceVariant,
                                        contentColor = if (isFavorite) Color.White else MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                ) {
                                    Icon(
                                        imageVector = if (isFavorite) Icons.Default.Favorite else Icons.Default.FavoriteBorder,
                                        contentDescription = null,
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(if (isFavorite) "Favorited" else "Favorite", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }

                                // Bookmark Button
                                Button(
                                    onClick = {
                                        viewModel.toggleBookmark(verse)
                                        if (isBookmarked) {
                                            Toast.makeText(context, "Bookmark removed", Toast.LENGTH_SHORT).show()
                                        } else {
                                            Toast.makeText(context, "Added to Bookmarks", Toast.LENGTH_SHORT).show()
                                        }
                                    },
                                    modifier = Modifier.weight(1f).testTag("full_view_dialog_bookmark_btn"),
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = if (isBookmarked) MaterialTheme.colorScheme.secondaryContainer else MaterialTheme.colorScheme.primary,
                                        contentColor = if (isBookmarked) MaterialTheme.colorScheme.onSecondaryContainer else MaterialTheme.colorScheme.onPrimary
                                    )
                                ) {
                                    Icon(
                                        imageVector = if (isBookmarked) Icons.Default.Bookmark else Icons.Default.BookmarkBorder,
                                        contentDescription = null,
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(if (isBookmarked) "Bookmarked" else "Bookmark", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }

                                // Speak Aloud this verse
                                OutlinedButton(
                                    onClick = {
                                        speakText("${verse.bookName} chapter ${verse.chapter} verse ${verse.verseNumber}", verse.text)
                                    },
                                    modifier = Modifier.weight(1f).testTag("full_view_dialog_read_btn")
                                ) {
                                    Icon(Icons.Default.VolumeUp, contentDescription = null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Read Aloud", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                            }

                            Spacer(modifier = Modifier.height(16.dp))

                            // Favorite Highlights Selector (Independent of Bookmark)
                            Row(
                                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                val haptic = LocalHapticFeedback.current
                                Text("Highlight:", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface)
                                Spacer(modifier = Modifier.width(2.dp))
                                val highlightColorsList = listOf(
                                    "#FFD54F" to Color(0xFFFFD54F), // Yellow
                                    "#A5D6A7" to Color(0xFFA5D6A7), // Green
                                    "#90CAF9" to Color(0x9090CAF9), // Blue
                                    "#F48FB1" to Color(0x90F48FB1)  // Pink
                                )
                                highlightColorsList.forEach { (hex, composeColor) ->
                                    val isSelectedHex = matchingFavorite?.colorHex?.equals(hex, ignoreCase = true) == true
                                    Box(
                                        modifier = Modifier
                                            .size(28.dp)
                                            .clip(CircleShape)
                                            .background(composeColor)
                                            .border(
                                                width = if (isSelectedHex) 2.dp else 0.dp,
                                                color = if (isSelectedHex) MaterialTheme.colorScheme.primary else Color.Transparent,
                                                shape = CircleShape
                                            )
                                            .clickable {
                                                haptic.performHapticFeedback(HapticFeedbackType.LongPress)
                                                viewModel.highlightVerse(verse, hex)
                                                Toast.makeText(context, "Favorite Highlight Applied!", Toast.LENGTH_SHORT).show()
                                            }
                                    )
                                }
                                if (isFavorited) {
                                    Spacer(modifier = Modifier.weight(1f))
                                    IconButton(
                                        onClick = {
                                            matchingFavorite?.let {
                                                viewModel.removeFavoriteHighlight(it)
                                                Toast.makeText(context, "Favorite Highlight removed", Toast.LENGTH_SHORT).show()
                                            }
                                        },
                                        modifier = Modifier.size(28.dp)
                                    ) {
                                        Icon(
                                            Icons.Default.Delete,
                                            contentDescription = "Remove Favorite Highlight",
                                            tint = MaterialTheme.colorScheme.error,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(16.dp))
                            HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))
                            Spacer(modifier = Modifier.height(12.dp))

                            // MULTI-TRANSLATION COMPARISON LIST
                            Text(
                                text = "Compare Versions (Offline)",
                                fontWeight = FontWeight.Bold,
                                style = MaterialTheme.typography.labelLarge,
                                color = MaterialTheme.colorScheme.secondary
                            )
                            Spacer(modifier = Modifier.height(8.dp))

                            val otherTranslations = comparedList.filter { it.translation != verse.translation }
                            if (otherTranslations.isEmpty()) {
                                Box(
                                    modifier = Modifier.fillMaxWidth().weight(1f),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = "No other downloaded translations found to compare. Manage downloaded versions in settings.",
                                        style = MaterialTheme.typography.bodySmall,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                        textAlign = TextAlign.Center
                                    )
                                }
                            } else {
                                LazyColumn(
                                    modifier = Modifier.fillMaxWidth().weight(1f),
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    items(otherTranslations.size) { oIndex ->
                                        val otherVerse = otherTranslations[oIndex]
                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f)),
                                            shape = RoundedCornerShape(8.dp)
                                        ) {
                                            Column(modifier = Modifier.padding(10.dp)) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween
                                                ) {
                                                    Text(
                                                        text = otherVerse.translation,
                                                        fontWeight = FontWeight.Bold,
                                                        style = MaterialTheme.typography.labelMedium,
                                                        color = MaterialTheme.colorScheme.primary
                                                    )
                                                }
                                                Spacer(modifier = Modifier.height(4.dp))
                                                Text(
                                                    text = otherVerse.text,
                                                    style = MaterialTheme.typography.bodyMedium,
                                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    selectedTranslationForDetails?.let { transCode ->
        val meta = lookupTranslationMetadata(transCode)
        TranslationDetailsDialog(
            metadata = meta,
            onDismiss = { selectedTranslationForDetails = null },
            onSelect = { viewModel.selectTranslation(transCode) }
        )
    }
}

fun bookNameInOldTestament(book: String): Boolean {
    val oldTestamentBooksList = listOf(
        "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy",
        "Joshua", "Judges", "Ruth", "1 Samuel", "2 Samuel",
        "1 Kings", "2 Kings", "1 Chronicles", "2 Chronicles", "Ezra",
        "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes",
        "Song of Solomon", "Isaiah", "Jeremiah", "Lamentations", "Ezekiel",
        "Daniel", "Hosea", "Joel", "Amos", "Obadiah", "Jonah",
        "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah",
        "Malachi"
    )
    return oldTestamentBooksList.contains(book)
}

fun lookupTranslationMetadata(code: String): TranslationMetadata {
    val englishTranslations = listOf(
        TranslationMetadata("GNT", "Good News Version (GNT)", 1800000L, "English", "Clear, easy to read and understand translation featuring everyday contemporary English vocabulary and natural sentence structure. Published by the American Bible Society, it is designed to be accessible to readers of all ages, non-native English speakers, and new believers."),
        TranslationMetadata("KJV", "King James Version", 1800000L, "English", "Classic majestic 1611 authorized text commissioned by King James I of England. Celebrated for its legendary poetic cadence, dignified early modern English phrasing, and monumental impact on English literature and Christian tradition for over 400 years."),
        TranslationMetadata("NKJV", "New King James Version", 2100000L, "English", "Modernized 1982 revision that preserves the timeless poetic grandeur, reverence, and manuscript tradition of the original 1611 KJV, while updating archaic vocabulary, grammar, and sentence structure for modern readability."),
        TranslationMetadata("NIV", "New International Version", 2200000L, "English", "Balanced dynamic-equivalence translation crafted by over 100 international scholars from original Hebrew, Aramaic, and Greek texts. Striking an optimal balance between word-for-word accuracy and smooth, contemporary reading flow."),
        TranslationMetadata("ESV", "English Standard Version", 2000000L, "English", "An essentially literal word-for-word translation published in 2001 that captures precise word choices, literary structure, and grammatical nuances of original biblical languages while maintaining clear literary elegance."),
        TranslationMetadata("NLT", "New Living Translation", 2000000L, "English", "Thought-for-thought translation in vibrant modern English, combining high academic scholarship with warm, clear expression. Ideal for personal devotions, group study, and expressive scripture reading."),
        TranslationMetadata("CSV", "Christian Standard Version", 1800000L, "English", "Optimal equivalence translation striking a precise balance between literal precision and natural readability. Designed for deep study and daily devotional engagement with consistent clarity."),
        TranslationMetadata("GNB", "Good News Bible", 1800000L, "English", "Accessible dynamic-equivalence Bible in contemporary English, designed for clear understanding and smooth reading across diverse cultures and reading backgrounds."),
        TranslationMetadata("ICB", "International Children's Bible", 1900000L, "English", "Translation specifically crafted at a 3rd-grade reading level using simple vocabulary and short, clear sentences. Perfect for young readers, family devotions, and English language learners."),
        TranslationMetadata("MSG", "The Message", 1700000L, "English", "Vibrant contemporary paraphrase by scholar Eugene Peterson that renders ancient Hebrew and Greek idioms into fresh, modern expressive language, shedding new light on familiar scripture passages."),
        TranslationMetadata("AMP", "Amplified Bible", 2500000L, "English", "Unique study version that uses inline parenthetical synonyms, expanded definitions, and explanatory notes to unpack subtle nuances and hidden depths of Hebrew, Aramaic, and Greek terms."),
        TranslationMetadata("WEB", "World English Bible", 2100000L, "English", "Modern, highly accurate, public-domain English translation based on the 1901 American Standard Version and Greek Majority Text, updated with contemporary grammar and spelling."),
        TranslationMetadata("ASV", "American Standard Version", 1900000L, "English", "Highly literal 1901 scholarly translation prized for its painstaking word-for-word accuracy, precise rendering of original idioms, and enduring consistency across biblical books.")
    )
    val spanishTranslations = listOf(
        TranslationMetadata("RVR1960", "Reina-Valera 1960", 2400000L, "Spanish", "La traducción clásica de referencia en el mundo hispanohablante. Valorada por su belleza literaria, reverencia y fidelidad a los textos originales de la Reforma."),
        TranslationMetadata("NVI", "Nueva Versión Internacional", 2200000L, "Spanish", "Traducción moderna y dinámica en español realizada directamente de los manuscritos hebreos, arameos y griegos. Ofrece una lectura fluida, clara y comprensible."),
        TranslationMetadata("LBLA", "La Biblia de las Américas (LBLA)", 2400000L, "Spanish", "Traducción rigurosamente literal y exacta que preserva la estructura y matices del hebreo y griego original, ideal para el estudio profundo de las Escrituras."),
        TranslationMetadata("JBS", "La Biblia del Jubileo 2000 (JBS)", 2100000L, "Spanish", "Traducción fiel basada en la célebre Biblia del Oso (1569) y de la Biblia del Cántaro (1602), adaptada al español contemporáneo sin perder la fuerza del texto clásico."),
        TranslationMetadata("NTV", "Nueva Traducción Viviente (NTV)", 2200000L, "Spanish", "Traducción clara, contemporánea y directa por pensamiento, diseñada para conmover el corazón e iluminar la mente con un lenguaje moderno y dinámico."),
        TranslationMetadata("RVR", "La Biblia Reina-Valera (RVR)", 2400000L, "Spanish", "La histórica y majestuosa traducción de Casiodoro de Reina revisada por Cipriano de Valera, patrimonio espiritual esencial del pueblo hispano."),
        TranslationMetadata("SEV", "Sagradas Escrituras (1569) (SEV)", 2300000L, "Spanish", "Traducción histórica seminal castellana que representa una de las primeras versiones completas traducidas de los idiomas originales al español."),
        TranslationMetadata("AA", "Almeida Atualizada", 2200000L, "Portuguese", "A clássica e respeitada tradução de João Ferreira de Almeida, atualizada com ortografia e fluidez moderna mantendo a reverência tradicional em português."),
        TranslationMetadata("NVI-PT", "Nova Versão Internacional - PT", 2100000L, "Portuguese", "Tradução contemporânea em português que une rigor acadêmico e linguagem natural para leitura diária e estudo bíblico.")
    )
    val globalTranslations = listOf(
        TranslationMetadata("LSG", "Louis Segond 1910", 2300000L, "French", "La version classique de référence protestante en français, réputée pour sa précision théologique et son élégance littéraire."),
        TranslationMetadata("OST", "Ostervald", 2200000L, "French", "Version traditionnelle française révisée par le théologien Jean-Frédéric Ostervald, appréciée pour sa clarté et sa fidélité pastorale."),
        TranslationMetadata("ELB", "Elberfelder 1905", 2500000L, "German", "Sehr wortgetreue und präzise deutsche Bibelübersetzung, geschätzt für ihre enge Anlehnung an die Grundtexte in Hebräisch und Griechisch."),
        TranslationMetadata("LUT", "Luther Bible 1912", 2400000L, "German", "Die historische und sprachgewaltige Übersetzung von Martin Luther, die die deutsche Sprache nachhaltig geprägt hat."),
        TranslationMetadata("GDB", "Giovanni Diodati 1649", 2300000L, "Italian", "La classica ed elegante traduzione protestante in lingua italiana, un capolavoro di fedeltà e bellezza letteraria."),
        TranslationMetadata("RIV", "Riveduta 1927", 2200000L, "Italian", "Accurata revisione del testo di Diodati curata da Giovanni Luzzi per offrire maggiore chiarezza e scorrevolezza in italiano."),
        TranslationMetadata("SVV", "Statenvertaling", 2400000L, "Dutch", "De historische en gezaghebbende Nederlandse bijbelvertaling uit 1637, bepalend voor de Nederlandse taal en cultuur."),
        TranslationMetadata("CUV", "Chinese Union Version - Traditional", 2000000L, "Chinese", "和合本繁體字版，華人教會最廣泛使用與尊崇的經典聖經譯本。"),
        TranslationMetadata("CUVP", "Chinese Union Version - Pinyin", 2200000L, "Chinese", "和合本漢語拼音版，標註完整拼音，便於朗讀、學習與語言研讀。"),
        TranslationMetadata("CUVS", "Chinese Union Version - Simplified", 2000000L, "Chinese", "和合本簡體字版，文字清晰典雅，廣泛普遍地被全球簡體中文讀者使用。"),
        TranslationMetadata("VULG", "Latin Vulgate", 2600000L, "Latin", "The historic 4th-century Latin translation prepared by St. Jerome, which served as the authoritative Bible of Western Christianity for over a millennium."),
        TranslationMetadata("SUV", "Swahili Union Version", 2100000L, "Swahili", "Toleo la Bibilia la Kiswahili lenye heshima na matumizi mapana zaidi katika Afrika Mashariki na Kati.")
    )
    return englishTranslations.find { it.code.equals(code, ignoreCase = true) }
        ?: spanishTranslations.find { it.code.equals(code, ignoreCase = true) }
        ?: globalTranslations.find { it.code.equals(code, ignoreCase = true) }
        ?: TranslationMetadata(code, code, 2000000L, "Unknown", "Bible translation version.")
}

@Composable
fun TranslationDetailsDialog(
    metadata: TranslationMetadata,
    isDownloaded: Boolean = false,
    isActive: Boolean = false,
    onDismiss: () -> Unit,
    onSelect: (() -> Unit)? = null,
    onDownloadToggle: (() -> Unit)? = null
) {
    Dialog(onDismissRequest = onDismiss) {
        Card(
            shape = RoundedCornerShape(24.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp)
                .border(1.5.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.5f), RoundedCornerShape(24.dp))
        ) {
            Column(
                modifier = Modifier
                    .padding(24.dp)
                    .fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Box(
                    modifier = Modifier
                        .size(64.dp)
                        .clip(CircleShape)
                        .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.1f)),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.MenuBook,
                        contentDescription = "Version Details",
                        tint = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.size(32.dp)
                    )
                }

                Spacer(modifier = Modifier.height(16.dp))

                Text(
                    text = metadata.fullName,
                    style = MaterialTheme.typography.titleLarge,
                    fontWeight = FontWeight.ExtraBold,
                    color = MaterialTheme.colorScheme.onSurface,
                    textAlign = TextAlign.Center
                )

                Spacer(modifier = Modifier.height(6.dp))

                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    SuggestionChip(
                        onClick = {},
                        label = { Text(metadata.code, fontWeight = FontWeight.Bold) }
                    )
                    SuggestionChip(
                        onClick = {},
                        label = { Text(metadata.language) }
                    )
                    if (isActive) {
                        SuggestionChip(
                            onClick = {},
                            label = { Text("Active", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary) }
                        )
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                Card(
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Text(
                            text = "VERSION DESCRIPTION & HISTORY",
                            style = MaterialTheme.typography.labelSmall,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = metadata.description,
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            lineHeight = 22.sp
                        )
                    }
                }

                Spacer(modifier = Modifier.height(20.dp))

                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    if (onSelect != null && !isActive) {
                        Button(
                            onClick = {
                                onSelect()
                                onDismiss()
                            },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Icon(Icons.Default.CheckCircle, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(modifier = Modifier.width(8.dp))
                            Text("Set as Active Bible Version")
                        }
                    }

                    if (onDownloadToggle != null) {
                        OutlinedButton(
                            onClick = {
                                onDownloadToggle()
                            },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Icon(
                                imageVector = if (isDownloaded) Icons.Default.Delete else Icons.Default.Download,
                                contentDescription = null,
                                modifier = Modifier.size(18.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(if (isDownloaded) "Uninstall Offline Version" else "Download Offline Copy")
                        }
                    }

                    OutlinedButton(
                        onClick = onDismiss,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Text("Close")
                    }
                }
            }
        }
    }
}

