    CommonScripture("John", 1, 1, "John 1:1", "In the beginning was the Word, and the Word was with God, and the Word was God.", "Divinity"),
    CommonScripture("Proverbs", 3, 6, "Proverbs 3:6", "In all thy ways acknowledge him, and he shall direct thy paths.", "Guidance"),
    CommonScripture("Matthew", 5, 3, "Matthew 5:3", "Blessed are the poor in spirit: for theirs is the kingdom of heaven.", "Blessings"),
    CommonScripture("Romans", 8, 38, "Romans 8:38", "For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come,", "Love of God"),
