@OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class, androidx.compose.foundation.layout.ExperimentalLayoutApi::class)
@Composable
fun CommonScripturesView(
    viewModel: BibleViewModel,
    appLanguageState: String,
    onNavigateToRead: (String, Int, Int) -> Unit
) {
    val context = LocalContext.current
    val selectedTranslation by viewModel.selectedTranslation.collectAsStateWithLifecycle()
    val bookmarks by viewModel.bookmarks.collectAsStateWithLifecycle(initialValue = emptyList())
    val favorites by viewModel.favorites.collectAsStateWithLifecycle(initialValue = emptyList())

    var subTabState by remember { mutableStateOf(0) } // 0 = Scriptures, 1 = Q&A, 2 = Trivia
    var activeScripturePopup by remember { mutableStateOf<CommonScripture?>(null) }

    val subTabs = remember {
        listOf(
            Triple(0, "Inspirational", Icons.Default.MenuBook),
            Triple(1, "Christian Q&A", Icons.Default.Help),
            Triple(2, "Bible Trivia", Icons.Default.Info)
        )
    }

    Column(
        modifier = Modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        // Sub-tabs row - Styled cleanly following bottom navigation bar gray style
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f), RoundedCornerShape(14.dp))
                .padding(4.dp),
            horizontalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            subTabs.forEach { (index, title, icon) ->
                val isSelected = subTabState == index
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .height(38.dp)
                        .clip(RoundedCornerShape(10.dp))
                        .background(
                            if (isSelected) MaterialTheme.colorScheme.surfaceContainerHigh
                            else Color.Transparent
                        )
                        .clickable { subTabState = index }
                        .padding(horizontal = 4.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = icon,
                            contentDescription = null,
                            modifier = Modifier.size(15.dp),
                            tint = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Spacer(modifier = Modifier.width(6.dp))
                        Text(
                            text = translateUi(title, appLanguageState),
                            fontSize = 11.sp,
                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                            color = if (isSelected) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }
            }
        }

        when (subTabState) {
            0 -> {
                // Scriptures List Tab
                var selectedCategory by remember { mutableStateOf("All") }
