                                tint = if (isPopupFavorited) Color(0xFFFF1744) else MaterialTheme.colorScheme.primary
                            )
                            Spacer(modifier = Modifier.width(4.dp))
                            Text(if (isPopupFavorited) "Favorited" else "Favorite", fontSize = 11.sp, fontWeight = FontWeight.Bold)
