@Composable
fun HighlightColorDot(color: Color, name: String, onClick: () -> Unit) {
    val haptic = LocalHapticFeedback.current
    Box(
        modifier = Modifier
            .size(40.dp)
            .clip(CircleShape)
            .background(color)
            .clickable {
                haptic.performHapticFeedback(HapticFeedbackType.LongPress)
                onClick()
            }
            .testTag("highlight_dot_$name")
    )
}

@Composable
fun VersionComparerDialog(
    verse: BibleVerse,
    viewModel: BibleViewModel,
    onDismiss: () -> Unit
) {
    val availableTranslationsList by viewModel.availableTranslationsList.collectAsStateWithLifecycle()
    val comparedVersesList by remember(verse) {
        viewModel.getVerseAcrossTranslations(verse.bookName, verse.chapter, verse.verseNumber)
    }.collectAsStateWithLifecycle(initialValue = emptyList())
    val bookmarks by viewModel.bookmarks.collectAsStateWithLifecycle(initialValue = emptyList())
    val favorites by viewModel.favorites.collectAsStateWithLifecycle(initialValue = emptyList())

    Dialog(onDismissRequest = onDismiss) {
        Card(
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 8.dp, vertical = 24.dp)
                .border(1.5.dp, MaterialTheme.colorScheme.primary, RoundedCornerShape(16.dp))
                .testTag("version_comparer_dialog")
        ) {
            Column(
                modifier = Modifier
                    .padding(16.dp)
                    .fillMaxWidth()
            ) {
                // Header
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = "Version Comparer",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                        Spacer(modifier = Modifier.height(2.dp))
                        Text(
                            text = "${verse.bookName} ${verse.chapter}:${verse.verseNumber}",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                    IconButton(
                        onClick = onDismiss,
                        modifier = Modifier.testTag("close_comparer_btn")
                    ) {
                        Icon(Icons.Default.Close, contentDescription = "Close Comparer")
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // Scrollable list of versions
                LazyColumn(
                    verticalArrangement = Arrangement.spacedBy(10.dp),
                    modifier = Modifier
                        .weight(1f, fill = false)
                        .fillMaxWidth()
                ) {
                    items(availableTranslationsList) { translation ->
                        val matchingVerse = comparedVersesList.find { it.translation.equals(translation, ignoreCase = true) }
                        val isVersionBookmarked = matchingVerse != null && bookmarks.any { bm -> bm.translation.equals(matchingVerse.translation, ignoreCase = true) && bm.bookName.equals(matchingVerse.bookName, ignoreCase = true) && bm.chapter == matchingVerse.chapter && bm.verseNumber == matchingVerse.verseNumber }
                        val isVersionFavorited = matchingVerse != null && favorites.any { fav -> fav.translation.equals(matchingVerse.translation, ignoreCase = true) && fav.bookName.equals(matchingVerse.bookName, ignoreCase = true) && fav.chapter == matchingVerse.chapter && fav.verseNumber == matchingVerse.verseNumber }

                        Card(
                            shape = RoundedCornerShape(12.dp),
                            colors = CardDefaults.cardColors(
                                containerColor = if (translation == verse.translation) 
                                    MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.25f) 
                                else 
                                    MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f)
                            ),
                            border = androidx.compose.foundation.BorderStroke(
                                1.5.dp, 
                                if (translation == verse.translation) 
                                    MaterialTheme.colorScheme.primary 
                                else 
                                    MaterialTheme.colorScheme.outline.copy(alpha = 0.15f)
                            ),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(12.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                        Text(
                                            text = translation,
                                            fontWeight = FontWeight.Bold,
                                            style = MaterialTheme.typography.labelLarge,
                                            color = if (translation == verse.translation) 
                                                MaterialTheme.colorScheme.primary 
                                            else 
                                                MaterialTheme.colorScheme.secondary
                                        )
                                        if (translation == verse.translation) {
                                            Badge(
                                                containerColor = MaterialTheme.colorScheme.primary,
                                                contentColor = MaterialTheme.colorScheme.onPrimary
                                            ) { 
                                                Text("Current", fontSize = 9.sp, modifier = Modifier.padding(horizontal = 4.dp)) 
                                            }
                                        }
                                    }

                                    matchingVerse?.let { v ->
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            IconButton(
                                                onClick = {
                                                    if (isVersionFavorited) {
                                                        viewModel.removeFavorite(v)
                                                    } else {
                                                        viewModel.highlightVerse(v, "#FFD54F")
                                                    }
                                                },
                                                modifier = Modifier.size(28.dp)
                                            ) {
                                                Icon(
                                                    if (isVersionFavorited) Icons.Default.Favorite else Icons.Default.FavoriteBorder,
                                                    contentDescription = "Favorite",
                                                    tint = if (isVersionFavorited) Color(0xFFFF1744) else MaterialTheme.colorScheme.onSurfaceVariant,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }
                                            IconButton(
                                                onClick = {
                                                    viewModel.toggleBookmark(v)
                                                },
                                                modifier = Modifier.size(28.dp)
                                            ) {
                                                Icon(
                                                    if (isVersionBookmarked) Icons.Default.Bookmark else Icons.Default.BookmarkBorder,
                                                    contentDescription = "Bookmark",
                                                    tint = if (isVersionBookmarked) Color(0xFFFF1744) else MaterialTheme.colorScheme.onSurfaceVariant,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }
                                        }
                                    }
                                }
                                Spacer(modifier = Modifier.height(6.dp))
                                Text(
                                    text = matchingVerse?.text ?: "[Translation not loaded. Go to Settings to download $translation fully offline.]",
                                    style = MaterialTheme.typography.bodyMedium,
                                    fontStyle = if (matchingVerse == null) FontStyle.Italic else FontStyle.Normal,
                                    color = if (matchingVerse == null) 
                                        MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f) 
                                    else 
                                        MaterialTheme.colorScheme.onSurface
                                )
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                Button(
                    onClick = onDismiss,
                    modifier = Modifier.fillMaxWidth().testTag("comparer_dismiss_btn")
                ) {
                    Text("Close Comparer", fontWeight = FontWeight.Bold)
                }
            }
        }
    }
}

// -----------------------------------------------------------------
// HIGHLIGHTED TEXT UTILITY FOR SEARCH
// -----------------------------------------------------------------
@Composable
fun HighlightedText(
    text: String,
    query: String,
    style: TextStyle = MaterialTheme.typography.bodyMedium,
    fontFamily: FontFamily = FontFamily.Serif,
    color: Color = MaterialTheme.colorScheme.onSurface,
    maxLines: Int = Int.MAX_VALUE
) {
    val highlightTextColor = MaterialTheme.colorScheme.onSurface
    val annotatedString = remember(text, query, highlightTextColor) {
        buildAnnotatedString {
            val words = query.split(Regex("\\s+"))
                .filter { it.length >= 2 }
                .map { it.lowercase() }
                .distinct()
            
            if (words.isEmpty()) {
                append(text)
            } else {
                val matches = mutableListOf<IntRange>()
                val lowerText = text.lowercase()
                
                for (word in words) {
                    var startIndex = 0
                    while (startIndex < text.length) {
                        val index = lowerText.indexOf(word, startIndex)
                        if (index == -1) break
                        matches.add(index until (index + word.length))
                        startIndex = index + word.length
                    }
                }
                
                val sortedMatches = matches.sortedBy { it.first }
                val mergedMatches = mutableListOf<IntRange>()
                for (range in sortedMatches) {
                    if (mergedMatches.isEmpty()) {
                        mergedMatches.add(range)
                    } else {
                        val last = mergedMatches.last()
                        if (range.first <= last.last + 1) {
                            val newRange = last.first..maxOf(last.last, range.last)
                            mergedMatches[mergedMatches.size - 1] = newRange
                        } else {
                            mergedMatches.add(range)
                        }
                    }
                }
                
                var lastIndex = 0
                for (range in mergedMatches) {
                    if (range.first > lastIndex) {
                        append(text.substring(lastIndex, range.first))
                    }
                    pushStyle(
                        SpanStyle(
                            background = GreenTone.copy(alpha = 0.45f),
                            fontWeight = FontWeight.Bold,
                            color = highlightTextColor
                        )
                    )
                    append(text.substring(range.first, range.last + 1))
                    pop()
                    lastIndex = range.last + 1
                }
                if (lastIndex < text.length) {
                    append(text.substring(lastIndex))
                }
            }
        }
    }
    
    Text(
        text = annotatedString,
        style = style,
        fontFamily = fontFamily,
        color = color,
        maxLines = maxLines,
        overflow = if (maxLines != Int.MAX_VALUE) TextOverflow.Ellipsis else TextOverflow.Clip
    )
}

// -----------------------------------------------------------------
// 2. SEARCH SCREEN (VERSE FINDER)
// -----------------------------------------------------------------
@OptIn(ExperimentalLayoutApi::class)
@Composable
fun SearchScreen(viewModel: BibleViewModel, speakText: (String, String) -> Unit) {
    val searchQuery by viewModel.searchQuery.collectAsStateWithLifecycle()
    val isSearching by viewModel.isSearching.collectAsStateWithLifecycle()
    val searchResults by viewModel.searchResults.collectAsStateWithLifecycle()
    val recentSearches by viewModel.recentSearches.collectAsStateWithLifecycle()

    Column(modifier = Modifier.fillMaxSize().padding(16.dp)) {
        // Search Input
        OutlinedTextField(
            value = searchQuery,
            onValueChange = { viewModel.updateSearchQuery(it) },
            modifier = Modifier
                .fillMaxWidth()
                .testTag("search_input"),
            placeholder = { Text("Search for words e.g., 'shepherd', 'beginning', 'love'") },
            leadingIcon = { Icon(Icons.Default.Search, contentDescription = "Search Icon") },
            trailingIcon = {
                if (searchQuery.isNotEmpty()) {
                    IconButton(onClick = { viewModel.updateSearchQuery("") }) {
                        Icon(Icons.Default.Close, contentDescription = "Clear")
                    }
                }
            },
            singleLine = true,
            colors = OutlinedTextFieldDefaults.colors(
                focusedBorderColor = MaterialTheme.colorScheme.primary,
                unfocusedBorderColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.3f)
            ),
            shape = RoundedCornerShape(12.dp)
        )

        Spacer(modifier = Modifier.height(16.dp))

        // State displays
        if (isSearching) {
            Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                CircularProgressIndicator()
            }
        } else if (searchQuery.isBlank()) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .weight(1f)
                    .verticalScroll(rememberScrollState())
            ) {
                // Room persistent Recent Searches card
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("search_screen_recent_searches_card"),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceContainerLow),
                    shape = RoundedCornerShape(16.dp),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f))
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(
                                    imageVector = Icons.Default.History,
                                    contentDescription = null,
                                    tint = MaterialTheme.colorScheme.primary,
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = "Recent Searches",
                                    style = MaterialTheme.typography.titleMedium,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                            }
                            if (recentSearches.isNotEmpty()) {
                                TextButton(
                                    onClick = { viewModel.clearRecentSearches() },
                                    contentPadding = PaddingValues(horizontal = 8.dp, vertical = 2.dp)
                                ) {
                                    Text("Clear All", fontSize = 12.sp, color = MaterialTheme.colorScheme.error)
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(12.dp))

                        if (recentSearches.isEmpty()) {
                            Text(
                                text = "Your search history is empty. Terms you search for will appear here.",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                                modifier = Modifier.padding(vertical = 8.dp)
                            )
                        } else {
                            androidx.compose.foundation.layout.FlowRow(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                recentSearches.forEach { term ->
                                    InputChip(
                                        selected = false,
                                        onClick = { viewModel.updateSearchQuery(term) },
                                        label = { Text(term, fontSize = 13.sp) },
                                        leadingIcon = {
                                            Icon(
                                                Icons.Default.History,
                                                contentDescription = null,
                                                modifier = Modifier.size(14.dp)
                                            )
                                        },
                                        trailingIcon = {
                                            IconButton(
                                                onClick = { viewModel.deleteRecentSearch(term) },
                                                modifier = Modifier.size(16.dp)
                                            ) {
                                                Icon(
                                                    Icons.Default.Close,
                                                    contentDescription = "Delete term",
                                                    modifier = Modifier.size(12.dp)
                                                )
                                            }
                                        },
                                        shape = RoundedCornerShape(10.dp)
                                    )
                                }
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(24.dp))

                // Friendly guide display
                Box(
                    modifier = Modifier.fillMaxWidth(),
                    contentAlignment = Alignment.Center
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        modifier = Modifier.padding(16.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Search,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.primary.copy(alpha = 0.3f),
                            modifier = Modifier.size(64.dp)
                        )
                        Spacer(modifier = Modifier.height(12.dp))
                        Text(
                            text = "Quick Verse Discovery",
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.titleMedium,
                            color = MaterialTheme.colorScheme.primary
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = "Type words to search scripture in all translations instantly offline.\nTry searching for: 'light', 'God', 'soul', or 'shepherd'.",
                            textAlign = TextAlign.Center,
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
                        )
                    }
                }
            }
        } else if (searchResults.isEmpty()) {
            Box(
                modifier = Modifier.fillMaxSize().weight(1f),
                contentAlignment = Alignment.Center
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Icon(
                        imageVector = Icons.Default.SentimentDissatisfied,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.secondary.copy(alpha = 0.5f),
                        modifier = Modifier.size(56.dp)
                    )
                    Spacer(modifier = Modifier.height(12.dp))
                    Text(
                        text = "No verses found matching \"$searchQuery\"",
                        style = MaterialTheme.typography.titleMedium,
                        color = MaterialTheme.colorScheme.secondary
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "Try searching other keywords.",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
                    )
                }
            }
        } else {
            // Results list
            Text(
                text = "${searchResults.size} results found",
                style = MaterialTheme.typography.labelLarge,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.primary,
                modifier = Modifier.padding(bottom = 8.dp)
            )

            LazyColumn(
                modifier = Modifier.fillMaxSize().weight(1f),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                items(searchResults) { verse ->
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                // Go directly to read screen with selected book/chapter/translation loaded
                                viewModel.selectTranslation(verse.translation)
                                viewModel.selectBook(verse.bookName)
                                viewModel.selectChapter(verse.chapter)
                                viewModel.navigateTo(Screen.READ)
                            },
                        shape = RoundedCornerShape(10.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                    ) {
                        Column(modifier = Modifier.padding(12.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "${verse.bookName} ${verse.chapter}:${verse.verseNumber}",
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.titleSmall,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Badge(
                                    containerColor = MaterialTheme.colorScheme.primaryContainer,
                                    contentColor = MaterialTheme.colorScheme.onPrimaryContainer
                                ) {
                                    Text(verse.translation, fontSize = 10.sp, fontWeight = FontWeight.Bold, modifier = Modifier.padding(horizontal = 4.dp, vertical = 2.dp))
                                }
                            }
                            
                            Spacer(modifier = Modifier.height(6.dp))
                            
                            HighlightedText(
                                text = verse.text,
                                query = searchQuery,
                                style = MaterialTheme.typography.bodyMedium,
                                fontFamily = FontFamily.Serif,
                                color = MaterialTheme.colorScheme.onSurface,
                                maxLines = 3
                            )

                            Spacer(modifier = Modifier.height(8.dp))

                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.End,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                IconButton(
                                    onClick = { speakText(verse.text, "${verse.bookName} ${verse.chapter}:${verse.verseNumber} (${verse.translation})") },
                                    modifier = Modifier.size(36.dp).testTag("search_read_aloud_${verse.id}")
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.VolumeUp,
                                        contentDescription = "Read Aloud",
                                        tint = MaterialTheme.colorScheme.primary,
                                        modifier = Modifier.size(20.dp)
                                    )
                                }
                                
                                Spacer(modifier = Modifier.width(8.dp))

                                FilledTonalButton(
                                    onClick = {
                                        viewModel.selectTranslation(verse.translation)
                                        viewModel.selectBook(verse.bookName)
                                        viewModel.selectChapter(verse.chapter)
                                        viewModel.navigateTo(Screen.READ)
                                    },
                                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp),
                                    modifier = Modifier.height(32.dp).testTag("search_go_to_${verse.id}")
                                ) {
                                    Icon(Icons.AutoMirrored.Filled.MenuBook, contentDescription = null, modifier = Modifier.size(14.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Open", fontSize = 11.sp)
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// -----------------------------------------------------------------
// 3. DEVOTIONS SCREEN
// -----------------------------------------------------------------
@Composable
fun DevotionsScreen(
    viewModel: BibleViewModel,
    speakText: (String, String) -> Unit,
    stopSpeaking: () -> Unit,
    currentReadingText: String?
) {
    val devotionals by viewModel.allDevotionals.collectAsStateWithLifecycle()
    val selectedDevotional by viewModel.selectedDevotional.collectAsStateWithLifecycle()
    
    val aiTopicInput by viewModel.aiTopicInput.collectAsStateWithLifecycle()
    val isAiGenerating by viewModel.isAiGenerating.collectAsStateWithLifecycle()
    val aiError by viewModel.aiError.collectAsStateWithLifecycle()

    var activeTab by remember { mutableStateOf(0) } // 0 = Daily, 1 = AI Devotional

    Column(modifier = Modifier.fillMaxSize().padding(16.dp)) {
        // Tab row switch
        TabRow(
            selectedTabIndex = activeTab,
            containerColor = Color.Transparent,
            modifier = Modifier.fillMaxWidth().padding(bottom = 16.dp)
        ) {
            Tab(
                selected = activeTab == 0,
                onClick = { activeTab = 0 },
                text = { Text("Daily Devotions", fontWeight = FontWeight.Bold) }
            )
            Tab(
                selected = activeTab == 1,
                onClick = { activeTab = 1 },
                text = { Text("AI Personal Devotion", fontWeight = FontWeight.Bold) }
            )
        }

        if (activeTab == 0) {
            // Daily offline devotionals
            if (selectedDevotional != null) {
                val dev = selectedDevotional!!
                LazyColumn(
                    modifier = Modifier.fillMaxSize().weight(1f),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    item {
                        // Bible Devotional Picture Banner
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(140.dp)
                                .clip(RoundedCornerShape(16.dp))
                        ) {
                            androidx.compose.foundation.Image(
                                painter = rememberAsyncImagePainter(R.drawable.img_bible_tulips_1785156601787),
                                contentDescription = "Daily Devotions Banner",
                                modifier = Modifier.fillMaxSize(),
                                contentScale = ContentScale.Crop
                            )
                            Box(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .background(
                                        Brush.verticalGradient(
                                            colors = listOf(Color.Transparent, MaterialTheme.colorScheme.surface.copy(alpha = 0.85f))
                                        )
                                    )
                            )
                        }

                        Spacer(modifier = Modifier.height(10.dp))

                        Card(
                            shape = RoundedCornerShape(16.dp),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            elevation = CardDefaults.cardElevation(defaultElevation = 4.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(18.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                        Text(
                                            text = dev.date,
                                            style = MaterialTheme.typography.labelLarge,
                                            color = MaterialTheme.colorScheme.primary,
                                            fontWeight = FontWeight.Bold
                                        )
                                        if (dev.isCustom) {
                                            Badge(containerColor = MaterialTheme.colorScheme.tertiaryContainer) {
                                                Text("AI Generated", fontSize = 10.sp, fontWeight = FontWeight.Bold, modifier = Modifier.padding(horizontal = 4.dp))
                                            }
                                        }
                                    }
                                    
                                    val devotionTitle = "Devotional: ${dev.title}"
                                    val isListeningDevotion = currentReadingText == devotionTitle
                                    AssistChip(
                                        onClick = {
                                            if (isListeningDevotion) {
                                                stopSpeaking()
                                            } else {
                                                val speakTextForDev = "Today's Devotional: ${dev.title}. Scripture focus: ${dev.scripture}. Reflection notes: ${dev.content}. Prayer: ${dev.prayer}."
                                                speakText(speakTextForDev, devotionTitle)
                                            }
                                        },
                                        label = {
                                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                                Icon(
                                                    imageVector = if (isListeningDevotion) Icons.Default.VolumeOff else Icons.Default.VolumeUp,
                                                    contentDescription = if (isListeningDevotion) "Stop Listening" else "Listen Aloud",
                                                    modifier = Modifier.size(14.dp),
                                                    tint = if (isListeningDevotion) Color(0xFFFF1744) else MaterialTheme.colorScheme.primary
                                                )
                                                Text(if (isListeningDevotion) "Stop" else "Listen", fontSize = 11.sp)
                                            }
                                        },
                                        modifier = Modifier.testTag("listen_devotional_btn")
                                    )
                                }
                                
                                Spacer(modifier = Modifier.height(8.dp))
                                
                                Text(
                                    text = dev.title,
                                    fontFamily = FontFamily.Serif,
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.headlineSmall,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                
                                Spacer(modifier = Modifier.height(12.dp))

                                // Scripture Box
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.08f))
                                        .padding(12.dp)
                                ) {
                                    Column {
                                        Text(
                                            text = "FOCUS SCRIPTURE",
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 11.sp,
                                            color = MaterialTheme.colorScheme.primary
                                        )
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = dev.scripture,
                                            fontStyle = FontStyle.Italic,
                                            fontSize = 15.sp,
                                            lineHeight = 22.sp,
                                            fontFamily = FontFamily.Serif,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                    }
                                }

                                Spacer(modifier = Modifier.height(16.dp))

                                // Reflection
                                Text(
                                    text = "Reflection",
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.titleMedium,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Spacer(modifier = Modifier.height(6.dp))
                                Text(
                                    text = dev.content,
                                    fontSize = 16.sp,
                                    lineHeight = 25.sp,
                                    color = MaterialTheme.colorScheme.onSurface
                                )

                                Spacer(modifier = Modifier.height(20.dp))

                                // Prayer
                                Text(
                                    text = "Today's Prayer",
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.titleMedium,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Spacer(modifier = Modifier.height(6.dp))
                                Text(
                                    text = dev.prayer,
                                    fontSize = 15.sp,
                                    lineHeight = 23.sp,
                                    fontStyle = FontStyle.Italic,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.9f)
                                )

                                Spacer(modifier = Modifier.height(18.dp))

                                // Discuss Devotion with Gemini AI Chatbot
                                Button(
                                    onClick = { viewModel.startDevotionalAIChat(dev.title, dev.scripture, dev.content) },
                                    colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.tertiary),
                                    shape = RoundedCornerShape(12.dp),
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(48.dp)
                                        .testTag("discuss_devotion_ai_btn")
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Icon(
                                            imageVector = Icons.Default.AutoAwesome,
                                            contentDescription = null,
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text(
                                            text = "Reflect & Discuss in Bible Bridge Chat",
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 14.sp
                                        )
                                    }
                                }
                            }
                        }
                    }

                    // Horizontal selection of other devotions
                    item {
                        Text(
                            text = "Browse Other Days",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.padding(top = 8.dp)
                        )
                    }

                    items(devotionals) { otherDev ->
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { viewModel.selectDevotional(otherDev) },
                            colors = CardDefaults.cardColors(
                                containerColor = if (otherDev.id == dev.id) MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)
                                else MaterialTheme.colorScheme.surface
                            )
                        ) {
                            Row(
                                modifier = Modifier.padding(12.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(otherDev.date, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                    Text(otherDev.title, fontWeight = FontWeight.Bold, fontSize = 15.sp)
                                }
                                Icon(Icons.Default.ChevronRight, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                            }
                        }
                    }
                }
            } else {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text("No devotionals loaded")
                }
            }
        } else {
            // AI Devotional Assistant (Gemini)
            LazyColumn(
                modifier = Modifier.fillMaxSize(),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                item {
                    // Picture on Personalized AI Devotion Tab
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(140.dp)
                            .clip(RoundedCornerShape(16.dp))
                    ) {
                        androidx.compose.foundation.Image(
                            painter = rememberAsyncImagePainter(R.drawable.img_ai_devotion_selected_1785161815453),
                            contentDescription = "Personalized AI Devotion Banner Image",
                            modifier = Modifier.fillMaxSize(),
                            contentScale = ContentScale.Crop
                        )
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .background(
                                    Brush.verticalGradient(
                                        colors = listOf(Color.Transparent, MaterialTheme.colorScheme.surface.copy(alpha = 0.85f))
                                    )
                                )
                        )
                        Row(
                            modifier = Modifier
                                .align(Alignment.BottomStart)
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.AutoAwesome,
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.size(20.dp)
                            )
                            Text(
                                text = "Personalized AI Devotion",
                                style = MaterialTheme.typography.titleMedium,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        }
                    }
                }
                item {
                    Card(
                        shape = RoundedCornerShape(16.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(modifier = Modifier.padding(16.dp)) {
                            Text(
                                text = "Personalized Devotion Assistant",
                                style = MaterialTheme.typography.titleMedium,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "Generate a custom devotion or prayer tailored exactly to what is on your heart right now. (Requires internet connection).",
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                            )
                            
                            Spacer(modifier = Modifier.height(16.dp))

                            OutlinedTextField(
                                value = aiTopicInput,
                                onValueChange = { viewModel.updateAiTopicInput(it) },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("ai_devotional_input"),
                                label = { Text("Topic or Verse (e.g., Peace, Psalm 23, Romans 8:28)") },
                                placeholder = { Text("Ex: Courage during transitions, finding peace...") },
                                maxLines = 2,
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedBorderColor = MaterialTheme.colorScheme.primary
                                )
                            )

                            Spacer(modifier = Modifier.height(12.dp))

                            if (aiError != null) {
                                Card(
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer),
                                    modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp)
                                ) {
                                    Text(
                                        text = aiError!!,
                                        color = MaterialTheme.colorScheme.onErrorContainer,
                                        fontSize = 13.sp,
                                        modifier = Modifier.padding(8.dp)
                                    )
                                }
                            }

                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Button(
                                    onClick = { viewModel.generateAiDevotional() },
                                    modifier = Modifier
                                        .weight(1f)
                                        .height(48.dp)
                                        .testTag("generate_devotional_button"),
                                    enabled = aiTopicInput.isNotBlank() && !isAiGenerating
                                ) {
                                    if (isAiGenerating) {
                                        CircularProgressIndicator(
                                            modifier = Modifier.size(20.dp),
                                            color = MaterialTheme.colorScheme.onPrimary,
                                            strokeWidth = 2.dp
                                        )
                                    } else {
                                        Icon(Icons.Default.AutoAwesome, contentDescription = null, modifier = Modifier.size(18.dp))
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text("Generate", fontSize = 13.sp)
                                    }
                                }

                                OutlinedButton(
                                    onClick = { viewModel.generateDevotionalForRandomVerse() },
                                    modifier = Modifier
                                        .weight(1f)
                                        .height(48.dp)
                                        .testTag("generate_random_verse_devotion_btn"),
                                    enabled = !isAiGenerating
                                ) {
                                    Icon(Icons.Default.Shuffle, contentDescription = null, modifier = Modifier.size(18.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Random Verse", fontSize = 13.sp)
                                }
                            }

                            Spacer(modifier = Modifier.height(8.dp))

                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Save,
                                    contentDescription = null,
                                    tint = MaterialTheme.colorScheme.primary,
                                    modifier = Modifier.size(14.dp)
                                )
                                Text(
                                    text = "All generated devotionals are saved locally in Room DB for offline access.",
                                    fontSize = 11.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        }
                    }
                }
                
                // Show currently generated custom devotion (or a placeholder guidance)
                if (selectedDevotional?.isCustom == true) {
                    val customDev = selectedDevotional!!
                    item {
                        Card(
                            shape = RoundedCornerShape(16.dp),
                            border = CardDefaults.outlinedCardBorder(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("YOUR GENERATED DEVOTION", style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold)
                                    Badge(containerColor = MaterialTheme.colorScheme.primary) { Text("Saved Offline", fontSize = 10.sp, fontWeight = FontWeight.Bold, modifier = Modifier.padding(horizontal = 4.dp)) }
                                }
                                
                                Spacer(modifier = Modifier.height(12.dp))
                                
                                Text(customDev.title, fontFamily = FontFamily.Serif, fontWeight = FontWeight.Bold, style = MaterialTheme.typography.headlineSmall)
                                
                                Spacer(modifier = Modifier.height(8.dp))
                                
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.1f))
                                        .padding(10.dp)
                                ) {
                                    Text(customDev.scripture, fontStyle = FontStyle.Italic, fontSize = 14.sp, fontFamily = FontFamily.Serif)
                                }

                                Spacer(modifier = Modifier.height(12.dp))

                                Text("Reflection", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                Text(customDev.content, fontSize = 15.sp, lineHeight = 23.sp)

                                Spacer(modifier = Modifier.height(16.dp))

                                Text("Prayer", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                Text(customDev.prayer, fontStyle = FontStyle.Italic, fontSize = 15.sp, lineHeight = 23.sp)
                            }
                        }
                    }
                } else {
                    item {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(32.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = "Your generated devotions will appear here and be stored offline automatically.",
                                textAlign = TextAlign.Center,
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.5f)
                            )
                        }
                    }
                }
            }
        }
    }
}

// -----------------------------------------------------------------
// INTERACTIVE TIMELINE VISUALIZATION COMPONENT
// -----------------------------------------------------------------
@Composable
fun InteractiveBibleTimelineMap(
    events: List<TimelineEvent>,
    selectedEvent: TimelineEvent?,
    onEventSelected: (TimelineEvent?) -> Unit,
    selectedBookFilter: String?,
    onBookFilterSelected: (String?) -> Unit,
    selectedEraFilter: String?,
    onEraFilterSelected: (String?) -> Unit
) {
    val localDensity = LocalDensity.current
    // 6 Eras representing historical chronological periods
    val erasList = listOf(
        "Primeval",
        "Exodus",
        "Monarchy",
        "Exile",
        "Messianic",
        "Apostolic"
    )
    // 8 Books in canonical sequence
    val booksList = listOf(
        "Genesis",
        "Exodus",
        "2 Samuel",
        "1 Kings",
        "2 Kings",
        "Matthew",
        "Luke",
        "Acts"
    )

    // Helper to calculate coordinate positions
    fun getCoordinates(event: TimelineEvent): Pair<Int, Int> {
        val eraIdx = when (event.period) {
            "Beginning of Time", "c. 2500 BC", "c. 2100 BC" -> 0
            "c. 1446 BC", "c. 1445 BC" -> 1
            "c. 1010 BC", "c. 930 BC" -> 2
            "586 BC" -> 3
            "c. 4 BC", "c. AD 28", "c. AD 30" -> {
                if (event.title.contains("Pentecost") || event.scriptureRef.contains("Acts")) 5 else 4
            }
            else -> {
                if (event.scriptureRef.contains("Genesis")) 0
                else if (event.scriptureRef.contains("Exodus")) 1
                else if (event.scriptureRef.contains("Samuel")) 2
                else if (event.scriptureRef.contains("Kings") && !event.title.contains("Exile")) 2
                else if (event.title.contains("Exile")) 3
                else if (event.scriptureRef.contains("Luke") || event.scriptureRef.contains("Matthew")) 4
                else 5
            }
        }
        val bookIdx = when {
            event.scriptureRef.contains("Genesis") -> 0
            event.scriptureRef.contains("Exodus") -> 1
            event.scriptureRef.contains("2 Samuel") -> 2
            event.scriptureRef.contains("1 Kings") -> 3
            event.scriptureRef.contains("2 Kings") -> 4
            event.scriptureRef.contains("Matthew") -> 5
            event.scriptureRef.contains("Luke") -> 6
            event.scriptureRef.contains("Acts") -> 7
            else -> 0
        }
        return Pair(eraIdx, bookIdx)
    }

    val coordsMap = remember(events) {
        events.groupBy { getCoordinates(it) }
    }

    val primaryColor = MaterialTheme.colorScheme.primary
    val secondaryColor = MaterialTheme.colorScheme.secondary
    val tertiaryColor = MaterialTheme.colorScheme.tertiary
    val onSurfaceColor = MaterialTheme.colorScheme.onSurface
    val gridColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f)

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .testTag("interactive_timeline_container"),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.15f))
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Default.Timeline,
                        contentDescription = null,
                        tint = primaryColor,
                        modifier = Modifier.size(20.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "Interactive Chronology Map",
                        style = MaterialTheme.typography.titleMedium,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                }
                IconButton(
                    onClick = {
                        onEventSelected(null)
                        onBookFilterSelected("All Books")
                        onEraFilterSelected("All Eras")
                    }
                ) {
                    Icon(
                        imageVector = Icons.Default.Refresh,
                        contentDescription = "Reset Filters",
                        tint = primaryColor.copy(alpha = 0.7f),
                        modifier = Modifier.size(20.dp)
                    )
                }
            }

            Text(
                text = "Tap event nodes to trace the narrative flow between historical timelines and canonical Bible books.",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                modifier = Modifier.padding(bottom = 12.dp)
            )

            BoxWithConstraints(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(240.dp)
                    .background(
                        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.25f),
                        shape = RoundedCornerShape(12.dp)
                    )
                    .border(
                        width = 1.dp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.05f),
                        shape = RoundedCornerShape(12.dp)
                    )
            ) {
                val widthPx = constraints.maxWidth.toFloat()
                val heightPx = constraints.maxHeight.toFloat()

                val widthDp = maxWidth
                val heightDp = maxHeight

                val leftMarginDp = 75.dp
                val rightMarginDp = 16.dp
                val topMarginDp = 20.dp
                val bottomMarginDp = 30.dp

                val plotWidthDp = widthDp - leftMarginDp - rightMarginDp
                val plotHeightDp = heightDp - topMarginDp - bottomMarginDp

                fun getPlotCoords(event: TimelineEvent): androidx.compose.ui.geometry.Offset {
                    val (eraIdx, bookIdx) = getCoordinates(event)
                    val group = coordsMap[Pair(eraIdx, bookIdx)] ?: emptyList()
                    val idx = group.indexOf(event)
                    val total = group.size

                    val stepX = if (erasList.size > 1) plotWidthDp.value / (erasList.size - 1).toFloat() else 0f
                    val stepY = if (booksList.size > 1) plotHeightDp.value / (booksList.size - 1).toFloat() else 0f

                    var xVal = leftMarginDp.value + eraIdx * stepX
                    var yVal = topMarginDp.value + (booksList.size - 1 - bookIdx) * stepY

                    // Stagger spacing horizontally for overlapping coordinates
                    if (total > 1) {
                        val spacing = 12f
                        val startOffset = -((total - 1) * spacing / 2f)
                        xVal += startOffset + idx * spacing
                    }

                    val dVal = localDensity.density
                    return androidx.compose.ui.geometry.Offset(
                        xVal * dVal,
                        yVal * dVal
                    )
                }

                val pointsList = remember(events, coordsMap) {
                    events.map { event -> Pair(event, getPlotCoords(event)) }
                }

                Canvas(
                    modifier = Modifier
                        .fillMaxSize()
                        .pointerInput(pointsList) {
                            detectTapGestures { offset ->
                                var minDistance = Float.MAX_VALUE
                                var closestEvent: TimelineEvent? = null
                                pointsList.forEach { (event, point) ->
                                    val dist = (offset.x - point.x) * (offset.x - point.x) + (offset.y - point.y) * (offset.y - point.y)
                                    if (dist < minDistance) {
                                        minDistance = dist
                                        closestEvent = event
                                    }
                                }
                                val thresholdPx = with(localDensity) { 24.dp.toPx() }
                                if (minDistance < thresholdPx * thresholdPx && closestEvent != null) {
                                    onEventSelected(closestEvent)
                                    val (eraIdx, bookIdx) = getCoordinates(closestEvent!!)
                                    onBookFilterSelected(booksList[bookIdx])
                                    onEraFilterSelected(erasList[eraIdx])
                                }
                            }
                        }
                ) {
                    val stepYPx = if (booksList.size > 1) (plotHeightDp.toPx() / (booksList.size - 1).toFloat()) else 0f
                    val startXPx = leftMarginDp.toPx()
                    val endXPx = (widthDp - rightMarginDp).toPx()

                    for (i in booksList.indices) {
                        val y = topMarginDp.toPx() + i * stepYPx
                        drawLine(
                            color = gridColor,
                            start = androidx.compose.ui.geometry.Offset(startXPx, y),
                            end = androidx.compose.ui.geometry.Offset(endXPx, y),
                            strokeWidth = 1f,
                            pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(10f, 10f))
                        )
                    }

                    val stepXPx = if (erasList.size > 1) (plotWidthDp.toPx() / (erasList.size - 1).toFloat()) else 0f
                    val startYPx = topMarginDp.toPx()
                    val endYPx = (heightDp - bottomMarginDp).toPx()

                    for (i in erasList.indices) {
                        val x = leftMarginDp.toPx() + i * stepXPx
                        drawLine(
                            color = gridColor,
                            start = androidx.compose.ui.geometry.Offset(x, startYPx),
                            end = androidx.compose.ui.geometry.Offset(x, endYPx),
                            strokeWidth = 1f,
                            pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(10f, 10f))
                        )
                    }

                    // Winding path connecting the chronological flow
                    val windingPath = androidx.compose.ui.graphics.Path()
                    pointsList.forEachIndexed { idx, (_, point) ->
                        if (idx == 0) {
                            windingPath.moveTo(point.x, point.y)
                        } else {
                            windingPath.lineTo(point.x, point.y)
                        }
                    }
                    drawPath(
                        path = windingPath,
                        color = primaryColor.copy(alpha = 0.2f),
                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                            width = 3f,
                            pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(12f, 8f))
                        )
                    )

                    // Draw event points
                    pointsList.forEach { (event, point) ->
                        val isMatched = (selectedEvent == event)
                        val isBookMatch = (selectedBookFilter == "All Books" || selectedBookFilter == booksList[getCoordinates(event).second])
                        val isEraMatch = (selectedEraFilter == "All Eras" || selectedEraFilter == erasList[getCoordinates(event).first])
                        val isDimmed = !isBookMatch || !isEraMatch

                        val dotColor = when {
                            isMatched -> primaryColor
                            event.scriptureRef.contains("Acts") || event.scriptureRef.contains("Luke") || event.scriptureRef.contains("Matthew") -> tertiaryColor
                            else -> secondaryColor
                        }

                        val radius = if (isMatched) 9.dp.toPx() else 6.dp.toPx()
                        val opacity = if (isDimmed) 0.25f else 1f

                        if (isMatched) {
                            drawCircle(
                                color = primaryColor.copy(alpha = 0.25f),
                                radius = 16.dp.toPx(),
                                center = point
                            )
                        }

                        drawCircle(
                            color = dotColor.copy(alpha = opacity),
                            radius = radius,
                            center = point
                        )

                        drawCircle(
                            color = Color.White.copy(alpha = opacity),
                            radius = if (isMatched) 3.5.dp.toPx() else 2.dp.toPx(),
                            center = point
                        )
                    }
                }

                // Overlay Book Labels on the Y Axis
                val stepY = if (booksList.size > 1) plotHeightDp / (booksList.size - 1).toFloat() else 0.dp
                booksList.forEachIndexed { idx, book ->
                    val yVal = topMarginDp + stepY * (booksList.size - 1 - idx)
                    val isFiltered = (selectedBookFilter == book)
                    Text(
                        text = book,
                        style = MaterialTheme.typography.labelSmall,
                        fontWeight = if (isFiltered) FontWeight.Bold else FontWeight.Medium,
                        color = if (isFiltered) primaryColor else onSurfaceColor.copy(alpha = 0.6f),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier
                            .width(70.dp)
                            .offset(x = 4.dp, y = yVal - 8.dp)
                            .clickable {
                                onBookFilterSelected(if (isFiltered) "All Books" else book)
                            }
                    )
                }

                // Overlay Era Labels on the X Axis
                val stepX = if (erasList.size > 1) plotWidthDp / (erasList.size - 1).toFloat() else 0.dp
                erasList.forEachIndexed { idx, era ->
                    val xVal = leftMarginDp + stepX * idx
                    val isFiltered = (selectedEraFilter == era)
                    Text(
                        text = era,
                        style = MaterialTheme.typography.labelSmall,
                        fontWeight = if (isFiltered) FontWeight.Bold else FontWeight.Medium,
                        color = if (isFiltered) primaryColor else onSurfaceColor.copy(alpha = 0.6f),
                        textAlign = TextAlign.Center,
                        modifier = Modifier
                            .width(60.dp)
                            .offset(x = xVal - 30.dp, y = heightDp - 22.dp)
                            .clickable {
                                onEraFilterSelected(if (isFiltered) "All Eras" else era)
                            }
                    )
                }
            }
        }
    }
}

// -----------------------------------------------------------------
// 4. TIMELINE SCREEN (BIBLICAL CHRONOLOGY & BOOK OVERVIEWS)
// -----------------------------------------------------------------
@OptIn(androidx.compose.foundation.layout.ExperimentalLayoutApi::class)
@Composable
fun TimelineScreen(
    viewModel: BibleViewModel,
    speakText: (String, String) -> Unit,
    stopSpeaking: () -> Unit,
    currentReadingText: String?
) {
    val events by viewModel.timelineEventsFlow.collectAsStateWithLifecycle()
    val availableBooks by viewModel.availableBooks.collectAsStateWithLifecycle()
    val selectedOverviewBook by viewModel.selectedOverviewBook.collectAsStateWithLifecycle()
    val selectedOverview by viewModel.selectedBookOverview.collectAsStateWithLifecycle()

    // COLLECT STATES FROM VIEWMODEL
    val selectedSection by viewModel.selectedStudySection.collectAsStateWithLifecycle()
    val selectedConcordanceEntry by viewModel.selectedConcordanceEntry.collectAsStateWithLifecycle()
    val concordanceSearchQuery by viewModel.concordanceSearchQuery.collectAsStateWithLifecycle()
    val concordanceLoading by viewModel.concordanceLoading.collectAsStateWithLifecycle()
    val concordanceError by viewModel.concordanceError.collectAsStateWithLifecycle()

    var showOverviewBookDropdown by remember { mutableStateOf(false) }

    var activeConcordanceView by remember { mutableStateOf("lander") }
    var selectedLetter by remember { mutableStateOf<Char?>(null) }
    var activeReadingVerseRef by remember { mutableStateOf<String?>(null) }
    var lastViewedWord by remember { mutableStateOf<String?>(null) }

    LaunchedEffect(selectedConcordanceEntry) {
        if (lastViewedWord != null && lastViewedWord != selectedConcordanceEntry.word) {
            activeConcordanceView = "study_profile"
        }
        lastViewedWord = selectedConcordanceEntry.word
    }

    // State definitions for interactive Bible timeline map
    val erasListHelper = listOf("Primeval", "Exodus", "Monarchy", "Exile", "Messianic", "Apostolic")
    val booksListHelper = listOf("Genesis", "Exodus", "2 Samuel", "1 Kings", "2 Kings", "Matthew", "Luke", "Acts")

    fun getCoordinatesHelper(event: TimelineEvent): Pair<Int, Int> {
        val eraIdx = when (event.period) {
            "Beginning of Time", "c. 2500 BC", "c. 2100 BC" -> 0
            "c. 1446 BC", "c. 1445 BC" -> 1
            "c. 1010 BC", "c. 930 BC" -> 2
            "586 BC" -> 3
            "c. 4 BC", "c. AD 28", "c. AD 30" -> {
                if (event.title.contains("Pentecost") || event.scriptureRef.contains("Acts")) 5 else 4
            }
            else -> {
                if (event.scriptureRef.contains("Genesis")) 0
                else if (event.scriptureRef.contains("Exodus")) 1
                else if (event.scriptureRef.contains("Samuel")) 2
                else if (event.scriptureRef.contains("Kings") && !event.title.contains("Exile")) 2
                else if (event.title.contains("Exile")) 3
                else if (event.scriptureRef.contains("Luke") || event.scriptureRef.contains("Matthew")) 4
                else 5
            }
        }
        val bookIdx = when {
            event.scriptureRef.contains("Genesis") -> 0
            event.scriptureRef.contains("Exodus") -> 1
            event.scriptureRef.contains("2 Samuel") -> 2
            event.scriptureRef.contains("1 Kings") -> 3
            event.scriptureRef.contains("2 Kings") -> 4
            event.scriptureRef.contains("Matthew") -> 5
            event.scriptureRef.contains("Luke") -> 6
            event.scriptureRef.contains("Acts") -> 7
            else -> 0
        }
        return Pair(eraIdx, bookIdx)
    }

    var selectedBookFilter by remember { mutableStateOf<String?>("All Books") }
    var selectedEraFilter by remember { mutableStateOf<String?>("All Eras") }
    var selectedPlottedEvent by remember { mutableStateOf<TimelineEvent?>(null) }

    val filteredEvents = remember(events, selectedBookFilter, selectedEraFilter) {
        events.filter { event ->
            val (eraIdx, bookIdx) = getCoordinatesHelper(event)
            val bookName = booksListHelper[bookIdx]
            val eraName = erasListHelper[eraIdx]
            
            val bookMatches = (selectedBookFilter == "All Books" || selectedBookFilter == bookName)
            val eraMatches = (selectedEraFilter == "All Eras" || selectedEraFilter == eraName)
            bookMatches && eraMatches
        }
    }

    if (selectedSection == -1) {
        // STUDY HUB DASHBOARD
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
                .verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Column(modifier = Modifier.padding(bottom = 4.dp)) {
                // Bible Timeline Map Picture Banner
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(140.dp)
                        .clip(RoundedCornerShape(16.dp))
                ) {
                    androidx.compose.foundation.Image(
                        painter = rememberAsyncImagePainter(R.drawable.img_bible_timeline_chart_1785156647206),
                        contentDescription = "Bible Timeline & Maps Banner",
                        modifier = Modifier.fillMaxSize(),
                        contentScale = ContentScale.Crop
                    )
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .background(
                                Brush.verticalGradient(
                                    colors = listOf(Color.Transparent, MaterialTheme.colorScheme.surface.copy(alpha = 0.85f))
                                )
                            )
                    )
                }

                Spacer(modifier = Modifier.height(10.dp))

                Text(
                    text = "Biblical Study Suite 📚",
                    style = MaterialTheme.typography.headlineMedium,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.primary
                )
                Text(
                    text = "Equip your study with outlines, timelines, and linguistic dictionaries.",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.7f)
                )
            }

            // 1. Book Overviews (Blue/Indigo)
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { viewModel.selectStudySection(0) }
                    .testTag("hub_card_book_overviews"),
                shape = RoundedCornerShape(20.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.85f)),
                elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
            ) {
                Row(modifier = Modifier.padding(20.dp), verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .size(56.dp)
                            .clip(CircleShape)
                            .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(Icons.AutoMirrored.Filled.MenuBook, null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(30.dp))
                    }
                    Spacer(modifier = Modifier.width(18.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text("Book Overviews & Outlines", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onPrimaryContainer)
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("Analyze categories, historical background, themes, key verses, lessons, and major scenes.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f))
                    }
                }
            }

            // 2. Timeline Map (Purple/Amethyst)
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { viewModel.selectStudySection(1) }
                    .testTag("hub_card_timeline"),
                shape = RoundedCornerShape(20.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.tertiaryContainer.copy(alpha = 0.85f)),
                elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
            ) {
                Row(modifier = Modifier.padding(20.dp), verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .size(56.dp)
                            .clip(CircleShape)
                            .background(MaterialTheme.colorScheme.tertiary.copy(alpha = 0.15f)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(Icons.Default.Timeline, null, tint = MaterialTheme.colorScheme.tertiary, modifier = Modifier.size(30.dp))
                    }
                    Spacer(modifier = Modifier.width(18.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text("Chronological Timeline Map", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onTertiaryContainer)
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("Trace redemptive history sequentially from Creation to the Early Church on an interactive canvas.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onTertiaryContainer.copy(alpha = 0.8f))
                    }
                }
            }

            // 3. Concordance (Secondary/Emerald Green)
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { viewModel.selectStudySection(2) }
                    .testTag("hub_card_concordance"),
                shape = RoundedCornerShape(20.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.85f)),
                elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
            ) {
                Row(modifier = Modifier.padding(20.dp), verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .size(56.dp)
                            .clip(CircleShape)
                            .background(MaterialTheme.colorScheme.secondary.copy(alpha = 0.15f)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(Icons.Default.Search, null, tint = MaterialTheme.colorScheme.secondary, modifier = Modifier.size(30.dp))
                    }
                    Spacer(modifier = Modifier.width(18.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text("Linguistic Concordance", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSecondaryContainer)
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("Perform word studies. Unpack Greek and Hebrew dictionary entries, Strong's numbering, counts, and verse mentions.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSecondaryContainer.copy(alpha = 0.8f))
                    }
                }
            }

            // 4. Commonly Asked Questions & Verses (Primary/Aura)
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { viewModel.selectStudySection(3) }
                    .testTag("hub_card_faq_verses"),
                shape = RoundedCornerShape(20.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.85f)),
                elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
            ) {
                Row(modifier = Modifier.padding(20.dp), verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .size(56.dp)
                            .clip(CircleShape)
                            .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(Icons.Default.Help, null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(30.dp))
                    }
                    Spacer(modifier = Modifier.width(18.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text("FAQ & Key Scriptures", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onPrimaryContainer)
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("Explore answers to common questions about faith, the Bible, and Christian life, with direct scripture links.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f))
                    }
                }
            }
        }
    } else {
        // FULL PAGE MODE WITH COLORFUL TABS
        Column(modifier = Modifier.fillMaxSize()) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 8.dp, vertical = 6.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(onClick = { viewModel.selectStudySection(-1) }) {
                    Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back to Study Hub")
                }
                Spacer(modifier = Modifier.width(4.dp))
                
                ScrollableTabRow(
                    selectedTabIndex = selectedSection,
                    containerColor = Color.Transparent,
                    edgePadding = 0.dp,
                    indicator = {},
                    divider = {},
                    modifier = Modifier.weight(1f)
                ) {
                    val colors = listOf(
                        MaterialTheme.colorScheme.primary,
                        MaterialTheme.colorScheme.tertiary,
                        MaterialTheme.colorScheme.secondary,
                        MaterialTheme.colorScheme.primary
                    )
                    val bgColors = listOf(
                        MaterialTheme.colorScheme.primaryContainer,
                        MaterialTheme.colorScheme.tertiaryContainer,
                        MaterialTheme.colorScheme.secondaryContainer,
                        MaterialTheme.colorScheme.primaryContainer
                    )
                    listOf("Overviews 📖", "Timeline ⏳", "Concordance 🔍", "Q&A & Verses ❓").forEachIndexed { index, title ->
                        val isTabSelected = selectedSection == index
                        Tab(
                            selected = isTabSelected,
                            onClick = { viewModel.selectStudySection(index) },
                            modifier = Modifier
                                .padding(horizontal = 4.dp, vertical = 4.dp)
                                .clip(RoundedCornerShape(24.dp))
                                .background(if (isTabSelected) bgColors[index] else Color.Transparent)
                                .border(1.dp, if (isTabSelected) colors[index] else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f), RoundedCornerShape(24.dp)),
                            text = {
                                Text(
                                    text = title,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isTabSelected) colors[index] else MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        )
                    }
                }
            }
            
            HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))

            if (selectedSection == 2) {
                // Interactive Concordance
                val letterWordsMap = mapOf(
                    'A' to listOf("Altar", "Angel", "Anointing", "Apostle", "Atonement", "Ark", "Abba", "Adopted"),
                    'B' to listOf("Baptism", "Belief", "Blessing", "Blood", "Body", "Bread", "Bridegroom", "Born Again"),
                    'C' to listOf("Covenant", "Creation", "Christ", "Cross", "Compassion", "Church", "Commandment", "Confession"),
                    'D' to listOf("Disciple", "Deuteronomy", "David", "Deliverance", "Devotion", "Doctrine", "Dominion", "Dust"),
                    'E' to listOf("Eternal", "Exile", "Exodus", "Elders", "Election", "Eden", "Emmanuel", "Epistle"),
                    'F' to listOf("Faith", "Father", "Forgiveness", "Flesh", "Fellowship", "Fear of the Lord", "Fruit of the Spirit", "Firstborn"),
                    'G' to listOf("Grace", "Glory", "God", "Gospel", "Gentiles", "Gifts", "Generosity", "Goodness"),
                    'H' to listOf("Hope", "Holiness", "Heart", "Heaven", "Holy", "Heir", "Humility", "Hallelujah"),
                    'I' to listOf("Israel", "Iniquity", "Inheritance", "Incarnation", "Image", "Intercession", "Immanuel", "Isaac"),
                    'J' to listOf("Jesus", "Joy", "Justice", "Judgement", "Justification", "Jerusalem", "John", "Judah"),
                    'K' to listOf("Kingdom", "King", "Kindness", "Knowledge", "Kinsman", "Kadosh", "Keys"),
                    'L' to listOf("Love", "Law", "Light", "Life", "Lord", "Lamb", "Liturgy", "Lineage"),
                    'M' to listOf("Mercy", "Messiah", "Miracle", "Mediator", "Manna", "Manger", "Ministry", "Mystery"),
                    'N' to listOf("Name", "Nation", "Neighbor", "Nazarene", "New", "Noah", "New Covenant", "New Birth"),
                    'O' to listOf("Obedience", "Offering", "Oil", "Overcomer", "Ordinance", "Omega", "Olive Tree", "Omnipotent"),
                    'P' to listOf("Peace", "Prayer", "Prophet", "Priest", "Promise", "Passover", "Praise", "Patience"),
                    'Q' to listOf("Queen", "Quench", "Quietness", "Quiver", "Quickened", "Questions"),
                    'R' to listOf("Righteousness", "Redemption", "Resurrection", "Repentance", "Reconciliation", "Revelation", "Reign", "Rest"),
                    'S' to listOf("Salvation", "Spirit", "Saviour", "Sin", "Sanctification", "Shepherd", "Scripture", "Sacrifice"),
                    'T' to listOf("Trust", "Truth", "Temple", "Tabernacle", "Testimony", "Tithes", "Trinity", "Throne"),
                    'U' to listOf("Understanding", "Unity", "Unbelief", "Unleavened", "Unfeigned", "Unconditional"),
                    'V' to listOf("Victory", "Vineyard", "Virgin", "Vessel", "Vision", "Vow", "Voice"),
                    'W' to listOf("Wisdom", "Word", "Worship", "Wrath", "Witness", "Water", "Way", "Will"),
                    'X' to listOf("Xerxes", "Exodus", "Exile", "Exceptional"),
                    'Y' to listOf("Yahweh", "Yoke", "Year", "Youth", "Yesterday", "Yield"),
                    'Z' to listOf("Zion", "Zeal", "Zionist", "Zechariah", "Zacchaeus", "Zerubbabel")
                )

                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(16.dp)
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    if (activeConcordanceView == "lander") {
                        // LANDER VIEW: Search Bar & Alphabet Grid
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                                Text(
                                    text = "Search Linguistic Concordance",
                                    style = MaterialTheme.typography.titleMedium,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.secondary
                                )
                                
                                OutlinedTextField(
                                    value = concordanceSearchQuery,
                                    onValueChange = { viewModel.updateConcordanceSearchQuery(it) },
                                    placeholder = { Text("Search word (e.g. Grace, Peace, Heart...)") },
                                    leadingIcon = { Icon(Icons.Default.Search, null) },
                                    singleLine = true,
                                    modifier = Modifier.fillMaxWidth(),
                                    keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                        imeAction = androidx.compose.ui.text.input.ImeAction.Search
                                    ),
                                    keyboardActions = androidx.compose.foundation.text.KeyboardActions(
                                        onSearch = {
                                            if (concordanceSearchQuery.isNotBlank()) {
                                                viewModel.selectConcordanceWord(concordanceSearchQuery)
                                                activeConcordanceView = "study_profile"
                                            }
                                        }
                                    ),
                                    trailingIcon = {
                                        if (concordanceSearchQuery.isNotBlank()) {
                                            IconButton(onClick = { viewModel.updateConcordanceSearchQuery("") }) {
                                                Icon(Icons.Default.Clear, null)
                                            }
                                        }
                                    }
                                )
                                
                                Text("Popular Keywords:", style = MaterialTheme.typography.bodySmall, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                androidx.compose.foundation.layout.FlowRow(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                    verticalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    listOf("Faith", "Love", "Grace", "Peace", "Hope", "Mercy", "Covenant", "Wisdom", "Glory", "Righteousness").forEach { keyword ->
                                        SuggestionChip(
                                            onClick = {
                                                viewModel.updateConcordanceSearchQuery(keyword)
                                                viewModel.selectConcordanceWord(keyword)
                                                activeConcordanceView = "study_profile"
                                            },
                                            label = { Text(keyword, fontSize = 11.sp, fontWeight = FontWeight.Bold) },
                                            colors = SuggestionChipDefaults.suggestionChipColors(
                                                containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                                                labelColor = MaterialTheme.colorScheme.onSurfaceVariant
                                            )
                                        )
                                    }
                                }
                            }
                        }

                        // THE ALPHABETS MATRIX
                        Text(
                            text = "Browse Alphabetically",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.secondary,
                            modifier = Modifier.padding(top = 8.dp)
                        )
                        
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
                        ) {
                            Column(
                                modifier = Modifier.padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                Text(
                                    text = "Select a letter to explore all related words in the concordance database",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                
                                val alphabetList = ('A'..'Z').toList()
                                val chunkSize = 7
                                val rows = alphabetList.chunked(chunkSize)
                                
                                Column(
                                    verticalArrangement = Arrangement.spacedBy(8.dp),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    rows.forEach { rowLetters ->
                                        Row(
                                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            rowLetters.forEach { letter ->
                                                var isHovered by remember { mutableStateOf(false) }
                                                val isSelected = selectedLetter == letter
                                                val showGlow = isHovered || isSelected

                                                Box(
                                                    modifier = Modifier
                                                        .weight(1f)
                                                        .aspectRatio(1f)
                                                        .shadow(
                                                            elevation = if (showGlow) 8.dp else 0.dp,
                                                            shape = RoundedCornerShape(12.dp),
                                                            ambientColor = Color(0xFFE53935),
                                                            spotColor = Color(0xFFE53935)
                                                        )
                                                        .clip(RoundedCornerShape(12.dp))
                                                        .background(
                                                            if (showGlow) Color(0xFFFFEBEE).copy(alpha = 0.5f)
                                                            else MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.35f)
                                                        )
                                                        .border(
                                                            width = if (showGlow) 2.dp else 1.dp,
                                                            color = if (showGlow) Color(0xFFE53935) else Color.Transparent,
                                                            shape = RoundedCornerShape(12.dp)
                                                        )
                                                        .pointerInput(Unit) {
                                                            awaitPointerEventScope {
                                                                while (true) {
                                                                    val event = awaitPointerEvent()
                                                                    when (event.type) {
                                                                        PointerEventType.Enter -> isHovered = true
                                                                        PointerEventType.Exit -> isHovered = false
                                                                    }
                                                                }
                                                            }
                                                        }
                                                        .clickable {
                                                            selectedLetter = letter
                                                            activeConcordanceView = "letter_words"
                                                        },
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    Text(
                                                        text = letter.toString(),
                                                        style = MaterialTheme.typography.titleMedium,
                                                        fontWeight = FontWeight.Bold,
                                                        color = if (showGlow) Color(0xFFC62828) else MaterialTheme.colorScheme.primary
                                                    )
                                                }
                                            }
                                            if (rowLetters.size < chunkSize) {
                                                repeat(chunkSize - rowLetters.size) {
                                                    Spacer(modifier = Modifier.weight(1f))
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                    } else if (activeConcordanceView == "letter_words") {
                        // WORDS STARTING WITH THE SELECTED LETTER
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            IconButton(onClick = {
                                selectedLetter = null
                                activeConcordanceView = "lander"
                            }) {
                                Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                            }
                            Text(
                                text = "Words starting with '${selectedLetter}'",
                                style = MaterialTheme.typography.titleLarge,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.secondary
                            )
                        }

                        val words = letterWordsMap[selectedLetter] ?: emptyList()
                        if (words.isEmpty()) {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
                            ) {
                                Box(modifier = Modifier.padding(24.dp).fillMaxWidth(), contentAlignment = Alignment.Center) {
                                    Text("No words available for this letter yet.")
                                }
                            }
                        } else {
                            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                words.forEach { word ->
                                    var isHovered by remember { mutableStateOf(false) }
                                    val showGlow = isHovered

                                    Card(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .shadow(
                                                elevation = if (showGlow) 6.dp else 0.dp,
                                                shape = RoundedCornerShape(12.dp),
                                                ambientColor = Color(0xFFE53935),
                                                spotColor = Color(0xFFE53935)
                                            )
                                            .pointerInput(Unit) {
                                                awaitPointerEventScope {
                                                    while (true) {
                                                        val event = awaitPointerEvent()
                                                        when (event.type) {
                                                            PointerEventType.Enter -> isHovered = true
                                                            PointerEventType.Exit -> isHovered = false
                                                        }
                                                    }
                                                }
                                            }
                                            .clickable {
                                                viewModel.updateConcordanceSearchQuery(word)
                                                viewModel.selectConcordanceWord(word)
                                                activeConcordanceView = "study_profile"
                                            },
                                        colors = CardDefaults.cardColors(
                                            containerColor = if (showGlow) Color(0xFFFFEBEE).copy(alpha = 0.5f) else MaterialTheme.colorScheme.surface
                                        ),
                                        border = BorderStroke(
                                            width = if (showGlow) 2.dp else 1.dp,
                                            color = if (showGlow) Color(0xFFE53935) else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)
                                        ),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(16.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(12.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.AutoMirrored.Filled.MenuBook,
                                                    contentDescription = null,
                                                    tint = if (showGlow) Color(0xFFC62828) else MaterialTheme.colorScheme.secondary,
                                                    modifier = Modifier.size(18.dp)
                                                )
                                                Text(
                                                    text = word,
                                                    style = MaterialTheme.typography.bodyLarge,
                                                    fontWeight = FontWeight.Bold,
                                                    color = if (showGlow) Color(0xFFB71C1C) else MaterialTheme.colorScheme.onSurface
                                                )
                                            }
                                            Icon(
                                                imageVector = Icons.AutoMirrored.Filled.ArrowForward,
                                                contentDescription = null,
                                                tint = if (showGlow) Color(0xFFC62828) else MaterialTheme.colorScheme.outline,
                                                modifier = Modifier.size(16.dp)
                                            )
                                        }
                                    }
                                }
                            }
                        }

                    } else {
                        // STUDY PROFILE VIEW
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            IconButton(onClick = {
                                if (selectedLetter != null) {
                                    activeConcordanceView = "letter_words"
                                } else {
                                    activeConcordanceView = "lander"
                                }
                            }) {
                                Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                            }
                            Text(
                                text = "Linguistic Word Study",
                                style = MaterialTheme.typography.titleLarge,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.secondary
                            )
                        }

                        if (concordanceLoading) {
                            Card(
                                modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                            ) {
                                Column(
                                    modifier = Modifier.fillMaxWidth().padding(24.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.Center
                                ) {
                                    CircularProgressIndicator(color = MaterialTheme.colorScheme.secondary)
                                    Spacer(modifier = Modifier.height(16.dp))
                                    Text(
                                        "Generating linguistic study profile...",
                                        fontWeight = FontWeight.Bold,
                                        style = MaterialTheme.typography.bodyMedium
                                    )
                                    Text(
                                        "Using server-side Gemini AI for deep-dive scholarship.",
                                        style = MaterialTheme.typography.bodySmall,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                                        modifier = Modifier.padding(top = 4.dp)
                                    )
                                }
                            }
                        } else if (concordanceError != null) {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.4f)),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.error)
                            ) {
                                Column(
                                    modifier = Modifier.padding(16.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    Icon(Icons.Default.Error, null, tint = MaterialTheme.colorScheme.error, modifier = Modifier.size(36.dp))
                                    Text("No Predefined Profile Found", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onErrorContainer)
                                    Text(concordanceError!!, textAlign = TextAlign.Center, fontSize = 12.sp, color = MaterialTheme.colorScheme.onErrorContainer)
                                    
                                    Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                                        Button(
                                            onClick = {
                                                if (concordanceSearchQuery.isNotBlank()) {
                                                    viewModel.searchConcordanceWordViaGemini(concordanceSearchQuery)
                                                }
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.error)
                                        ) {
                                            Text("Retry with AI")
                                        }
                                        OutlinedButton(
                                            onClick = {
                                                if (selectedLetter != null) {
                                                    activeConcordanceView = "letter_words"
                                                } else {
                                                    activeConcordanceView = "lander"
                                                }
                                            }
                                        ) {
                                            Text("Back")
                                        }
                                    }
                                }
                            }
                        } else {
                            val entry = selectedConcordanceEntry
                            
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.5f)),
                                shape = RoundedCornerShape(16.dp)
                            ) {
                                Column(modifier = Modifier.padding(16.dp)) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Text(
                                            text = entry.word,
                                            style = MaterialTheme.typography.headlineMedium,
                                            fontWeight = FontWeight.ExtraBold,
                                            color = MaterialTheme.colorScheme.onSecondaryContainer
                                        )
                                        Spacer(modifier = Modifier.width(12.dp))
                                        Text(
                                            text = entry.partOfSpeech,
                                            fontStyle = FontStyle.Italic,
                                            style = MaterialTheme.typography.titleMedium,
                                            color = MaterialTheme.colorScheme.onSecondaryContainer.copy(alpha = 0.7f)
                                        )
                                    }
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Text(
                                        text = entry.meaning,
                                        style = MaterialTheme.typography.bodyLarge,
                                        fontWeight = FontWeight.Medium,
                                        color = MaterialTheme.colorScheme.onSecondaryContainer
                                    )
                                }
                            }

                            Text("Original Language Study Profile", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.secondary)
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                shape = RoundedCornerShape(16.dp),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                            ) {
                                Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text("Greek/Hebrew Word", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                            Text(entry.greekWord.ifBlank { "N/A" }, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                        }
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text("Transliteration", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                            Text(entry.transliteration.ifBlank { "N/A" }, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
                                        }
                                    }
                                    
                                    HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))
                                    
                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text("Strong's Number", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                            Text(entry.strongsNumber.ifBlank { "N/A" }, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.tertiary)
                                        }
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text("Scripture Mentions", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                            Text(if (entry.usedCount > 0) "${entry.usedCount} times" else "Multiple", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
                                        }
                                    }

