                                }
                            }
                        }
                    }
                }

                if (activeReadingVerseRef != null) {
                    ConcordanceVersePopup(
                        ref = activeReadingVerseRef!!,
                        viewModel = viewModel,
                        onDismiss = { activeReadingVerseRef = null }
