                                        } else {
                                            "Lessons: " + selectedOverview.lessons
                                        }
                                        val speakTextForStudy = "Book of ${selectedOverview.name}. Category: ${selectedOverview.category}. Author: ${selectedOverview.author}. Date Written: ${selectedOverview.dateWritten}. Key Theme: ${selectedOverview.theme}. Key Scripture: ${selectedOverview.keyVerse}. $charactersStr. $lessonsStr. Summary: ${selectedOverview.summary}."
                                        speakText(speakTextForStudy, studyOverviewTitle)
                                    }
                                },
                                label = {
                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                        Icon(
