                            Column(modifier = Modifier.padding(12.dp)) {
                                Text("KEY VERSE", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = selectedOverview.keyVerse,
                                    fontStyle = FontStyle.Italic,
                                    fontFamily = FontFamily.Serif,
                                    fontSize = 14.sp
                                )
                            }
                        }

                        // NEW: Key Characters Section
                        if (selectedOverview.keyCharacters.isNotEmpty() || selectedOverview.characters.isNotEmpty()) {
                            Spacer(modifier = Modifier.height(16.dp))
