            } else {
                itemsIndexed(filteredEvents) { index, event ->
                    var isAnimated by remember { mutableStateOf(false) }
                    LaunchedEffect(Unit) {
                        isAnimated = true
                    }
                    AnimatedVisibility(
                        visible = isAnimated,
                        enter = fadeIn(animationSpec = tween(durationMillis = 600, delayMillis = index * 80)) +
                                slideInVertically(initialOffsetY = { 40 }, animationSpec = tween(durationMillis = 600, delayMillis = index * 80)),
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 4.dp)
                    ) {
                        val themeColor = if (index % 2 == 0) MaterialTheme.colorScheme.tertiary else MaterialTheme.colorScheme.primary
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.Top
                        ) {
                            // Left Axis: Bullet Indicator & Connecting Line
                            Column(
                                modifier = Modifier
                                    .padding(end = 12.dp)
                                    .width(20.dp),
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                Box(
                                    modifier = Modifier
                                        .padding(top = 16.dp)
                                        .size(14.dp)
                                        .clip(CircleShape)
                                        .background(themeColor)
                                        .border(2.dp, MaterialTheme.colorScheme.background, CircleShape)
                                )
                                Box(
                                    modifier = Modifier
                                        .width(2.dp)
                                        .height(115.dp)
                                        .background(themeColor.copy(alpha = 0.25f))
                                )
                            }

                            // Right: Full Width Event Card
                            Card(
                                modifier = Modifier
                                    .weight(1f)
                                    .testTag("timeline_card_${index}"),
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(
                                    containerColor = if (selectedPlottedEvent == event) themeColor.copy(alpha = 0.05f) else MaterialTheme.colorScheme.surface
                                ),
                                elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                                border = BorderStroke(
                                    width = if (selectedPlottedEvent == event) 1.5.dp else 1.dp,
                                    color = if (selectedPlottedEvent == event) themeColor else themeColor.copy(alpha = 0.15f)
                                )
                            ) {
                                Column(modifier = Modifier.padding(14.dp)) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(28.dp)
                                                    .clip(CircleShape)
                                                    .background(themeColor.copy(alpha = 0.1f)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Icon(
                                                    imageVector = getTimelineIcon(event.iconName),
                                                    contentDescription = null,
                                                    tint = themeColor,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text(
                                                text = event.title,
                                                fontWeight = FontWeight.Bold,
                                                style = MaterialTheme.typography.titleMedium,
                                                color = MaterialTheme.colorScheme.onSurface
                                            )
                                        }
                                        
                                        Surface(
                                            color = themeColor.copy(alpha = 0.08f),
                                            shape = RoundedCornerShape(8.dp),
                                            modifier = Modifier.padding(start = 4.dp)
                                        ) {
                                            Text(
                                                text = event.period,
                                                fontWeight = FontWeight.Bold,
                                                style = MaterialTheme.typography.labelSmall,
                                                color = themeColor,
                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                            )
                                        }
                                    }
                                    
                                    Spacer(modifier = Modifier.height(6.dp))
                                    Text(
                                        text = event.description,
                                        style = MaterialTheme.typography.bodyMedium,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.85f),
                                        lineHeight = 20.sp
                                    )
                                    
                                    Spacer(modifier = Modifier.height(10.dp))
                                    Surface(
                                        shape = RoundedCornerShape(8.dp),
                                        color = themeColor.copy(alpha = 0.12f),
                                        modifier = Modifier.clickable {
                                            val (book, chapter) = parseScriptureRef(event.scriptureRef)
                                            viewModel.selectBook(book)
                                            viewModel.selectChapter(chapter)
                                            viewModel.setReadStep(BibleViewModel.ReadStep.VERSE_READ)
                                            viewModel.navigateTo(Screen.READ)
                                        }
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.MenuBook,
                                                contentDescription = null,
                                                modifier = Modifier.size(14.dp),
                                                tint = themeColor
                                            )
                                            Spacer(modifier = Modifier.width(6.dp))
                                            Text(
                                                text = event.scriptureRef,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = themeColor
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
}
}
}

// -----------------------------------------------------------------
// 5. LIBRARY, STUDY OVERVIEWS, & SETTINGS SCREEN
// -----------------------------------------------------------------
@Composable
fun LibraryScreen(
    viewModel: BibleViewModel,
    confirmDeletion: (String, String, () -> Unit) -> Unit = { _, _, onConfirm -> onConfirm() }
) {
    val favorites by viewModel.favoriteVerses.collectAsStateWithLifecycle()
    val history by viewModel.readingHistoryList.collectAsStateWithLifecycle()
    val availableBooks by viewModel.availableBooks.collectAsStateWithLifecycle()
    val selectedOverviewBook by viewModel.selectedOverviewBook.collectAsStateWithLifecycle()
    val selectedOverview by viewModel.selectedBookOverview.collectAsStateWithLifecycle()
    val isDarkMode by viewModel.isDarkMode.collectAsStateWithLifecycle()

    var activeSubTab by remember { mutableStateOf(0) } // 0 = Overviews, 1 = Highlights, 2 = History, 3 = Settings
    var showOverviewBookDropdown by remember { mutableStateOf(false) }

    Column(modifier = Modifier.fillMaxSize().padding(16.dp)) {
        // Horizontal Scrollable Scrollable Sub-Tabs
        ScrollableTabRow(
            selectedTabIndex = activeSubTab,
            containerColor = Color.Transparent,
            edgePadding = 0.dp,
            modifier = Modifier.fillMaxWidth().padding(bottom = 16.dp)
        ) {
            Tab(selected = activeSubTab == 0, onClick = { activeSubTab = 0 }) {
                Text("Book Overviews", modifier = Modifier.padding(vertical = 12.dp), fontWeight = FontWeight.Bold)
            }
            Tab(selected = activeSubTab == 1, onClick = { activeSubTab = 1 }) {
                Text("Highlights (${favorites.size})", modifier = Modifier.padding(vertical = 12.dp), fontWeight = FontWeight.Bold)
            }
            Tab(selected = activeSubTab == 2, onClick = { activeSubTab = 2 }) {
                Text("Reading History", modifier = Modifier.padding(vertical = 12.dp), fontWeight = FontWeight.Bold)
            }
            Tab(selected = activeSubTab == 3, onClick = { activeSubTab = 3 }) {
                Text("Theme Settings", modifier = Modifier.padding(vertical = 12.dp), fontWeight = FontWeight.Bold)
            }
        }

        when (activeSubTab) {
            0 -> {
                // Book Overviews Study Pane
                LazyColumn(
                    modifier = Modifier.fillMaxSize().weight(1f),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    item {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                        ) {
                            Row(
                                modifier = Modifier.padding(14.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text("Select Bible Book to Study:", fontWeight = FontWeight.Bold)
                                
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    IconButton(
                                        onClick = { viewModel.navigateTo(Screen.BOOK_OVERVIEW) },
                                        modifier = Modifier.testTag("open_full_book_overview_screen_btn")
                                    ) {
                                        Icon(Icons.Default.OpenInNew, "Full Screen Overview", tint = MaterialTheme.colorScheme.primary)
                                    }

                                    Box {
                                        AssistChip(
                                            onClick = { showOverviewBookDropdown = true },
                                            label = { Text(selectedOverviewBook, fontWeight = FontWeight.Bold) },
                                            trailingIcon = { Icon(Icons.Default.ArrowDropDown, null) }
                                        )
                                        DropdownMenu(
                                            expanded = showOverviewBookDropdown,
                                            onDismissRequest = { showOverviewBookDropdown = false }
                                        ) {
                                            availableBooks.forEach { book ->
                                                DropdownMenuItem(
                                                    text = { Text(book) },
                                                    onClick = {
                                                        viewModel.selectOverviewBook(book)
                                                        showOverviewBookDropdown = false
                                                    }
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    item {
                        Card(
                            shape = RoundedCornerShape(16.dp),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(18.dp)) {
                                Text(
                                    text = selectedOverview.name,
                                    style = MaterialTheme.typography.headlineMedium,
                                    fontFamily = FontFamily.Serif,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                
                                Row(
                                    modifier = Modifier.padding(vertical = 4.dp),
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    SuggestionChip(onClick = {}, label = { Text(selectedOverview.category) })
                                    SuggestionChip(onClick = {}, label = { Text("Author: ${selectedOverview.author}") })
                                }

                                Spacer(modifier = Modifier.height(12.dp))

                                RowValue(label = "Date Written", value = selectedOverview.dateWritten)
                                RowValue(label = "Key Theme", value = selectedOverview.theme)
                                
                                Spacer(modifier = Modifier.height(14.dp))

                                // Key Verse Card
                                Card(
                                    shape = RoundedCornerShape(8.dp),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Column(modifier = Modifier.padding(12.dp)) {
                                        Text("KEY VERSE", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = selectedOverview.keyVerse,
                                            fontStyle = FontStyle.Italic,
                                            fontFamily = FontFamily.Serif,
                                            fontSize = 14.sp
                                        )
                                    }
                                }

                                Spacer(modifier = Modifier.height(16.dp))

                                Text("Book Overview Summary", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.titleMedium)
                                Spacer(modifier = Modifier.height(6.dp))
                                Text(
                                    text = formatDocumentText(selectedOverview.summary),
                                    fontSize = 15.sp,
                                    lineHeight = 22.sp
                                )
                            }
                        }
                    }
                }
            }

            1 -> {
                // Favorites / Highlighting List
                if (favorites.isEmpty()) {
                    Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Icon(Icons.Default.StarOutline, null, modifier = Modifier.size(64.dp), tint = MaterialTheme.colorScheme.primary.copy(alpha = 0.4f))
                            Spacer(modifier = Modifier.height(12.dp))
                            Text("No highlights saved yet.", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.5f))
                            Text("Tap any verse in the reader to highlight it!", fontSize = 13.sp, color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.5f))
                        }
                    }
                } else {
                    LazyColumn(
                        modifier = Modifier.fillMaxSize().weight(1f),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        items(favorites) { fav ->
                            val favColor = Color(android.graphics.Color.parseColor(fav.colorHex))
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        // Jump to Reader
                                        viewModel.selectTranslation(fav.translation)
                                        viewModel.selectBook(fav.bookName)
                                        viewModel.selectChapter(fav.chapter)
                                        viewModel.navigateTo(Screen.READ)
                                    },
                                colors = CardDefaults.cardColors(containerColor = favColor)
                            ) {
                                Column(modifier = Modifier.padding(12.dp)) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(
                                            text = "${fav.bookName} ${fav.chapter}:${fav.verseNumber} (${fav.translation})",
                                            fontWeight = FontWeight.Bold,
                                            color = MaterialTheme.colorScheme.onBackground
                                        )
                                        IconButton(
                                            onClick = {
                                                confirmDeletion(
                                                    "Delete Highlighted Passage",
                                                    "Are you sure you want to delete the highlight on ${fav.bookName} ${fav.chapter}:${fav.verseNumber}?"
                                                ) {
                                                    viewModel.removeFavoriteHighlight(fav)
                                                }
                                            }
                                        ) {
                                            Icon(Icons.Default.Delete, contentDescription = "Delete Highlight", tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.7f))
                                        }
                                    }
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = fav.text,
                                        fontFamily = FontFamily.Serif,
                                        fontSize = 15.sp,
                                        lineHeight = 22.sp,
                                        color = MaterialTheme.colorScheme.onBackground
                                    )
                                }
                            }
                        }
                    }
                }
            }

            2 -> {
                // Reading History Log
                if (history.isEmpty()) {
                    Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                        Text("No chapters read in this session yet.", color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.5f))
                    }
                } else {
                    Column(modifier = Modifier.fillMaxSize()) {
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(bottom = 8.dp),
                            horizontalArrangement = Arrangement.End
                        ) {
                            TextButton(onClick = { viewModel.clearAllHistory() }) {
                                Icon(Icons.Default.Delete, null)
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Clear History")
                            }
                        }

                        LazyColumn(
                            modifier = Modifier.fillMaxSize().weight(1f),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            items(history) { log ->
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable {
                                            viewModel.selectBook(log.bookName)
                                            viewModel.selectChapter(log.chapter)
                                            viewModel.navigateTo(Screen.READ)
                                        },
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                                ) {
                                    Row(
                                        modifier = Modifier.padding(14.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Icon(Icons.Default.History, null, tint = MaterialTheme.colorScheme.primary)
                                            Spacer(modifier = Modifier.width(12.dp))
                                            Text(
                                                text = "Opened ${log.bookName} Chapter ${log.chapter}",
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                        Icon(Icons.Default.ChevronRight, null, tint = MaterialTheme.colorScheme.primary)
                                    }
                                }
                            }
                        }
                    }
                }
            }

            3 -> {
                // Settings, User Credentials, Theme, and Downloads
                val userNameState by viewModel.userName.collectAsStateWithLifecycle()
                val userEmailState by viewModel.userEmail.collectAsStateWithLifecycle()
                val userCredentialsState by viewModel.userCredentials.collectAsStateWithLifecycle()
                val themePreferenceState by viewModel.themePreference.collectAsStateWithLifecycle()
                
                val downloadedState by viewModel.downloadedVersions.collectAsStateWithLifecycle()
                val downloadProgressState by viewModel.downloadProgress.collectAsStateWithLifecycle()
                
                var nameInput by remember { mutableStateOf(userNameState) }
                var credentialsInput by remember { mutableStateOf(userCredentialsState) }
                var emailInput by remember { mutableStateOf(userEmailState) }

                // Keep inputs in sync if they change in viewModel
                LaunchedEffect(userNameState, userCredentialsState, userEmailState) {
                    nameInput = userNameState
                    credentialsInput = userCredentialsState
                    emailInput = userEmailState
                }

                val context = LocalContext.current

                LazyColumn(
                    modifier = Modifier.fillMaxSize().padding(horizontal = 4.dp),
                    verticalArrangement = Arrangement.spacedBy(16.dp),
                    contentPadding = PaddingValues(bottom = 24.dp)
                ) {
                    // 1. Profile settings
                    item {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            shape = RoundedCornerShape(16.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(Icons.Default.AccountCircle, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(24.dp))
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text("User Profile & Credentials", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                }
                                
                                Spacer(modifier = Modifier.height(12.dp))
                                
                                // Profile Picture Section
                                val userProfilePicState by viewModel.userProfilePic.collectAsStateWithLifecycle()
                                var showUrlDialog by remember { mutableStateOf(false) }
                                var webUrlInput by remember { mutableStateOf("") }
                                
                                val imagePickerLauncher = rememberLauncherForActivityResult(
                                    contract = ActivityResultContracts.GetContent()
                                ) { uri: Uri? ->
                                    if (uri != null) {
                                        viewModel.updateUserProfilePic(uri.toString())
                                        Toast.makeText(context, "Profile picture uploaded!", Toast.LENGTH_SHORT).show()
                                    }
                                }

                                Row(
                                    modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(56.dp)
                                            .clip(CircleShape)
                                            .background(MaterialTheme.colorScheme.primaryContainer)
                                            .border(1.5.dp, MaterialTheme.colorScheme.primary, CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        ProfileAvatarImage(
                                            userProfilePicState = userProfilePicState,
                                            placeholderSize = 32.dp
                                        )
                                    }
                                    
                                    Spacer(modifier = Modifier.width(12.dp))
                                    
                                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                        Text("Profile Picture", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodyMedium)
                                        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                            OutlinedButton(
                                                onClick = { imagePickerLauncher.launch("image/*") },
                                                modifier = Modifier.height(32.dp).testTag("upload_pic_device_btn_slide"),
                                                contentPadding = PaddingValues(horizontal = 8.dp, vertical = 2.dp)
                                            ) {
                                                Icon(Icons.Default.PhotoLibrary, contentDescription = null, modifier = Modifier.size(12.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("Device", fontSize = 10.sp)
                                            }
                                            
                                            OutlinedButton(
                                                onClick = { showUrlDialog = true },
                                                modifier = Modifier.height(32.dp).testTag("upload_pic_web_btn_slide"),
                                                contentPadding = PaddingValues(horizontal = 8.dp, vertical = 2.dp)
                                            ) {
                                                Icon(Icons.Default.Language, contentDescription = null, modifier = Modifier.size(12.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("Web Link", fontSize = 10.sp)
                                            }
                                        }
                                    }
                                }

                                if (showUrlDialog) {
                                    AlertDialog(
                                        onDismissRequest = { showUrlDialog = false },
                                        title = { Text("Profile Pic Web URL") },
                                        text = {
                                            Column {
                                                Text("Enter or paste a web image link:", fontSize = 12.sp)
                                                Spacer(modifier = Modifier.height(8.dp))
                                                OutlinedTextField(
                                                     value = webUrlInput,
                                                     onValueChange = { webUrlInput = it },
                                                     placeholder = { Text("https://example.com/avatar.jpg") },
                                                     modifier = Modifier.fillMaxWidth().testTag("web_pic_url_input_slide"),
                                                     singleLine = true
                                                )
                                            }
                                        },
                                        confirmButton = {
                                            Button(
                                                onClick = {
                                                    if (webUrlInput.isNotBlank()) {
                                                        viewModel.updateUserProfilePic(webUrlInput)
                                                        showUrlDialog = false
                                                        webUrlInput = ""
                                                        Toast.makeText(context, "Profile picture set!", Toast.LENGTH_SHORT).show()
                                                    }
                                                },
                                                modifier = Modifier.testTag("save_web_pic_btn_slide")
                                            ) {
                                                Text("Save")
                                            }
                                        },
                                        dismissButton = {
                                            TextButton(onClick = { showUrlDialog = false }) {
                                                Text("Cancel")
                                            }
                                        }
                                    )
                                }

                                Spacer(modifier = Modifier.height(8.dp))

                                OutlinedTextField(
                                    value = nameInput,
                                    onValueChange = { 
                                        nameInput = it 
                                    },
                                    label = { Text("Reader Name") },
                                    modifier = Modifier.fillMaxWidth().testTag("settings_username"),
                                    singleLine = true
                                )
                                
                                Spacer(modifier = Modifier.height(8.dp))
                                
                                OutlinedTextField(
                                    value = emailInput,
                                    onValueChange = { emailInput = it },
                                    label = { Text("Email Address") },
                                    modifier = Modifier.fillMaxWidth().testTag("settings_email"),
                                    singleLine = true
                                )
                                
                                Spacer(modifier = Modifier.height(12.dp))
                                
                                Button(
                                    onClick = {
                                        viewModel.updateUserProfile(nameInput, emailInput, credentialsInput)
                                        Toast.makeText(context, "Profile updated successfully!", Toast.LENGTH_SHORT).show()
                                    },
                                    modifier = Modifier.fillMaxWidth().testTag("settings_save_profile")
                                ) {
                                    Icon(Icons.Default.Save, contentDescription = null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text("Save Credentials")
                                }
                            }
                        }
                    }

                    // 2. Default App Theme Card
                    item {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            shape = RoundedCornerShape(16.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(Icons.Default.Palette, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(24.dp))
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text("Default App Theme", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                }
                                
                                Spacer(modifier = Modifier.height(12.dp))
                                
                                val themeOptions = listOf("System" to "System Default", "Dark" to "Celestial Dark", "Light" to "Warm Parchment")
                                themeOptions.forEach { (value, label) ->
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clickable { viewModel.setThemePreference(value) }
                                            .padding(vertical = 8.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        RadioButton(
                                            selected = themePreferenceState == value,
                                            onClick = { viewModel.setThemePreference(value) },
                                            modifier = Modifier.testTag("theme_radio_$value")
                                        )
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text(label, style = MaterialTheme.typography.bodyLarge)
                                    }
                                }
                            }
                        }
                    }

                    // 3. Downloaded versions manager
                    item {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            shape = RoundedCornerShape(16.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(Icons.Default.Download, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(24.dp))
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text("Downloaded Bible Versions", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                }
                                
                                Spacer(modifier = Modifier.height(12.dp))
                                
                                val allVersionsList = listOf(
                                    Triple("KJV", "King James Version", "1.8 MB"),
                                    Triple("WEB", "World English Bible", "2.1 MB"),
                                    Triple("ASV", "American Standard Version", "1.9 MB"),
                                    Triple("NIV", "New International Version", "2.2 MB"),
                                    Triple("ESV", "English Standard Version", "2.0 MB"),
                                    Triple("NKJV", "New King James Version", "2.1 MB"),
                                    Triple("NLT", "New Living Translation", "2.0 MB"),
                                    Triple("NASB", "New American Standard Bible", "2.3 MB"),
                                    Triple("AMP", "Amplified Bible", "2.5 MB"),
                                    Triple("MSG", "The Message", "1.7 MB")
                                )
                                
                                allVersionsList.forEach { (code, fullName, size) ->
                                    val isDownloaded = downloadedState.contains(code)
                                    val progress = downloadProgressState[code]
                                    
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(vertical = 8.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column(modifier = Modifier.weight(1f)) {
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Text(code, fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodyLarge)
                                                Spacer(modifier = Modifier.width(8.dp))
                                                Text(size, fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f))
                                            }
                                            Text(fullName, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f))
                                            
                                            if (progress != null) {
                                                Spacer(modifier = Modifier.height(4.dp))
                                                LinearProgressIndicator(
                                                    progress = { progress / 100f },
                                                    modifier = Modifier.fillMaxWidth(0.8f).testTag("download_progress_$code"),
                                                    color = MaterialTheme.colorScheme.primary,
                                                    trackColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.2f),
                                                )
                                            }
                                        }
                                        
                                        if (isDownloaded) {
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Icon(Icons.Default.CheckCircle, contentDescription = "Downloaded", tint = GreenTone, modifier = Modifier.size(20.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("Offline Ready", fontSize = 11.sp, color = GreenTone, fontWeight = FontWeight.Bold)
                                            }
                                        } else if (progress != null) {
                                            Text("$progress%", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                        } else {
                                            FilledTonalButton(
                                                onClick = { viewModel.downloadVersion(code) },
                                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp),
                                                modifier = Modifier.height(32.dp).testTag("download_btn_$code")
                                            ) {
                                                Icon(Icons.Default.CloudDownload, contentDescription = null, modifier = Modifier.size(14.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("Download", fontSize = 11.sp)
                                            }
                                        }
                                    }
                                    HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))
                                }
                            }
                        }
                    }

                    // 4. Build specifications
                    item {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant),
                            shape = RoundedCornerShape(16.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Text("System Specification", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                Spacer(modifier = Modifier.height(8.dp))
                                RowValue("App Version", "1.4.2-Release")
                                RowValue("Engine Build", "SQLite Room v2.6.1")
                                RowValue("Schema Hash", "3b6a0dcd")
                                RowValue("AI Model", "Gemini 1.5 Flash REST Server-Side")
                                RowValue("Connectivity", "Dual Mode (Offline/Cloud Hybrid)")
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun formatDocumentText(text: String): androidx.compose.ui.text.AnnotatedString {
    val cleanedText = text.replace(Regex("(?m)^#+\\s+"), "") // strip markdown headings
    
    val parts = cleanedText.split("**")
    return buildAnnotatedString {
        var isBold = false
        parts.forEach { part ->
            if (isBold) {
                pushStyle(
                    SpanStyle(
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary
                    )
                )
                append(part)
                pop()
            } else {
                append(part)
            }
            isBold = !isBold
        }
    }
}

@Composable
fun RowValue(label: String, value: String) {
    Row(
        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)
    ) {
        Text(
            text = "$label: ",
            fontWeight = FontWeight.Bold,
            color = MaterialTheme.colorScheme.primary,
            fontSize = 14.sp,
            modifier = Modifier.width(100.dp)
        )
        Text(
            text = value,
            fontSize = 14.sp,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
    }
}

