                                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)),
                                                    shape = RoundedCornerShape(16.dp),
                                                    border = androidx.compose.foundation.BorderStroke(1.8.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.35f))
                                                ) {
                                                    Column(modifier = Modifier.padding(14.dp).fillMaxSize(), verticalArrangement = Arrangement.SpaceBetween) {
                                                        Column {
                                                            Row(verticalAlignment = androidx.compose.ui.Alignment.CenterVertically) {
