                                                            Text(
                                                                text = "Read Holy Scriptures fully offline. Study multiple versions (KJV, WEB, ASV) side-by-side in parallel mode, bookmark passages, and highlight verses.",
                                                                fontSize = 11.sp,
                                                                lineHeight = 15.sp,
                                                                color = MaterialTheme.colorScheme.onSurfaceVariant
                                                            )
                                                        }
                                                        Button(
                                                            onClick = { 
                                                                viewModel.setReadStep(BibleViewModel.ReadStep.BOOK_SELECT)
                                                                viewModel.navigateTo(Screen.READ) 
                                                            },
                                                            modifier = Modifier.fillMaxWidth().height(36.dp).testTag("slide_read_btn"),
                                                            contentPadding = PaddingValues(vertical = 0.dp),
                                                            shape = RoundedCornerShape(8.dp)
                                                        ) {
                                                            Text("Open Scripture Reader", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                                        }
                                                    }
                                                }
                                            }
