                                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.5f)),
                                                    shape = RoundedCornerShape(16.dp),
                                                    border = androidx.compose.foundation.BorderStroke(1.8.dp, MaterialTheme.colorScheme.secondary.copy(alpha = 0.35f))
                                                ) {
                                                    Column(modifier = Modifier.padding(14.dp).fillMaxSize(), verticalArrangement = Arrangement.SpaceBetween) {
                                                        Column {
                                                            Row(verticalAlignment = androidx.compose.ui.Alignment.CenterVertically) {
                                                                Icon(Icons.Default.History, contentDescription = null, tint = MaterialTheme.colorScheme.secondary, modifier = Modifier.size(18.dp))
                                                                Spacer(modifier = Modifier.width(8.dp))
                                                                Text("Historical Timeline", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.titleSmall, color = MaterialTheme.colorScheme.secondary)
                                                            }
                                                            Spacer(modifier = Modifier.height(6.dp))
