                                            viewModel.updateReminderSettings(context, true, reminderHour, reminderMinute)
                                        } else {
                                            permissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
                                        }
                                    } else {
                                        viewModel.updateReminderSettings(context, true, reminderHour, reminderMinute)
                                    }
                                } else {
