        // 4. Downloaded versions manager -> Upgraded to Translation & Storage Manager
        item {
            if (selectedCategoryTab == 0 || selectedCategoryTab == 3) {
            val storageSizesState by viewModel.translationStorageSizes.collectAsStateWithLifecycle()
            var expandedGroupId by remember { mutableStateOf<String?>("english_versions") }
            
            // Trigger a refresh of sizes when this view is shown
            LaunchedEffect(Unit) {
                viewModel.refreshStorageSizes()
            }

            // Helper function to format storage sizes dynamically
            fun formatStorageBytes(bytes: Long): String {
                val scaledBytes = bytes * 90L // scale factor to represent full Bible size realistically
                return when {
                    scaledBytes >= 1024 * 1024 -> String.format("%.2f MB", scaledBytes / (1024f * 1024f))
                    scaledBytes >= 1024 -> String.format("%.1f KB", scaledBytes / 1024f)
                    else -> "$scaledBytes B"
                }
            }

            // Calculate overall storage stats
            var totalDownloadedBytes = 0L
            var totalAllPossibleBytes = 0L
            groups.forEach { group ->
                group.translations.forEach { trans ->
                    val isDownloaded = downloadedState.contains(trans.code)
                    val rawBytes = if (isDownloaded) (storageSizesState[trans.code] ?: (trans.baseSizeInBytes / 90L)) else 0L
                    totalDownloadedBytes += rawBytes
                    totalAllPossibleBytes += (trans.baseSizeInBytes / 90L) // Normalizing potential bytes so ratio is realistic
                }
            }

            val totalDownloadedStr = formatStorageBytes(totalDownloadedBytes)
            val totalAllPossibleStr = formatStorageBytes(totalAllPossibleBytes)
            val totalStorageRatio = if (totalAllPossibleBytes > 0) totalDownloadedBytes.toFloat() / totalAllPossibleBytes else 0f

            Card(
                modifier = Modifier.fillMaxWidth().testTag("translation_manager_card"),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    // Header Section
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Default.Download,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(24.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "Translation & Storage Manager",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                    }

                    Spacer(modifier = Modifier.height(12.dp))
                    Text(
                        text = "Toggle translations below to download for full offline access, or remove them to free up device space.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                    )
                    
                    Spacer(modifier = Modifier.height(16.dp))

                    // Storage Overview Section
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.25f), RoundedCornerShape(12.dp))
                            .border(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.15f), RoundedCornerShape(12.dp))
                            .padding(12.dp)
                    ) {
                        Column {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "Total Offline Storage",
                                    style = MaterialTheme.typography.bodyMedium,
                                    fontWeight = FontWeight.Bold
                                )
                                Text(
                                    text = "$totalDownloadedStr of $totalAllPossibleStr",
                                    style = MaterialTheme.typography.bodyMedium,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.primary
                                )
                            }
                            Spacer(modifier = Modifier.height(8.dp))
                            LinearProgressIndicator(
                                progress = { totalStorageRatio.coerceIn(0f, 1f) },
                                modifier = Modifier.fillMaxWidth().height(8.dp).clip(CircleShape),
                                color = MaterialTheme.colorScheme.primary,
                                trackColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)
                            )
                            Spacer(modifier = Modifier.height(6.dp))
                            Text(
                                text = "Currently storing ${downloadedState.size} active translations offline.",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                fontSize = 11.sp
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    // Render Language Groups
                    groups.forEach { group ->
                        val isExpanded = expandedGroupId == group.id
                        
                        // Calculate Group Specific Storage
                        var groupDownloadedBytes = 0L
                        var groupTotalBytes = 0L
                        var groupDownloadedCount = 0
                        group.translations.forEach { t ->
                            val isDownloaded = downloadedState.contains(t.code)
                            if (isDownloaded) {
                                groupDownloadedBytes += (storageSizesState[t.code] ?: (t.baseSizeInBytes / 90L))
                                groupDownloadedCount++
                            }
                            groupTotalBytes += (t.baseSizeInBytes / 90L)
                        }
                        val groupRatio = if (groupTotalBytes > 0) groupDownloadedBytes.toFloat() / groupTotalBytes else 0f
                        val groupDownloadedStr = formatStorageBytes(groupDownloadedBytes)

                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp)
                        ) {
                            // Group Header (Clickable for expand/collapse)
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { expandedGroupId = if (isExpanded) null else group.id }
                                    .padding(vertical = 8.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                                    Box(
                                        modifier = Modifier
                                            .size(36.dp)
                                            .clip(RoundedCornerShape(8.dp))
                                            .background(MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.4f)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = group.icon,
                                            contentDescription = null,
                                            tint = MaterialTheme.colorScheme.primary,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Column {
                                        Text(
                                            text = group.name,
                                            fontWeight = FontWeight.Bold,
                                            style = MaterialTheme.typography.bodyLarge
                                        )
                                        Text(
                                            text = "$groupDownloadedCount of ${group.translations.size} ready • $groupDownloadedStr",
                                            style = MaterialTheme.typography.bodySmall,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                        )
                                    }
                                }
                                Icon(
                                    imageVector = if (isExpanded) Icons.Default.ExpandLess else Icons.Default.ExpandMore,
                                    contentDescription = if (isExpanded) "Collapse" else "Expand",
                                    tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                )
                            }

                            // Group-level storage progress bar (always visible below header for quick diagnostic!)
                            LinearProgressIndicator(
                                progress = { groupRatio.coerceIn(0f, 1f) },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(3.dp)
                                    .clip(CircleShape)
                                    .padding(horizontal = 4.dp),
                                color = if (groupDownloadedCount == group.translations.size) GreenTone else MaterialTheme.colorScheme.primary,
                                trackColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.05f)
                            )

                            if (isExpanded) {
                                Spacer(modifier = Modifier.height(8.dp))
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(start = 12.dp, bottom = 8.dp),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Column(modifier = Modifier.padding(12.dp)) {
                                        Text(
                                            text = group.description,
                                            style = MaterialTheme.typography.bodySmall,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f),
                                            modifier = Modifier.padding(bottom = 8.dp)
                                        )
                                        
                                        group.translations.forEachIndexed { index, translation ->
                                            val isDownloaded = downloadedState.contains(translation.code)
                                            val progress = downloadProgressState[translation.code]
                                            val currentRawSize = if (isDownloaded) (storageSizesState[translation.code] ?: (translation.baseSizeInBytes / 90L)) else 0L
                                            val individualSize = formatStorageBytes(if (isDownloaded) currentRawSize else (translation.baseSizeInBytes / 90L))

                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .padding(vertical = 8.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column(
                                                    modifier = Modifier
                                                        .weight(1f)
                                                        .clip(RoundedCornerShape(8.dp))
                                                        .clickable { selectedTranslationForPopup = translation }
                                                        .padding(end = 4.dp)
                                                ) {
                                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                                        Text(
                                                            text = translation.code,
                                                            fontWeight = FontWeight.Bold,
                                                            style = MaterialTheme.typography.bodyMedium
                                                        )
                                                        Spacer(modifier = Modifier.width(4.dp))
                                                        IconButton(
                                                            onClick = { selectedTranslationForPopup = translation },
                                                            modifier = Modifier.size(22.dp).testTag("info_btn_${translation.code}")
                                                        ) {
                                                            Icon(
                                                                imageVector = Icons.Default.Info,
                                                                contentDescription = "Version details",
                                                                tint = MaterialTheme.colorScheme.primary,
                                                                modifier = Modifier.size(16.dp)
                                                            )
                                                        }
                                                        Spacer(modifier = Modifier.width(4.dp))
                                                        if (translation.code.equals(currentSelectedTranslation, ignoreCase = true)) {
                                                            Surface(
                                                                color = MaterialTheme.colorScheme.primaryContainer,
                                                                contentColor = MaterialTheme.colorScheme.primary,
                                                                shape = RoundedCornerShape(4.dp)
                                                            ) {
                                                                Text(
                                                                    text = "ACTIVE",
                                                                    fontSize = 8.sp,
                                                                    fontWeight = FontWeight.Bold,
                                                                    modifier = Modifier.padding(horizontal = 4.dp, vertical = 2.dp)
                                                                )
                                                            }
                                                            Spacer(modifier = Modifier.width(4.dp))
                                                        }
                                                        if (isDownloaded) {
                                                            Text(
                                                                text = "($individualSize)",
                                                                fontSize = 11.sp,
                                                                color = MaterialTheme.colorScheme.primary,
                                                                fontWeight = FontWeight.SemiBold
                                                            )
                                                            Spacer(modifier = Modifier.width(6.dp))
                                                            Surface(
                                                                color = GreenTone.copy(alpha = 0.15f),
                                                                contentColor = GreenTone,
                                                                shape = RoundedCornerShape(4.dp)
                                                            ) {
                                                                Row(
                                                                    verticalAlignment = Alignment.CenterVertically,
                                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                                ) {
                                                                    Icon(
                                                                        imageVector = Icons.Default.Check,
                                                                        contentDescription = null,
                                                                        modifier = Modifier.size(10.dp)
                                                                    )
                                                                    Spacer(modifier = Modifier.width(2.dp))
                                                                    Text(
                                                                        text = "OFFLINE READY",
                                                                        fontSize = 8.sp,
                                                                        fontWeight = FontWeight.Bold
                                                                    )
                                                                }
                                                            }
                                                        } else {
                                                            Text(
                                                                text = "(${formatStorageBytes(translation.baseSizeInBytes / 90L)})",
                                                                fontSize = 11.sp,
                                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)
                                                            )
                                                        }
                                                    }
                                                    Text(
                                                        text = translation.fullName,
                                                        style = MaterialTheme.typography.bodySmall,
                                                        fontWeight = FontWeight.Medium,
                                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                                                    )
                                                    Text(
                                                        text = translation.description,
                                                        style = MaterialTheme.typography.bodySmall,
                                                        fontSize = 10.sp,
                                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f),
                                                        maxLines = 2,
                                                        overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                                                    )
                                                    Text(
                                                        text = "Tap version for extended description popup ℹ️",
                                                        style = MaterialTheme.typography.bodySmall,
                                                        fontSize = 9.sp,
                                                        color = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f),
                                                        fontWeight = FontWeight.Medium,
                                                        modifier = Modifier.padding(top = 2.dp)
                                                    )

                                                    if (progress != null) {
                                                        Spacer(modifier = Modifier.height(6.dp))
                                                        Row(
                                                            verticalAlignment = Alignment.CenterVertically,
                                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                        ) {
                                                            LinearProgressIndicator(
                                                                progress = { progress / 100f },
                                                                modifier = Modifier.weight(1f).height(4.dp).clip(CircleShape),
                                                                color = MaterialTheme.colorScheme.primary,
                                                                trackColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.2f),
                                                            )
                                                            Text(
                                                                text = "$progress%",
                                                                fontSize = 10.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = MaterialTheme.colorScheme.primary
                                                            )
                                                        }
                                                    }
                                                }

                                                Spacer(modifier = Modifier.width(8.dp))

                                                // Toggle switch to manage download status
                                                if (progress != null) {
                                                    CircularProgressIndicator(
                                                        modifier = Modifier.size(24.dp),
                                                        strokeWidth = 2.dp,
                                                        color = MaterialTheme.colorScheme.primary
                                                    )
                                                } else {
                                                    Switch(
                                                        checked = isDownloaded,
                                                        onCheckedChange = { checked ->
                                                            if (checked) {
                                                                viewModel.downloadVersion(translation.code)
                                                            } else {
                                                                if (downloadedState.size <= 1) {
                                                                    Toast.makeText(context, "Cannot delete! At least one offline translation must remain installed.", Toast.LENGTH_LONG).show()
                                                                } else {
                                                                    confirmDeletion(
                                                                        "Uninstall Translation",
                                                                        "Are you sure you want to delete ${translation.fullName} (${translation.code})? This will free up approximately $individualSize of storage."
                                                                    ) {
                                                                        viewModel.deleteVersion(translation.code)
                                                                        Toast.makeText(context, "${translation.code} uninstalled.", Toast.LENGTH_SHORT).show()
                                                                    }
                                                                }
                                                            }
                                                        },
                                                        modifier = Modifier.testTag("translation_toggle_${translation.code}")
                                                    )
                                                }
                                            }
                                            
                                            if (index < group.translations.size - 1) {
                                                HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.05f))
                                            }
                                        }
                                    }
                                }
                            }
                            HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f), modifier = Modifier.padding(top = 4.dp))
                        }
                    }
                }
            }
        }
    }

        // Full Search History Card in Settings
        item {
            if (selectedCategoryTab == 0 || selectedCategoryTab == 4) {
            Card(
                modifier = Modifier.fillMaxWidth().testTag("settings_search_history_card"),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                imageVector = Icons.Default.History,
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.size(24.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = "Search History Management",
                                style = MaterialTheme.typography.titleMedium,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }
                        if (recentSearchesSettings.isNotEmpty()) {
                            TextButton(
                                onClick = {
                                    confirmDeletion(
                                        "Clear Search History",
                                        "Are you sure you want to clear your entire search history?"
                                    ) {
                                        viewModel.clearRecentSearches()
                                        Toast.makeText(context, "Search history cleared!", Toast.LENGTH_SHORT).show()
                                    }
                                }
