                        ) {
                            Text(
                                text = "Your search history is empty.",
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                            )
                        }
                    } else {
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            recentSearchesSettings.forEach { query ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable {
                                            viewModel.updateSearchQuery(query)
                                            viewModel.navigateTo(Screen.HOME)
                                        }
                                        .background(MaterialTheme.colorScheme.onSurface.copy(alpha = 0.03f), RoundedCornerShape(8.dp))
                                        .padding(horizontal = 12.dp, vertical = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Search,
                                            contentDescription = null,
                                            tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f),
                                            modifier = Modifier.size(16.dp)
                                        )
                                        Spacer(modifier = Modifier.width(10.dp))
                                        Text(
                                            text = query,
                                            fontSize = 14.sp,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                    }
                                    IconButton(
                                        onClick = {
                                            confirmDeletion(
                                                "Delete Search Term",
                                                "Are you sure you want to delete '$query' from your history?"
                                            ) {
                                                viewModel.deleteRecentSearch(query)
                                                Toast.makeText(context, "Search term deleted!", Toast.LENGTH_SHORT).show()
                                            }
                                        },
                                        modifier = Modifier.size(32.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Close,
                                            contentDescription = "Delete search term",
                                            tint = MaterialTheme.colorScheme.error.copy(alpha = 0.7f),
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

        // 4b. Manual Backup & JSON Export/Import Card
        item {
            if (selectedCategoryTab == 0 || selectedCategoryTab == 4) {
            var importText by remember { mutableStateOf("") }
            var showImportDialog by remember { mutableStateOf(false) }
            val clipboardManager = androidx.compose.ui.platform.LocalClipboardManager.current
            
            // Standard file picker launchers
            val exportLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
                contract = androidx.activity.result.contract.ActivityResultContracts.CreateDocument("application/json")
            ) { uri ->
                if (uri != null) {
                    viewModel.exportBackup { json ->
                        if (json != null) {
                            try {
                                context.contentResolver.openOutputStream(uri)?.use { outputStream ->
                                    outputStream.write(json.toByteArray())
                                }
                                Toast.makeText(context, "Backup successfully exported to file!", Toast.LENGTH_SHORT).show()
                            } catch (e: Exception) {
                                Toast.makeText(context, "Failed to write file: ${e.message}", Toast.LENGTH_LONG).show()
                            }
                        } else {
                            Toast.makeText(context, "Failed to generate backup", Toast.LENGTH_SHORT).show()
                        }
                    }
                }
            }

            val importLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
                contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
            ) { uri ->
                if (uri != null) {
                    try {
                        context.contentResolver.openInputStream(uri)?.use { inputStream ->
                            val json = inputStream.bufferedReader().use { it.readText() }
                            viewModel.importBackup(json) { success ->
                                if (success) {
                                    Toast.makeText(context, "Backup successfully imported!", Toast.LENGTH_SHORT).show()
                                } else {
                                    Toast.makeText(context, "Invalid backup file or format.", Toast.LENGTH_LONG).show()
                                }
                            }
                        }
                    } catch (e: Exception) {
                        Toast.makeText(context, "Failed to read file: ${e.message}", Toast.LENGTH_LONG).show()
                    }
                }
            }

            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .testTag("settings_manual_backup_card"),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp),
                border = androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Default.Sync,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(24.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "Manual Backup & Portability",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                    }

                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = "Export or import your scripture highlights, study milestones, and reading progress as a JSON backup file. Perfect for manual backups or transferring data.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                    )

                    Spacer(modifier = Modifier.height(16.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Button(
                            onClick = {
                                try {
                                    exportLauncher.launch("bible_bridge_backup_${System.currentTimeMillis()}.json")
                                } catch (e: Exception) {
                                    viewModel.exportBackup { json ->
                                        if (json != null) {
                                            clipboardManager.setText(androidx.compose.ui.text.AnnotatedString(json))
                                            Toast.makeText(context, "Backup JSON copied to clipboard!", Toast.LENGTH_LONG).show()
                                        } else {
                                            Toast.makeText(context, "Failed to export backup", Toast.LENGTH_SHORT).show()
                                        }
                                    }
                                }
                            },
                            modifier = Modifier.weight(1f).testTag("backup_export_btn"),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Icon(Icons.Default.Download, contentDescription = null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Export JSON", fontSize = 12.sp)
                        }

                        OutlinedButton(
                            onClick = {
                                try {
                                    importLauncher.launch("application/json")
                                } catch (e: Exception) {
                                    showImportDialog = true
                                }
                            },
                            modifier = Modifier.weight(1f).testTag("backup_import_btn"),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Icon(Icons.Default.Cloud, contentDescription = null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Import JSON", fontSize = 12.sp)
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.Center
                    ) {
                        TextButton(
                            onClick = {
                                viewModel.exportBackup { json ->
                                    if (json != null) {
                                        clipboardManager.setText(androidx.compose.ui.text.AnnotatedString(json))
                                        Toast.makeText(context, "Backup JSON copied to clipboard!", Toast.LENGTH_SHORT).show()
                                    } else {
                                        Toast.makeText(context, "Failed to export", Toast.LENGTH_SHORT).show()
                                    }
                                }
                            }
                        ) {
                            Text("Copy JSON text", fontSize = 11.sp)
                        }

                        Text(
                            text = "•",
                            fontSize = 11.sp,
                            modifier = Modifier.align(Alignment.CenterVertically).padding(horizontal = 4.dp),
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)
                        )

                        TextButton(
                            onClick = { showImportDialog = true }
                        ) {
                            Text("Paste JSON text", fontSize = 11.sp)
                        }
                    }
                }
            }

            if (showImportDialog) {
                AlertDialog(
                    onDismissRequest = { showImportDialog = false },
                    title = { Text("Paste Backup JSON") },
                    text = {
                        Column {
                            Text("Paste your previously exported backup JSON content below:", fontSize = 12.sp)
                            Spacer(modifier = Modifier.height(8.dp))
                            OutlinedTextField(
                                value = importText,
                                onValueChange = { importText = it },
                                modifier = Modifier.fillMaxWidth().height(160.dp),
                                textStyle = MaterialTheme.typography.bodySmall,
                                label = { Text("Backup JSON") },
                                maxLines = 10
                            )
                        }
                    },
                    confirmButton = {
                        Button(
                            onClick = {
                                if (importText.isNotBlank()) {
                                    viewModel.importBackup(importText) { success ->
                                        if (success) {
                                            Toast.makeText(context, "Backup successfully restored!", Toast.LENGTH_SHORT).show()
                                            showImportDialog = false
                                            importText = ""
                                        } else {
                                            Toast.makeText(context, "Invalid JSON data or schema. Ensure it's a valid backup.", Toast.LENGTH_LONG).show()
                                        }
                                    }
                                }
                            }
                        ) {
                            Text("Restore")
                        }
                    },
                    dismissButton = {
                        TextButton(onClick = { showImportDialog = false }) {
                            Text("Cancel")
                        }
                    }
                )
            }
        }
    }

        // 5. Build specifications
        item {
            if (selectedCategoryTab == 0 || selectedCategoryTab == 4) {
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant),
                shape = RoundedCornerShape(16.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text("System Specification", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                    Spacer(modifier = Modifier.height(8.dp))
                    RowValue("App Version", "1.4.2-Release")
                    RowValue("Engine Build", "SQLite Room v2.6.1")
                    RowValue("Schema Hash", "3b6a0dcd")
                    RowValue("AI Model", "Gemini 1.5 Flash REST Server-Side")
                    RowValue("Connectivity", "Dual Mode (Offline/Cloud Hybrid)")
                }
            }
        }
    }
    }

    selectedTranslationForPopup?.let { meta ->
        val isDownloaded = downloadedState.contains(meta.code)
        val isActive = currentSelectedTranslation.equals(meta.code, ignoreCase = true)

        TranslationDetailsDialog(
            metadata = meta,
            isDownloaded = isDownloaded,
            isActive = isActive,
            onDismiss = { selectedTranslationForPopup = null },
            onSelect = {
                viewModel.selectTranslation(meta.code)
                Toast.makeText(context, "Set ${meta.fullName} as active Bible version", Toast.LENGTH_SHORT).show()
            },
            onDownloadToggle = {
                if (isDownloaded) {
                    if (downloadedState.size <= 1) {
                        Toast.makeText(context, "Cannot delete! At least one offline translation must remain installed.", Toast.LENGTH_LONG).show()
                    } else {
                        confirmDeletion(
                            "Uninstall Translation",
                            "Are you sure you want to delete ${meta.fullName} (${meta.code})?"
                        ) {
                            viewModel.deleteVersion(meta.code)
                            Toast.makeText(context, "${meta.code} uninstalled.", Toast.LENGTH_SHORT).show()
                            selectedTranslationForPopup = null
                        }
                    }
                } else {
                    viewModel.downloadVersion(meta.code)
                    Toast.makeText(context, "Downloading ${meta.code}...", Toast.LENGTH_SHORT).show()
                    selectedTranslationForPopup = null
                }
            }
        )
    }
}
}

@Composable
fun FavoritesDialog(
    viewModel: BibleViewModel,
    onDismiss: () -> Unit,
    confirmDeletion: (String, String, () -> Unit) -> Unit
) {
    val favorites by viewModel.favoriteVerses.collectAsStateWithLifecycle()
    val bookmarks by viewModel.bookmarkedVerses.collectAsStateWithLifecycle()
    var subTabState by remember { mutableStateOf(0) } // 0 = Bookmarks, 1 = Favorites
    var searchQuery by remember { mutableStateOf("") }
    val context = LocalContext.current
    
    val filteredBookmarks = if (searchQuery.isBlank()) {
        bookmarks
    } else {
        bookmarks.filter { 
            it.text.contains(searchQuery, ignoreCase = true) || 
            it.bookName.contains(searchQuery, ignoreCase = true) 
        }
    }

    val filteredFavorites = if (searchQuery.isBlank()) {
        favorites
    } else {
        favorites.filter { 
            it.text.contains(searchQuery, ignoreCase = true) || 
            it.bookName.contains(searchQuery, ignoreCase = true) 
        }
    }

    Dialog(onDismissRequest = onDismiss) {
        Card(
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            modifier = Modifier
                .fillMaxWidth()
                .fillMaxHeight(0.85f)
                .padding(vertical = 16.dp)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp)
            ) {
                // Header
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Default.Bookmark,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(24.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "Saved Scripture",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold,
                            fontFamily = FontFamily.Serif,
                            color = MaterialTheme.colorScheme.primary
                        )
                    }
                    IconButton(onClick = onDismiss, modifier = Modifier.testTag("close_favorites_btn")) {
                        Icon(Icons.Default.Close, "Close")
                    }
                }
                
                Spacer(modifier = Modifier.height(12.dp))

                // Custom premium tab bar for switching Bookmarks / Favorites
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f), RoundedCornerShape(12.dp))
                        .padding(4.dp),
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .clip(RoundedCornerShape(8.dp))
                            .background(if (subTabState == 0) MaterialTheme.colorScheme.primary else Color.Transparent)
