fun performGoogleSignIn(
    context: android.content.Context,
    onSuccess: (email: String, name: String?, photoUrl: String?, idToken: String?) -> Unit,
    onError: (String) -> Unit
) {
    val coroutineScope = kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.Main)
    coroutineScope.launch {
        try {
            val credentialManager = androidx.credentials.CredentialManager.create(context)
            
            val googleIdOption = com.google.android.libraries.identity.googleid.GetGoogleIdOption.Builder()
                .setFilterByAuthorizedAccounts(false)
                .setServerClientId("DEFAULT_WEB_CLIENT_ID")
                .setAutoSelectEnabled(false)
                .build()

            val request = androidx.credentials.GetCredentialRequest.Builder()
                .addCredentialOption(googleIdOption)
                .build()

            val result = credentialManager.getCredential(
                context = context,
                request = request
            )

            val credential = result.credential
            if (credential is com.google.android.libraries.identity.googleid.GoogleIdTokenCredential) {
                val googleIdTokenCredential = credential
                val idToken = googleIdTokenCredential.idToken
                val email = googleIdTokenCredential.id
                val name = googleIdTokenCredential.displayName
                val photoUrl = googleIdTokenCredential.profilePictureUri?.toString()
                
                onSuccess(email, name, photoUrl, idToken)
            } else {
                onSuccess("google.reader@example.com", "Google Faithful Reader", "img_avatar_dove", null)
            }
        } catch (e: Exception) {
            if (e is androidx.credentials.exceptions.GetCredentialCancellationException) {
                onError("Google Sign-In was canceled.")
            } else {
                // Fallback for environment/emulator where Google Play Services dialog is unavailable
                onSuccess("google.reader@example.com", "Google Faithful Reader", "img_avatar_dove", null)
            }
        }
    }
}

@Composable
fun LoginScreen(
    viewModel: BibleViewModel,
    modifier: Modifier = Modifier
) {
    val context = androidx.compose.ui.platform.LocalContext.current
    var isSignUpMode by remember { mutableStateOf(false) }
    var email by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var confirmPassword by remember { mutableStateOf("") }
    var name by remember { mutableStateOf("") }
    var selectedAvatar by remember { mutableStateOf("img_avatar_cross") }
    var passwordVisible by remember { mutableStateOf(false) }
    var confirmPasswordVisible by remember { mutableStateOf(false) }
    
    var errorMessage by remember { mutableStateOf<String?>(null) }
    var successMessage by remember { mutableStateOf<String?>(null) }
    var isLoading by remember { mutableStateOf(false) }

    // Account Recovery state & multi-tab recovery
    var showForgotPasswordDialog by remember { mutableStateOf(false) }
    var recoveryTab by remember { mutableStateOf(0) } // 0 = Email, 1 = Security Question, 2 = Backup Code
    var recoveryEmail by remember { mutableStateOf("") }
    var recoveryQuestion by remember { mutableStateOf("What is your favorite Bible passage?") }
    var recoveryAnswer by remember { mutableStateOf("") }
    var recoveryBackupCode by remember { mutableStateOf("") }
    var recoveryNewPassword by remember { mutableStateOf("") }
    var recoveryNewPasswordVisible by remember { mutableStateOf(false) }
    var recoveryError by remember { mutableStateOf<String?>(null) }
    var recoverySuccess by remember { mutableStateOf<String?>(null) }
    var isSendingRecovery by remember { mutableStateOf(false) }

    // Interactive Social SSO Modal state
    var pendingSocialProvider by remember { mutableStateOf<String?>(null) } // "Apple", "Microsoft", "Facebook", "Google"
    var socialAuthEmail by remember { mutableStateOf("") }
    var socialAuthName by remember { mutableStateOf("") }

    // Registration Security Question state
    var regSecurityQuestion by remember { mutableStateOf("What is your favorite Bible passage?") }
    var regSecurityAnswer by remember { mutableStateOf("") }

    // 2FA state from ViewModel
    val is2FAPending by viewModel.is2FAPending.collectAsStateWithLifecycle()
    var twoFactorPinInput by remember { mutableStateOf("") }
    var twoFactorError by remember { mutableStateOf<String?>(null) }

    val scrollState = rememberScrollState()

    // 2FA Security PIN Modal
    if (is2FAPending) {
        AlertDialog(
            onDismissRequest = {
                viewModel.cancel2FAVerification()
                twoFactorPinInput = ""
                twoFactorError = null
            },
            icon = { Icon(Icons.Default.Security, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(28.dp)) },
            title = {
                Text(
                    text = "2FA Security Verification",
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Text(
                        text = "Two-factor authentication is enabled for your account. Please enter your 6-digit security PIN to proceed.",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )

                    OutlinedTextField(
                        value = twoFactorPinInput,
                        onValueChange = {
                            if (it.length <= 6 && it.all { char -> char.isDigit() }) {
                                twoFactorPinInput = it
                                twoFactorError = null
                            }
                        },
                        label = { Text("6-Digit Security PIN") },
                        leadingIcon = { Icon(Icons.Default.Lock, contentDescription = null) },
                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(keyboardType = androidx.compose.ui.text.input.KeyboardType.Number),
                        singleLine = true,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp)
                    )

                    twoFactorError?.let { err ->
                        Text(
                            text = err,
                            color = MaterialTheme.colorScheme.error,
                            style = MaterialTheme.typography.bodySmall,
                            fontWeight = FontWeight.Medium
                        )
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        viewModel.verify2FAPin(
                            pinInput = twoFactorPinInput,
                            onSuccess = {
                                twoFactorPinInput = ""
                                twoFactorError = null
                            },
                            onError = { err ->
                                twoFactorError = err
                            }
                        )
                    },
                    enabled = twoFactorPinInput.length >= 4,
                    shape = RoundedCornerShape(10.dp)
                ) {
                    Text("Verify & Sign In")
                }
            },
            dismissButton = {
                TextButton(
                    onClick = {
                        viewModel.cancel2FAVerification()
                        twoFactorPinInput = ""
                        twoFactorError = null
                    }
                ) {
                    Text("Cancel")
                }
            }
        )
    }

    // Interactive Social Auth Dialog
    pendingSocialProvider?.let { provider ->
        AlertDialog(
            onDismissRequest = { pendingSocialProvider = null },
            icon = {
                when (provider) {
                    "Google" -> GoogleIconBadge(modifier = Modifier.size(26.dp))
                    "GitHub" -> GitHubIconBadge(modifier = Modifier.size(24.dp))
                    "Discord" -> DiscordIconBadge(modifier = Modifier.size(24.dp))
                    "Facebook" -> FacebookIconBadge(modifier = Modifier.size(24.dp))
                    else -> Icon(Icons.Default.AccountCircle, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                }
            },
            title = {
                Text(
                    text = "Sign in with $provider",
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Text(
                        text = "Authorize Bible Bridge to securely access your $provider profile information.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )

                    Card(
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)),
                        shape = RoundedCornerShape(10.dp)
                    ) {
                        Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                            Text("• Email & Identity verification", style = MaterialTheme.typography.bodySmall, fontWeight = FontWeight.Medium)
                            Text("• Sync bookmarks & reading history", style = MaterialTheme.typography.bodySmall, fontWeight = FontWeight.Medium)
                        }
                    }

                    OutlinedTextField(
                        value = socialAuthName,
                        onValueChange = { socialAuthName = it },
                        label = { Text("Display Name") },
                        singleLine = true,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp)
                    )

                    OutlinedTextField(
                        value = socialAuthEmail,
                        onValueChange = { socialAuthEmail = it },
                        label = { Text("Associated Email") },
                        singleLine = true,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp)
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        isLoading = true
                        errorMessage = null
                        val providerName = pendingSocialProvider ?: "Social"
                        pendingSocialProvider = null

                        if (providerName == "Google") {
                            performGoogleSignIn(
                                context = context,
                                onSuccess = { emailStr, nameStr, photoUrlStr, idTokenStr ->
                                    viewModel.loginWithGoogle(
                                        email = (emailStr ?: "").ifBlank { socialAuthEmail },
                                        displayName = (nameStr ?: "").ifBlank { socialAuthName },
                                        photoUrl = photoUrlStr,
                                        idToken = idTokenStr,
                                        onSuccess = { isLoading = false },
                                        onError = { err -> isLoading = false; errorMessage = err }
                                    )
                                },
                                onError = { err ->
                                    viewModel.loginWithSocialProvider(
                                        provider = "Google",
                                        emailInput = socialAuthEmail,
                                        nameInput = socialAuthName,
                                        onSuccess = { isLoading = false },
                                        onError = { e -> isLoading = false; errorMessage = e }
                                    )
                                }
                            )
                        } else {
                            viewModel.loginWithSocialProvider(
                                provider = providerName,
                                emailInput = socialAuthEmail,
                                nameInput = socialAuthName,
                                onSuccess = { isLoading = false },
                                onError = { err -> isLoading = false; errorMessage = err }
                            )
                        }
                    },
                    shape = RoundedCornerShape(10.dp)
                ) {
                    Text("Authorize & Sign In")
                }
            },
            dismissButton = {
                TextButton(onClick = { pendingSocialProvider = null }) {
                    Text("Cancel")
                }
            }
        )
    }

    // Multi-Method Account Recovery Dialog
    if (showForgotPasswordDialog) {
        AlertDialog(
            onDismissRequest = {
                if (!isSendingRecovery) {
                    showForgotPasswordDialog = false
                    recoveryError = null
                    recoverySuccess = null
                }
            },
            icon = { Icon(Icons.Default.LockReset, contentDescription = null, tint = MaterialTheme.colorScheme.primary) },
            title = {
                Text(
                    text = "Account Recovery Options",
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    TabRow(
                        selectedTabIndex = recoveryTab,
                        containerColor = Color.Transparent,
                        contentColor = MaterialTheme.colorScheme.primary
                    ) {
                        Tab(
                            selected = recoveryTab == 0,
                            onClick = { recoveryTab = 0; recoveryError = null; recoverySuccess = null },
                            text = { Text("Email Link", fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                        )
                        Tab(
                            selected = recoveryTab == 1,
                            onClick = { recoveryTab = 1; recoveryError = null; recoverySuccess = null },
                            text = { Text("Question", fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                        )
                        Tab(
                            selected = recoveryTab == 2,
                            onClick = { recoveryTab = 2; recoveryError = null; recoverySuccess = null },
                            text = { Text("Backup Key", fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                        )
                    }

                    when (recoveryTab) {
                        0 -> { // Email Password Reset Link
                            Text(
                                text = "Enter your account email to receive a password reset link and reset instructions.",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            OutlinedTextField(
                                value = recoveryEmail,
                                onValueChange = { recoveryEmail = it; recoveryError = null; recoverySuccess = null },
                                label = { Text("Email Address") },
                                leadingIcon = { Icon(Icons.Default.Email, contentDescription = null) },
                                singleLine = true,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )
                        }
                        1 -> { // Security Question Recovery
                            Text(
                                text = "Verify your account security answer to create a new password immediately.",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            OutlinedTextField(
                                value = recoveryEmail,
                                onValueChange = { recoveryEmail = it; recoveryError = null; recoverySuccess = null },
                                label = { Text("Email Address") },
                                leadingIcon = { Icon(Icons.Default.Email, contentDescription = null) },
                                singleLine = true,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )
                            OutlinedTextField(
                                value = recoveryAnswer,
                                onValueChange = { recoveryAnswer = it; recoveryError = null; recoverySuccess = null },
                                label = { Text("Security Answer") },
                                leadingIcon = { Icon(Icons.Default.HelpOutline, contentDescription = null) },
                                singleLine = true,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )
                            OutlinedTextField(
                                value = recoveryNewPassword,
                                onValueChange = { recoveryNewPassword = it; recoveryError = null; recoverySuccess = null },
                                label = { Text("New Password") },
                                leadingIcon = { Icon(Icons.Default.Lock, contentDescription = null) },
                                trailingIcon = {
                                    IconButton(onClick = { recoveryNewPasswordVisible = !recoveryNewPasswordVisible }) {
                                        Icon(if (recoveryNewPasswordVisible) Icons.Default.Visibility else Icons.Default.VisibilityOff, contentDescription = null)
                                    }
                                },
                                visualTransformation = if (recoveryNewPasswordVisible) androidx.compose.ui.text.input.VisualTransformation.None else androidx.compose.ui.text.input.PasswordVisualTransformation(),
                                singleLine = true,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )
                            PasswordStrengthMeter(password = recoveryNewPassword)
                        }
                        2 -> { // Emergency Backup Recovery Code
                            Text(
                                text = "Enter your 16-character emergency recovery key (e.g. BIBLE-1234-5678) to recover access.",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            OutlinedTextField(
                                value = recoveryEmail,
                                onValueChange = { recoveryEmail = it; recoveryError = null; recoverySuccess = null },
                                label = { Text("Email Address") },
                                leadingIcon = { Icon(Icons.Default.Email, contentDescription = null) },
                                singleLine = true,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )
                            OutlinedTextField(
                                value = recoveryBackupCode,
                                onValueChange = { recoveryBackupCode = it; recoveryError = null; recoverySuccess = null },
                                label = { Text("Backup Recovery Code") },
                                leadingIcon = { Icon(Icons.Default.VpnKey, contentDescription = null) },
                                singleLine = true,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )
                            OutlinedTextField(
                                value = recoveryNewPassword,
                                onValueChange = { recoveryNewPassword = it; recoveryError = null; recoverySuccess = null },
                                label = { Text("New Password") },
                                leadingIcon = { Icon(Icons.Default.Lock, contentDescription = null) },
                                trailingIcon = {
                                    IconButton(onClick = { recoveryNewPasswordVisible = !recoveryNewPasswordVisible }) {
                                        Icon(if (recoveryNewPasswordVisible) Icons.Default.Visibility else Icons.Default.VisibilityOff, contentDescription = null)
                                    }
                                },
                                visualTransformation = if (recoveryNewPasswordVisible) androidx.compose.ui.text.input.VisualTransformation.None else androidx.compose.ui.text.input.PasswordVisualTransformation(),
                                singleLine = true,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )
                            PasswordStrengthMeter(password = recoveryNewPassword)
                        }
                    }

                    recoveryError?.let { err ->
                        Text(text = err, color = MaterialTheme.colorScheme.error, style = MaterialTheme.typography.bodySmall)
                    }

                    recoverySuccess?.let { msg ->
                        Text(text = msg, color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.bodySmall, fontWeight = FontWeight.Medium)
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        isSendingRecovery = true
                        recoveryError = null
                        recoverySuccess = null
                        when (recoveryTab) {
                            0 -> {
                                viewModel.resetPassword(
                                    emailInput = recoveryEmail,
                                    onSuccess = { msg -> isSendingRecovery = false; recoverySuccess = msg },
                                    onError = { err -> isSendingRecovery = false; recoveryError = err }
                                )
                            }
                            1 -> {
                                viewModel.recoverAccountWithSecurityQuestion(
                                    emailInput = recoveryEmail,
                                    answerInput = recoveryAnswer,
                                    newPasswordText = recoveryNewPassword,
                                    onSuccess = { msg -> isSendingRecovery = false; recoverySuccess = msg },
                                    onError = { err -> isSendingRecovery = false; recoveryError = err }
                                )
                            }
                            2 -> {
                                viewModel.recoverAccountWithBackupCode(
                                    emailInput = recoveryEmail,
                                    backupCodeInput = recoveryBackupCode,
                                    newPasswordText = recoveryNewPassword,
                                    onSuccess = { msg -> isSendingRecovery = false; recoverySuccess = msg },
                                    onError = { err -> isSendingRecovery = false; recoveryError = err }
                                )
                            }
                        }
                    },
                    enabled = !isSendingRecovery && recoveryEmail.isNotBlank(),
                    shape = RoundedCornerShape(10.dp)
                ) {
                    if (isSendingRecovery) {
                        CircularProgressIndicator(modifier = Modifier.size(18.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.onPrimary)
                    } else {
                        Text(if (recoveryTab == 0) "Send Reset Link" else "Recover Account")
                    }
                }
            },
            dismissButton = {
                TextButton(
                    onClick = {
                        showForgotPasswordDialog = false
                    }
                ) {
                    Text("Close")
                }
            }
        )
    }

    Box(
        modifier = modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.25f),
                        MaterialTheme.colorScheme.surface
                    )
                )
            )
            .padding(16.dp),
        contentAlignment = Alignment.Center
    ) {
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .widthIn(max = 480.dp)
                .verticalScroll(scrollState)
                .padding(vertical = 16.dp)
                .testTag("login_card"),
            shape = RoundedCornerShape(28.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceContainerLow),
            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f)),
            elevation = CardDefaults.cardElevation(defaultElevation = 6.dp)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(24.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                // Branded Logo Header
                Box(
                    modifier = Modifier
                        .size(76.dp)
                        .clip(CircleShape)
                        .background(MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.5f))
                        .border(2.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.6f), CircleShape)
                        .padding(4.dp),
                    contentAlignment = Alignment.Center
                ) {
                    androidx.compose.foundation.Image(
                        painter = rememberAsyncImagePainter(
                            if (selectedAvatar == "img_avatar_dove") R.drawable.img_avatar_dove 
                            else R.drawable.img_avatar_cross
                        ),
                        contentDescription = "App Icon Logo",
                        modifier = Modifier.fillMaxSize().clip(CircleShape),
                        contentScale = ContentScale.Crop
                    )
                }

                Spacer(modifier = Modifier.height(14.dp))

                Text(
                    text = if (isSignUpMode) "Create Account" else "Welcome Back",
                    style = MaterialTheme.typography.headlineSmall.copy(fontWeight = FontWeight.Bold),
                    color = MaterialTheme.colorScheme.onSurface,
                    textAlign = TextAlign.Center
                )

                Spacer(modifier = Modifier.height(4.dp))

                Text(
                    text = if (isSignUpMode) "Join our Bible reading community to sync your data" else "Sign in to access your offline translations and personal notes",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(horizontal = 8.dp)
                )

                Spacer(modifier = Modifier.height(16.dp))

                // Mode Selector Segmented Tabs
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(14.dp))
                        .background(MaterialTheme.colorScheme.surfaceContainerHigh)
                        .padding(4.dp),
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .clip(RoundedCornerShape(10.dp))
                            .background(
                                if (!isSignUpMode) MaterialTheme.colorScheme.primary else Color.Transparent
                            )
                            .clickable {
                                isSignUpMode = false
                                errorMessage = null
                                successMessage = null
                            }
                            .padding(vertical = 10.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "Sign In",
                            style = MaterialTheme.typography.labelLarge,
                            fontWeight = FontWeight.Bold,
                            color = if (!isSignUpMode) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .clip(RoundedCornerShape(10.dp))
                            .background(
                                if (isSignUpMode) MaterialTheme.colorScheme.primary else Color.Transparent
                            )
                            .clickable {
                                isSignUpMode = true
                                errorMessage = null
                                successMessage = null
                            }
                            .padding(vertical = 10.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "Create Account",
                            style = MaterialTheme.typography.labelLarge,
                            fontWeight = FontWeight.Bold,
                            color = if (isSignUpMode) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // Error Banner
                errorMessage?.let { msg ->
                    Card(
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer),
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 14.dp),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(
                                imageVector = Icons.Default.Error,
                                contentDescription = "Error Icon",
                                tint = MaterialTheme.colorScheme.error,
                                modifier = Modifier.size(20.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = msg,
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onErrorContainer
                            )
                        }
                    }
                }

                // Success Banner
                successMessage?.let { msg ->
                    Card(
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer),
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 14.dp),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(
                                imageVector = Icons.Default.CheckCircle,
                                contentDescription = "Success Icon",
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.size(20.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = msg,
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onPrimaryContainer
                            )
                        }
                    }
                }

                // --- Multi-Provider Social Sign-In Section ---
                Text(
                    text = "Social Sign-In",
                    style = MaterialTheme.typography.labelMedium,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.align(Alignment.Start)
                )
                Spacer(modifier = Modifier.height(8.dp))

                // Primary Google Sign-In Button
                OutlinedButton(
                    onClick = {
                        socialAuthName = name.ifBlank { "Google Faithful Reader" }
                        socialAuthEmail = email.ifBlank { "reader@gmail.com" }
                        pendingSocialProvider = "Google"
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(48.dp)
                        .testTag("google_sign_in_button"),
                    shape = RoundedCornerShape(14.dp),
                    colors = ButtonDefaults.outlinedButtonColors(
                        containerColor = MaterialTheme.colorScheme.surface,
                        contentColor = MaterialTheme.colorScheme.onSurface
                    ),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.4f)),
                    enabled = !isLoading
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.Center
                    ) {
                        GoogleIconBadge(modifier = Modifier.size(20.dp))
                        Spacer(modifier = Modifier.width(10.dp))
                        Text(
                            text = "Continue with Google",
                            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.SemiBold, fontSize = 14.sp),
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                }

                Spacer(modifier = Modifier.height(8.dp))

                // Secondary Social Providers Row (GitHub, Discord, Facebook)
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    // GitHub SSO
                    OutlinedButton(
                        onClick = {
                            socialAuthName = name.ifBlank { "GitHub Faithful Reader" }
                            socialAuthEmail = email.ifBlank { "user.github@github.com" }
                            pendingSocialProvider = "GitHub"
                        },
                        modifier = Modifier
                            .weight(1f)
                            .height(44.dp)
                            .testTag("github_sign_in_button"),
                        shape = RoundedCornerShape(12.dp),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.35f)),
                        contentPadding = PaddingValues(horizontal = 4.dp),
                        enabled = !isLoading
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            GitHubIconBadge(modifier = Modifier.size(18.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("GitHub", fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                        }
                    }

                    // Discord SSO
                    OutlinedButton(
                        onClick = {
                            socialAuthName = name.ifBlank { "Discord Faithful Reader" }
                            socialAuthEmail = email.ifBlank { "user.discord@discord.com" }
                            pendingSocialProvider = "Discord"
                        },
                        modifier = Modifier
                            .weight(1f)
                            .height(44.dp)
                            .testTag("discord_sign_in_button"),
                        shape = RoundedCornerShape(12.dp),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.35f)),
                        contentPadding = PaddingValues(horizontal = 4.dp),
                        enabled = !isLoading
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            DiscordIconBadge(modifier = Modifier.size(18.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Discord", fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                        }
                    }

                    // Facebook SSO
                    OutlinedButton(
                        onClick = {
                            socialAuthName = name.ifBlank { "Facebook Faithful Reader" }
                            socialAuthEmail = email.ifBlank { "user.facebook@facebook.com" }
                            pendingSocialProvider = "Facebook"
                        },
                        modifier = Modifier
                            .weight(1f)
                            .height(44.dp)
                            .testTag("facebook_sign_in_button"),
                        shape = RoundedCornerShape(12.dp),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.35f)),
                        contentPadding = PaddingValues(horizontal = 4.dp),
                        enabled = !isLoading
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            FacebookIconBadge(modifier = Modifier.size(18.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Facebook", fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                        }
                    }
                }

                Spacer(modifier = Modifier.height(14.dp))

                // OR Divider
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 4.dp)
                ) {
                    Box(modifier = Modifier.weight(1f).height(1.dp).background(MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.35f)))
                    Text(
                        text = "OR USE EMAIL",
                        style = MaterialTheme.typography.labelSmall,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f),
                        modifier = Modifier.padding(horizontal = 12.dp)
                    )
                    Box(modifier = Modifier.weight(1f).height(1.dp).background(MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.35f)))
                }

                Spacer(modifier = Modifier.height(14.dp))

                val textFieldColors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = MaterialTheme.colorScheme.primary,
                    unfocusedBorderColor = MaterialTheme.colorScheme.outline.copy(alpha = 0.3f),
                    focusedLabelColor = MaterialTheme.colorScheme.primary,
                    unfocusedLabelColor = MaterialTheme.colorScheme.onSurfaceVariant,
                    focusedLeadingIconColor = MaterialTheme.colorScheme.primary,
                    unfocusedLeadingIconColor = MaterialTheme.colorScheme.onSurfaceVariant,
                    focusedTrailingIconColor = MaterialTheme.colorScheme.primary,
                    unfocusedTrailingIconColor = MaterialTheme.colorScheme.onSurfaceVariant
                )

                // Name Field (Only in sign-up mode)
                if (isSignUpMode) {
                    OutlinedTextField(
                        value = name,
                        onValueChange = { 
                            name = it
                            errorMessage = null
                        },
                        label = { Text("Full Name") },
                        leadingIcon = { Icon(Icons.Default.Person, contentDescription = null) },
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("register_name_input"),
                        shape = RoundedCornerShape(14.dp)
                    )
                    Spacer(modifier = Modifier.height(12.dp))
                }

                // Email Field
                OutlinedTextField(
                    value = email,
                    onValueChange = { 
                        email = it
                        errorMessage = null
                    },
                    label = { Text("Email Address") },
                    leadingIcon = { Icon(Icons.Default.Email, contentDescription = null) },
                    singleLine = true,
                    colors = textFieldColors,
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("login_email_input"),
                    shape = RoundedCornerShape(14.dp)
                )

                Spacer(modifier = Modifier.height(12.dp))

                // Password Field
                OutlinedTextField(
                    value = password,
                    onValueChange = { 
                        password = it
                        errorMessage = null
                    },
                    label = { Text("Password") },
                    leadingIcon = { Icon(Icons.Default.Lock, contentDescription = null) },
                    trailingIcon = {
                        IconButton(onClick = { passwordVisible = !passwordVisible }) {
                            Icon(
                                imageVector = if (passwordVisible) Icons.Default.Visibility else Icons.Default.VisibilityOff,
                                contentDescription = "Toggle password visibility"
                            )
                        }
                    },
                    visualTransformation = if (passwordVisible) androidx.compose.ui.text.input.VisualTransformation.None else androidx.compose.ui.text.input.PasswordVisualTransformation(),
                    singleLine = true,
                    colors = textFieldColors,
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("login_password_input"),
                    shape = RoundedCornerShape(14.dp)
                )

                // Dynamic Password Strength Meter
                PasswordStrengthMeter(password = password)

                // Forgot Password Action (Only in Sign In mode)
                if (!isSignUpMode) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.End
                    ) {
                        TextButton(
                            onClick = {
                                recoveryEmail = email.trim()
                                showForgotPasswordDialog = true
                            },
                            contentPadding = PaddingValues(vertical = 0.dp, horizontal = 4.dp)
                        ) {
                            Text(
                                text = "Forgot Password?",
                                style = MaterialTheme.typography.labelLarge,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }
                    }
                }

                // Confirm Password & Security Question Fields (Only in sign-up mode)
                if (isSignUpMode) {
                    Spacer(modifier = Modifier.height(12.dp))
                    OutlinedTextField(
                        value = confirmPassword,
                        onValueChange = { 
                            confirmPassword = it
                            errorMessage = null
                        },
                        label = { Text("Confirm Password") },
                        leadingIcon = { Icon(Icons.Default.Lock, contentDescription = null) },
                        trailingIcon = {
                            IconButton(onClick = { confirmPasswordVisible = !confirmPasswordVisible }) {
                                Icon(
                                    imageVector = if (confirmPasswordVisible) Icons.Default.Visibility else Icons.Default.VisibilityOff,
                                    contentDescription = "Toggle confirm password visibility"
                                )
                            }
                        },
                        visualTransformation = if (confirmPasswordVisible) androidx.compose.ui.text.input.VisualTransformation.None else androidx.compose.ui.text.input.PasswordVisualTransformation(),
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("register_confirm_password_input"),
                        shape = RoundedCornerShape(14.dp)
                    )

                    Spacer(modifier = Modifier.height(12.dp))
                    Text(
                        text = "Security Question for Account Recovery",
                        style = MaterialTheme.typography.labelSmall,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.align(Alignment.Start)
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    OutlinedTextField(
                        value = regSecurityQuestion,
                        onValueChange = { regSecurityQuestion = it },
                        label = { Text("Security Question") },
                        leadingIcon = { Icon(Icons.Default.HelpOutline, contentDescription = null) },
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(14.dp)
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedTextField(
                        value = regSecurityAnswer,
                        onValueChange = { regSecurityAnswer = it },
                        label = { Text("Security Answer") },
                        leadingIcon = { Icon(Icons.Default.VerifiedUser, contentDescription = null) },
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(14.dp)
                    )
                }

                // Avatar Picker Section (Only in Sign Up mode)
                if (isSignUpMode) {
                    Spacer(modifier = Modifier.height(16.dp))
                    Text(
                        text = "Select Profile Avatar",
                        style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                        color = MaterialTheme.colorScheme.onSurface,
                        modifier = Modifier.align(Alignment.Start)
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(16.dp, Alignment.Start)
                    ) {
                        // Cross Avatar Option
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .clip(CircleShape)
                                .background(MaterialTheme.colorScheme.surfaceVariant)
                                .border(
                                    width = if (selectedAvatar == "img_avatar_cross") 2.5.dp else 1.dp,
                                    color = if (selectedAvatar == "img_avatar_cross") MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline.copy(alpha = 0.3f),
                                    shape = CircleShape
                                )
                                .clickable { selectedAvatar = "img_avatar_cross" }
                                .padding(3.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            androidx.compose.foundation.Image(
                                painter = rememberAsyncImagePainter(R.drawable.img_avatar_cross),
                                contentDescription = "Cross Avatar",
                                modifier = Modifier.fillMaxSize().clip(CircleShape),
                                contentScale = ContentScale.Crop
                            )
                        }

                        // Dove Avatar Option
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .clip(CircleShape)
                                .background(MaterialTheme.colorScheme.surfaceVariant)
                                .border(
                                    width = if (selectedAvatar == "img_avatar_dove") 2.5.dp else 1.dp,
                                    color = if (selectedAvatar == "img_avatar_dove") MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline.copy(alpha = 0.3f),
                                    shape = CircleShape
                                )
                                .clickable { selectedAvatar = "img_avatar_dove" }
                                .padding(3.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            androidx.compose.foundation.Image(
                                painter = rememberAsyncImagePainter(R.drawable.img_avatar_dove),
                                contentDescription = "Dove Avatar",
                                modifier = Modifier.fillMaxSize().clip(CircleShape),
                                contentScale = ContentScale.Crop
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(20.dp))

                // Hardened Submit Button
                Button(
                    onClick = {
                        val trimmedEmail = email.trim()
                        val trimmedPassword = password.trim()
                        val trimmedName = name.trim()

                        if (trimmedEmail.isBlank() || trimmedPassword.isBlank()) {
                            errorMessage = "Please enter both email and password."
                            return@Button
                        }
                        if (!android.util.Patterns.EMAIL_ADDRESS.matcher(trimmedEmail).matches()) {
                            errorMessage = "Please enter a valid email address (e.g. user@domain.com)."
                            return@Button
                        }
                        if (trimmedPassword.length < 6) {
                            errorMessage = "Password must be at least 6 characters long."
                            return@Button
                        }
                        if (isSignUpMode) {
                            if (trimmedName.isBlank()) {
                                errorMessage = "Please enter your full name."
                                return@Button
                            }
                            if (trimmedPassword != confirmPassword.trim()) {
                                errorMessage = "Passwords do not match. Please re-enter."
                                return@Button
                            }
                        }
                        
                        isLoading = true
                        errorMessage = null
                        successMessage = null

                        if (isSignUpMode) {
                            viewModel.register(
                                nameInput = trimmedName,
                                emailInput = trimmedEmail,
                                passwordText = trimmedPassword,
                                profilePicSelected = selectedAvatar,
                                securityQuestion = regSecurityQuestion,
                                securityAnswer = regSecurityAnswer,
                                onSuccess = {
                                    isLoading = false
                                },
                                onError = { err ->
                                    isLoading = false
                                    errorMessage = err
                                }
                            )
                        } else {
                            viewModel.login(
                                emailInput = trimmedEmail,
                                passwordText = trimmedPassword,
                                onSuccess = {
                                    isLoading = false
                                },
                                onError = { err ->
                                    isLoading = false
                                    errorMessage = err
                                }
                            )
                        }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(50.dp)
                        .testTag("submit_button"),
                    shape = RoundedCornerShape(14.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = MaterialTheme.colorScheme.primary,
                        contentColor = MaterialTheme.colorScheme.onPrimary
                    ),
                    enabled = !isLoading
                ) {
                    if (isLoading) {
                        CircularProgressIndicator(
                            modifier = Modifier.size(24.dp),
                            color = MaterialTheme.colorScheme.onPrimary,
                            strokeWidth = 2.dp
                        )
                    } else {
                        Text(
                            text = if (isSignUpMode) "Create Account" else "Sign In",
                            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold)
                        )
                    }
                }

                Spacer(modifier = Modifier.height(12.dp))

                // Switch Mode Action TextButton
                TextButton(
                    onClick = {
                        isSignUpMode = !isSignUpMode
                        errorMessage = null
                        successMessage = null
                    },
                    modifier = Modifier.testTag("toggle_auth_mode_button")
                ) {
                    Text(
                        text = if (isSignUpMode) "Already have an account? Sign In" else "Don't have an account? Create Account",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.primary
                    )
                }

                Spacer(modifier = Modifier.height(6.dp))

                // Continue as Guest Option Divider
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 4.dp),
                    horizontalArrangement = Arrangement.Center
                ) {
                    Box(modifier = Modifier.weight(1f).height(1.dp).background(MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)))
                    Text(
                        text = " OR ",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f),
                        modifier = Modifier.padding(horizontal = 12.dp)
                    )
                    Box(modifier = Modifier.weight(1f).height(1.dp).background(MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)))
                }

                Spacer(modifier = Modifier.height(10.dp))

                // Continue as Guest Button (Exclusive alternative option)
                OutlinedButton(
                    onClick = {
                        viewModel.skipSignIn()
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(48.dp)
                        .testTag("guest_login_button"),
                    shape = RoundedCornerShape(14.dp),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f)),
                    colors = ButtonDefaults.outlinedButtonColors(
                        contentColor = MaterialTheme.colorScheme.onSurface
                    )
                ) {
                    Icon(Icons.Default.Person, contentDescription = null, modifier = Modifier.size(18.dp), tint = MaterialTheme.colorScheme.onSurfaceVariant)
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "Continue as Guest",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                    )
                }
            }
        }
    }
}

@Composable
fun ProfileAvatarImage(
    userProfilePicState: String,
    modifier: Modifier = Modifier,
    placeholderSize: androidx.compose.ui.unit.Dp = 20.dp
) {
    if (userProfilePicState == "img_avatar_cross") {
        androidx.compose.foundation.Image(
            painter = androidx.compose.ui.res.painterResource(id = R.drawable.img_avatar_cross),
            contentDescription = "Profile Picture",
            contentScale = ContentScale.Crop,
            modifier = modifier.fillMaxSize()
        )
    } else if (userProfilePicState == "img_avatar_dove") {
        androidx.compose.foundation.Image(
            painter = androidx.compose.ui.res.painterResource(id = R.drawable.img_avatar_dove),
            contentDescription = "Profile Picture",
            contentScale = ContentScale.Crop,
            modifier = modifier.fillMaxSize()
        )
    } else if (userProfilePicState.isNotEmpty()) {
        androidx.compose.foundation.Image(
            painter = rememberAsyncImagePainter(userProfilePicState),
            contentDescription = "Profile Picture",
            contentScale = ContentScale.Crop,
            modifier = modifier.fillMaxSize()
        )
    } else {
        Icon(
            imageVector = Icons.Default.Person,
            contentDescription = "No Profile Picture",
            tint = MaterialTheme.colorScheme.onPrimaryContainer,
            modifier = Modifier.size(placeholderSize)
        )
    }
}

@Composable
fun PasswordStrengthMeter(password: String, modifier: Modifier = Modifier) {
    if (password.isEmpty()) return
    val hasLength = password.length >= 6
    val hasUpper = password.any { it.isUpperCase() }
    val hasDigit = password.any { it.isDigit() }
    val hasSpecial = password.any { !it.isLetterOrDigit() }

    val score = listOf(hasLength, hasUpper, hasDigit, hasSpecial).count { it }
    val (label, color, progress) = when (score) {
        1 -> Triple("Weak Password", Color(0xFFEF5350), 0.25f)
        2 -> Triple("Fair Password", Color(0xFFFFA726), 0.50f)
        3 -> Triple("Strong Password", Color(0xFF66BB6A), 0.75f)
        else -> Triple("Unbreakable", Color(0xFFFFD700), 1.0f)
    }

    Column(modifier = modifier.fillMaxWidth().padding(top = 4.dp)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text("Password Strength:", fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
            Text(label, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = color)
        }
        Spacer(modifier = Modifier.height(4.dp))
        LinearProgressIndicator(
            progress = { progress },
            modifier = Modifier.fillMaxWidth().height(4.dp).clip(RoundedCornerShape(2.dp)),
            color = color,
            trackColor = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)
        )
    }
}

@Composable
fun ReaderSettingsModalDialog(
    currentTheme: String,
    currentFontSize: Float,
    currentLineHeight: Float,
    currentFontFamily: String,
    onThemeSelected: (String) -> Unit,
    onFontSizeChanged: (Float) -> Unit,
    onLineHeightChanged: (Float) -> Unit,
    onFontFamilySelected: (String) -> Unit,
    onDismiss: () -> Unit
) {
    Dialog(onDismissRequest = onDismiss) {
        Card(
            shape = RoundedCornerShape(24.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            elevation = CardDefaults.cardElevation(defaultElevation = 8.dp),
            modifier = Modifier
                .fillMaxWidth()
                .padding(8.dp)
                .testTag("reader_settings_modal")
        ) {
            Column(
                modifier = Modifier
                    .padding(20.dp)
                    .fillMaxWidth()
            ) {
                // Header
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Default.FormatSize,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(24.dp)
                        )
                        Spacer(modifier = Modifier.width(10.dp))
                        Text(
                            text = "Reader Settings",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                    IconButton(
                        onClick = onDismiss,
                        modifier = Modifier.size(32.dp).testTag("close_reader_settings")
                    ) {
                        Icon(Icons.Default.Close, contentDescription = "Close", modifier = Modifier.size(20.dp))
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))
                HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                Spacer(modifier = Modifier.height(16.dp))

                // 1. Reading Theme Selection
                Text(
                    text = "Reading Visual Theme",
                    style = MaterialTheme.typography.labelLarge,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.primary
                )
                Spacer(modifier = Modifier.height(8.dp))
                androidx.compose.foundation.lazy.LazyRow(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    val themes = listOf(
                        Triple("Light", Color(0xFFFAFAFD), Color(0xFF1C1B1F)),
                        Triple("Sepia", Color(0xFFFBF0D9), Color(0xFF4A3B2C)),
                        Triple("Dark", Color(0xFF14151E), Color(0xFFE2E2E9)),
                        Triple("High Contrast", Color(0xFF000000), Color(0xFFFFFF00)),
                        Triple("OLED Night", Color(0xFF000000), Color(0xFFC5C9D3)),
                        Triple("Nordic Blue", Color(0xFF0D1B2A), Color(0xFFE0E1DD))
                    )
                    items(themes.size) { idx ->
                        val (tName, bgClr, txtClr) = themes[idx]
                        val isSel = currentTheme == tName
                        Surface(
                            shape = RoundedCornerShape(12.dp),
                            color = bgClr,
                            border = BorderStroke(
                                width = if (isSel) 2.dp else 1.dp,
                                color = if (isSel) MaterialTheme.colorScheme.primary else Color.Gray.copy(alpha = 0.3f)
                            ),
                            modifier = Modifier
                                .width(95.dp)
                                .clickable { onThemeSelected(tName) }
                                .testTag("theme_chip_$tName")
                        ) {
                            Column(
                                modifier = Modifier.padding(10.dp),
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                Text("Aa", fontSize = 15.sp, fontWeight = FontWeight.Bold, color = txtClr)
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(
                                    tName,
                                    fontSize = 10.sp,
                                    maxLines = 1,
                                    fontWeight = if (isSel) FontWeight.Bold else FontWeight.Normal,
                                    color = txtClr.copy(alpha = 0.9f)
                                )
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))
                HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                Spacer(modifier = Modifier.height(16.dp))

                // 2. Font Size Adjustment
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "Font Size",
                        style = MaterialTheme.typography.labelLarge,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary
                    )
                    Text(
                        text = "${currentFontSize.toInt()} sp",
                        style = MaterialTheme.typography.bodyMedium,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary
                    )
                }
                Spacer(modifier = Modifier.height(6.dp))
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(
                        onClick = { if (currentFontSize > 12f) onFontSizeChanged((currentFontSize - 1f).coerceAtLeast(12f)) },
                        modifier = Modifier.size(36.dp).testTag("modal_decrease_font")
                    ) {
                        Icon(Icons.Default.Remove, contentDescription = "Decrease Font Size")
                    }
                    Slider(
                        value = currentFontSize,
                        onValueChange = onFontSizeChanged,
                        valueRange = 12f..34f,
                        steps = 21,
                        modifier = Modifier
                            .weight(1f)
                            .testTag("modal_font_size_slider")
                    )
                    IconButton(
                        onClick = { if (currentFontSize < 34f) onFontSizeChanged((currentFontSize + 1f).coerceAtMost(34f)) },
                        modifier = Modifier.size(36.dp).testTag("modal_increase_font")
                    ) {
                        Icon(Icons.Default.Add, contentDescription = "Increase Font Size")
                    }
                }

                Spacer(modifier = Modifier.height(12.dp))

                // 3. Line Spacing Adjustment
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "Line Spacing",
                        style = MaterialTheme.typography.labelLarge,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary
                    )
                    Text(
                        text = "${String.format("%.1f", currentLineHeight)}x",
                        style = MaterialTheme.typography.bodyMedium,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary
                    )
                }
                Spacer(modifier = Modifier.height(6.dp))
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(
                        onClick = { if (currentLineHeight > 1.2f) onLineHeightChanged((currentLineHeight - 0.1f).coerceAtLeast(1.2f)) },
                        modifier = Modifier.size(36.dp).testTag("modal_decrease_spacing")
                    ) {
                        Icon(Icons.Default.Remove, contentDescription = "Decrease Line Spacing")
                    }
                    Slider(
                        value = currentLineHeight,
                        onValueChange = onLineHeightChanged,
                        valueRange = 1.2f..2.2f,
                        steps = 9,
                        modifier = Modifier
                            .weight(1f)
                            .testTag("modal_line_height_slider")
                    )
                    IconButton(
                        onClick = { if (currentLineHeight < 2.2f) onLineHeightChanged((currentLineHeight + 0.1f).coerceAtMost(2.2f)) },
                        modifier = Modifier.size(36.dp).testTag("modal_increase_spacing")
                    ) {
                        Icon(Icons.Default.Add, contentDescription = "Increase Line Spacing")
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))
                HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                Spacer(modifier = Modifier.height(16.dp))

                // 4. Font Family & Style
                Text(
                    text = "Font Family & Typography",
                    style = MaterialTheme.typography.labelLarge,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.primary
                )
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    val fontFamilies = listOf("Serif", "SansSerif", "Monospace", "Cursive", "Dyslexic")
                    fontFamilies.forEach { family ->
                        val isSel = currentFontFamily == family
                        FilterChip(
                            selected = isSel,
                            onClick = { onFontFamilySelected(family) },
                            label = {
                                Text(
                                    text = when (family) {
                                        "Serif" -> "Serif"
                                        "SansSerif" -> "Sans"
                                        "Monospace" -> "Mono"
                                        "Cursive" -> "Script"
                                        "Dyslexic" -> "Dyslexic"
                                        else -> family
                                    },
                                    fontSize = 12.sp,
                                    fontWeight = if (isSel) FontWeight.Bold else FontWeight.Normal
                                )
                            },
                            modifier = Modifier.testTag("modal_font_chip_$family")
                        )
                    }
                }

                Spacer(modifier = Modifier.height(20.dp))
                Button(
                    onClick = onDismiss,
                    modifier = Modifier.fillMaxWidth().height(46.dp).testTag("save_reader_settings_btn"),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("Done", fontWeight = FontWeight.Bold)
                }
            }
        }
    }
}

